/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20241007-4","meetingId":"r06-c-settlement","date":"2024年10月7日","dateIso":"2024-10-07","committee":"決算特別委員会","time":"午前 ９時３０分～午後 ５時０６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を173件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"２６９ページ区立保育園費、それから２７９ページの私立保育園費に関連する形でお伺いしていきたいと考えています。民間も含めてその担当の課では、モニタリングも含めてどのようにお考えなのか、改めて伺いたいと思います。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"こちら、先日の厚生委員会等でご説明をさせていただいてはおりますが、多くの施設において、確かに収支でマイナスが出ているような状況です。は紹介手数料を払って紹介事業者にお願いするなど、そういった経費がかさんで… やはり赤字部分の原因につきましては、議員おっしゃられるとおり、まず１つはコロナの影響で利用控えがあること。障害者の場合、区独自でグループホームの運営費助成、有資格者助成を行っているところです。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問","question":"私がどうしてこういう保育園の話を出したかというと、公立保育園をどのようにしていくのだと考えたら、延床で１８０坪などという床が出てこないです。後の運営をどうするかということを考えてあげるということをやっていけば、ぜひそこら辺の感覚を、最後お話しを伺いたいと思う。","respondent":"東野福祉計画課長、菅野高齢者福祉課長","answer":"それから、民間の土地というところにつきましては、先日グループホームのオーナー向けの説明会、それから現地見学会なども行ったところです。参加された方から、そういったセミナーなども含めまして… 現在もグループホームの入居者には、家賃の減額を実施した事業者に対して、減額に要した費用を調整するという制度があります。","id":"exchange-002"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"昨年の第３回定例会の一般質問の場で訴えさせていただいた内容ですが、当事者の方々からは大変にありがたいと感謝の声をいただいております。そういったことについて対策は何か検討していることはあるのか、お聞きしたいと思います。","respondent":"松山障害者支援課長","answer":"委員おっしゃられるとおり、１００円券についてはガソリンスタンドでは使えないため共通券化ができず、結果的に分冊になってしまったものです。今後障害者の方のご意見を聞きながら、タクシー、ガソリンスタンドの会社と調整しつつ検討してまいりたいと考えております。","id":"exchange-003"},{"speaker":"ゆきた委員","kind":"質問","question":"都内でも交通系ＩＣカードを活用できるタクシー事業者は、都内大手タクシー４事業者も含め、さらに増えつつあります。改めて交通系ＩＣカードなどでの交付について、区の見解をお聞きできればと思います。","respondent":"松山障害者支援課長","answer":"今現在としましては難しいところですけれども、今後、ＩＣ化の拡大の動向を注視しながら検討してまいります。さらなる利便性の向上に努めていきたいと考えております。","id":"exchange-004"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"品川区は年間４万２,０００円であるのに対して、千代田区が年間４万５,０００円、大田区は全て５万２,０００円です。物価高騰を鑑みて、さらなる助成の増額を要望したいと思いますが、この辺について区の見解をお聞きしたいと思います。","respondent":"松山障害者支援課長","answer":"実際、品川区としましては現在４万２,０００円で、他区はそれ以上、またそれ以下のところもあります。今後物価高騰の動向を鑑みながら、障害者の方のお声もありますので、さらに検討を深めていきたいと考えております。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問","question":"福祉タクシー利用券、４万２,０００円分を使っていたとしても、経済的な逼迫というものがかなり切実な問題というお声は聞いています。この辺についてどう対応を考えていらっしゃるのか、区の見解をお聞きしたいと思います。","respondent":"松山障害者支援課長","answer":"ご利用される介護タクシー、あとリフト寝台付福祉タクシー事業というのを実施しておりまして、一般のタクシー料金と同様としています。費用負担につきましては、今後検討してまいります。","id":"exchange-006"},{"speaker":"ゆきた委員","kind":"質問","question":"介助人は別料金で、介助人は１人に限り半額の助成がされ、事前登録をすることで福祉キャブの活用ができています。福祉タクシー利用券だけではなく、改めて区の見解をお聞きできればと思います。","respondent":"松山障害者支援課長","answer":"迎車料、やはり車椅子を使用される方は必ずかかる費用ですので、そのようなお声も多くいただいております。今後検討してまいりたいと考えております。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"意見","question":"私もこの現場からの、介護タクシーを使えない現実というのは本当に切実な問題だと聞いています。そこに対しての、そこに寄り添うということはできると思いますので、何とぞ区の前向きな対応をとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"山本委員","kind":"質問","question":"２６３ページの奨学金貸付事業、２４９ページの高齢者向けパソコン・スマホ教室、２５５ページの子育て支援情報発信アプリ運用について伺います。大学応援資金の利用者は２３人と記載されていますが、主な使用用途は何か尋ねました。","respondent":"飛田子育て応援課長","answer":"主な使用用途ですが、学習関連で塾の費用が一番多くなっております。次に、学校への施設整備費や修学旅行の積立金となっております。","id":"exchange-009"},{"speaker":"山本委員","kind":"質問","question":"申請時に立てた具体的な目標の達成により、免除となる仕組みとのことですが、昨年度は何人の方が免除になったのでしょうか。免除にならなかった人数を説明するよう求めました。","respondent":"飛田子育て応援課長","answer":"この春高校を卒業しまして、免除申請があった方の人数ですが、１６名でした。申請のあった方は書類選考や面接を行い、１６人全員が返還免除となりましたので、免除にならなかった方はいらっしゃいません。","id":"exchange-010"},{"speaker":"山本委員","kind":"質問","question":"次に、介護人材確保定着事業について伺います。品川介護福祉専門学校の入学者の定員と４月の入学者、本年度開始した区独自の介護職向け居住支援手当の対象者数について説明するよう求めました。","respondent":"菅野高齢者福祉課長","answer":"そして、区独自の介護職員向け居住支援手当につきましては、約６,０００人の方が区内には勤めているということが分かりました。そのうちこの手当自体が実労働時間が週２０時間以上で月８０時間以上と決まっておりますので、対象者は約４,０００人ということになっております。","id":"exchange-011"},{"speaker":"山本委員","kind":"質問・要望","question":"令和５年度の補助金を利用した法人の利用実績を確認しますと、品川区では２つの法人だけでした。それぞれ区のご見解を伺います。","respondent":"菅野高齢者福祉課長","answer":"東京都が実施している介護職員奨学金返済育成支援事業に関するご質問についてお答えをします。区としては、あとは実務者研修費の補助などをさせていただいて、多様な手法で介護人材の確保に努めていきたいと考えています。","id":"exchange-012"},{"speaker":"山本委員","kind":"質問","question":"次に、福祉人材確保の中で、外国人介護職員確保のための住居支援について伺います。減少理由と、本事業に対する認識、課題があれば課題と、今後の方針について説明を求めました。","respondent":"菅野高齢者福祉課長","answer":"ファミーユ西品川を活用した外国人介護職員の居住支援確保ということで、１戸２人入居で現在６戸、１２人分を貸出しをしています。","id":"exchange-013"},{"speaker":"山本委員","kind":"質問・要望","question":"さらに今後、日本国内で外国人介護職員の取り合いになるので、他自治体に先行し労働できる環境整備を進めていくべきであるとのご要望を伺いました。外国人介護職員の住居支援の拡大と、労働従事者と家族の生活環境の支援の充実を要望し、次の質問に参ります。","respondent":"樫村高齢者地域支援課長","answer":"スマホよろず相談につきましては７４回実施しまして、６２６名の方にご参加をいただいたところです。区としましても大変人気で、区民ニーズが高い事業であると認識をしています。","id":"exchange-014"},{"speaker":"山本委員","kind":"提案","question":"対象者が９,０００人いて、今の年間３００人ペースだと３０年かかるというので、大幅なペースアップの要望をいたしました。繰り返しの提案となりますが、よろず相談窓口の増加など、より多くの方々にスマホを使って習っていただけるような環境づくりを要望いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"２３１ページ精神障害者地域生活支援センター運営費について、２３７ページ障害者福祉手当等支給事務について伺います。その果たしている役割をどう評価しているのか、その意義について区の認識を伺いたいと思います。","respondent":"松山障害者支援課長","answer":"精神障害者地域生活支援センター「たいむ」の役割です。そちらから居場所につなげていくというような、そしてサービスにつなげていくというような、大変重要な入り口の役割を持っていると考えております。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"家族会のほうからは、区内にこちら一か所のみの地域生活支援センターということで、増設を求める声が届いております。この施設の増設を検討して具体化すべきだと思うのですけれども、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"精神障害者地域生活支援センターは、たいむのほかにも、障害児者総合支援施設の中にもあります。全ての障害の方にご利用いただける地域活動支援センターとなっており、区としては２か所あるという認識があります。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ荏原地域のほうの増設もお願いしたいのですが、検討するべきだと思うのですけれども、いかがでしょうかという質問をします。特にその線引きが難しいという点ですとか、あるいは他の障害との兼ね合いについてとはどういう意味なのか、伺いたいと思います。","respondent":"松山障害者支援課長","answer":"精神障害者のサポート２４というところが戸越にありますけれども、そちらのほうで相談、今後検討してまいりたいと考えております。手当についてはどういった経済的な支援が必要かについては、幅広く今後また引き続き検討してまいりたいと考えております。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"２級の方のほうが幅広いというのは、もう幅広いわけですから、もうすべて２級だったら全部出したほうが私はいいと思うのです。１級の方だけですから、少なくとも２級まで拡大したとしても４８.４３％の方が対象になるということですから、最後にいかがか尋ねました。","respondent":"松山障害者支援課長","answer":"委員がおっしゃられる人数比や支給額のみだけで考えることではございませんので、総合的にこちらのほうは検討していきたいと考えております。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"私からは、２２７ページ重層的支援体制整備検討費、支え愛・ほっとステーション事業、２４７ページ認知症高齢者支援事業についてお伺いをいたします。令和７年度から本格実施ということになりますけれども、また職員向けの対応マニュアルなど、現時点でどのように進んでいるのかをお伺いをいたします。","respondent":"東野福祉計画課長","answer":"属性を問わない支援、参加支援、地域づくりに向けた支援の３つの支援を一体的に実施するという方針の下。この後、管理職向けの研修も順次進めてまいりまして、この重層的支援体制整備事業の人材の育成という面では図っていかれるように対応してまいります。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"令和５年度の事務事業評価シートになりますと、２４件と約半分にその目標件数を落としているのですけれども、その理由をお知らせください。この指標の対応方針を決定したケースということを指標にしていいのか、その辺り、今後のその評価のあり方についてお伺いをしたいと思います。","respondent":"東野福祉計画課長","answer":"こちらにつきましては、これまで令和４年度から支援会議と呼ばれる会議で、実際に行われるであろう件数を見込んだものです。支援会議で対応方針を決定したケース、区としてその支援会議の中で対応方針を決定した、こちらは既に支援が行われているというもので。","id":"exchange-021"},{"speaker":"筒井委員","kind":"意見","question":"は利用に月額３００円かかるということが書いてあります。一方で、障害者支援課で作成しているパンフレットでは、利用料金はかからないと書いてあるのですけれども、その理由をお知らせくださいとの意見を述べました。","respondent":"東野福祉計画課長","answer":"救急通報代理システムですが、こちらにつきましては、本年４月からそれまでかかっていました３００円の利用料金を無償化したものです。委員がご覧いただいているパンフレットの作成時期が、もしかしたら昨年度のものかと思われます。","id":"exchange-022"},{"speaker":"筒井委員","kind":"質問","question":"その辺りのご見解と、また、一方でこの支え愛ほっとステーション事業の利用者が、結構常に特定の方に偏ってしまっているということはないのか。その辺り、利用者の状況というのをお伺いをしたいと思います。","respondent":"東野福祉計画課長","answer":"現在令和５年度末におきましては、合計５３６名の地域支援員の方がいらっしゃいます。新しい方もどんどん増えてきているような状況ですので、特定の方だけではないと理解をしています。","id":"exchange-023"},{"speaker":"筒井委員","kind":"質問・要望","question":"本当に需要がある今後もっと増えてくる事業だと考えていますので、ぜひ周知のほうも徹底していってほしいと求めました。現在周知方法についてどのようになっているのか、最後にお伺いいたします。","respondent":"東野福祉計画課長","answer":"こちらの支え愛ほっとステーション事業につきましては、区のホームページのほか、委託しております品川区社会福祉協議会のホームページ、または区の広報紙などでも特集号を組んだり、それから各地域センターでのぼりを立てたり、そういうことでの周知を図っているところです。","id":"exchange-024"},{"speaker":"せらく委員","kind":"確認","question":"こちらについていま一度確認させてください。延長保育の利用登録には出産要件で登録が可能と確認したのですが、こちらも認識が合っていますか。","respondent":"芝野保育入園調整課長","answer":"当時から、令和５年度より妊娠出産と育休を分けて、妊娠出産の場合は標準時間もしくは短時間をお選びいただけるというふうにご案内をしています。延長で夜間保育についても、同様に選べる形になっております。","id":"exchange-025"},{"speaker":"せらく委員","kind":"質問・要望","question":"確認いたしました。区としてはどのような思いで、産休中は標準時間を選択できるようにしたのか尋ねました。","respondent":"芝野保育入園調整課長","answer":"現場のほうもなかなかそれを理解できてないという現状も考えられますので、こちらは周知を徹底してまいりたいと思います。標準時間、短時間ともちろん選べるという形になりますが、個別に相談に乗りながら対応を図ってまいりたいと思います。","id":"exchange-026"},{"speaker":"せらく委員","kind":"質問","question":"声を伺っていると、対応している園もあれば、まだそのまま短時間でと保育園からお願いをされている方もいらっしゃると感じます。保護者の皆さんが萎縮することなく選択できるように、こちらも各園への周知をお願いしたいと思うのですけれども、いかがか尋ねました。","respondent":"芝野保育入園調整課長","answer":"来年４月から年齢制限を撤廃しまして、育児休業期間中は保育園の利用可能になるですが、こちらは短時間のご利用としています。育児休業中の標準時間選択制の導入につきましては、今後の運営状況や他区の動向を踏まえながら検討を進めてまいりたいと思います。","id":"exchange-027"},{"speaker":"せらく委員","kind":"確認","question":"入園関係でもう一つなのですけれども、保育園入園書類の中に、今、希望園を８園まで書くことができることを確認しています。記入欄を増やしてほしいというような声があったのですけれども、改めて増やした理由をお聞かせいただけると助かります。","respondent":"芝野保育入園調整課長","answer":"入園申請書の書式で６園から８園に増やした経緯ですが、平成２８年４月入園から、それまで６園だったものを８園に変更しています。その背景としましては、平成２７年度に子ども・子育て支援新制度が創設されまして、記載できる園を増やす対応をしたものです。","id":"exchange-028"},{"speaker":"せらく委員","kind":"確認","question":"在宅子育て支援として、令和５年度の一時預かりについて２万１,７７１人の利用実績があると確認いたしました。こちらについてご説明ほしいと求めました。","respondent":"藤村子ども育成課長","answer":"オアシスルームは在宅子育て支援、リフレッシュというところ目的に、生活支援型の一時保育として運営してきた経緯があります。その間の預かり、オアシスルームは主に在宅子育て支援という形で、現在運用させていただいているところです。","id":"exchange-029"},{"speaker":"せらく委員","kind":"質問","question":"幼稚園の長期休みという部分では、そうなのですけれども、区分と実情というところが今マッチしていない部分があるかなと考えています。そういったところを一度調査などをしていただけたら助かるのですけれども、いかがか尋ねました。","respondent":"藤村子ども育成課長","answer":"利用区分というか利用方法のお話かと思います。現状マッチしていないところといいますか、区民の方からも、例えば保育園に通われている方で、土曜日……終わります。","id":"exchange-030"},{"speaker":"横山委員","kind":"質問","question":"私からは、２６１ページ児童相談所移管推進事業、２６７ページ子どもの未来応援事業についてお伺いいたします。１点目に、子どもの未来応援事業についてお伺いいたします。","respondent":"飛田子育て応援課長","answer":"しあわせ食卓事業についてです。子どもの食の支援を進めるにあたり、住宅入居支援等につなげて、最終的には自立を支援しております。","id":"exchange-031"},{"speaker":"横山委員","kind":"質問・要望","question":"スペシャルボックスが届いたときに開けるのは大体子どもたちですから、例えばケーキ・お菓子を上にして梱包するなどの工夫をしているようです。","respondent":"飛田子育て応援課長","answer":"昨年度は食品配送２回のほか、企業寄附により日用品の発送やお米なども発送することができました。引き続き、あなたが大切なのですという思いを込めながら実施したいと思います。","id":"exchange-032"},{"speaker":"横山委員","kind":"質問・要望","question":"通学したいかどうか意向を原則確認しているのは、学校で教育を受ける権利が十分に保障されているとは言えない状況が浮かび上がったとあります。現在一時保護所において、子どもたちに対して通学の意向をどのように確認していますか尋ねました。","respondent":"金子一時保護担当課長","answer":"保護児童の通学はできる限り実施していく方針で、通学を前提として、送迎の職員体制や通学費用を組んでおります。すべての子どもにはなりませんけれども、子どもの意向を聞き取り、個々の状況を踏まえ通学を実施していきます。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"ウエルビーイングを目指す品川区が、東京都、さらに日本を導いて子どもたちの権利保障に尽くしていただきたいと考えています。これからできる限り子どもたちが通学することのできる体制整備をお願いしたいと思いますが、今後の見通しを説明するよう求めました。","respondent":"金子一時保護担当課長","answer":"先ほど申し上げたとおり、通学の体制というのは基本的に組んでいるつもりです。そういった様々な調整をしていって、通学自体を当たり前にしていくと、そういったことを考えていきたいと考えております。","id":"exchange-034"},{"speaker":"横山委員","kind":"質問・要望","question":"東京都で視察した際に、葛飾区だったか豊島区等でもお伺いしたのですけれども、課題としてあるとお聞きしました。様々な手法で子どもたちの教育の権利の保障について、品川区として進めていってほしいと求めましたので、最後に一言お願いします。","respondent":"金子一時保護担当課長","answer":"様々な形で登校、それから教育の保障、児童相談所の中で通学できていない子どもたちに対し、元教員の学習指導員が保護所内で教育を行っていまして、今タブレットの使用についても今後検討していきたいと考えています。","id":"exchange-035"},{"speaker":"えのした委員","kind":"質問","question":"私からは、２４７ページ認知症理解促進事業、２４３ページ熱中症等予防対策についてお伺いいたします。これには何か意図があるのでしょうか、お伺いいたします。","respondent":"樫村高齢者地域支援課長","answer":"シルバーフェスタなど、どなたでも参加できるイベントと抱き合わせで実施をしまして、気軽に足を運んでいただけるように工夫に努めているところです。","id":"exchange-036"},{"speaker":"えのした委員","kind":"質問","question":"さらに最後、これは防災備蓄品のお土産付きというのですか。改善の余地があると思いますが、いかがか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"こちらも、なるべくやはり多くの方に興味を持っていただきまして、気軽に足を運んでいただきたい事業ですので、今後は会場とも協議を重ねて、できる限りのＰＲなどをいたしまして、区民の方の目にとまるように工夫をしていきたいと考えています。","id":"exchange-037"},{"speaker":"えのした委員","kind":"質問","question":"対象者１,０００人に向けてこちらの受診をされて認知症と疑われるような結果が出た方には、その後どのように対応しているのか説明を求めました。","respondent":"樫村高齢者地域支援課長","answer":"それから認知症フレイル予防事業のご案内をするほか、もの忘れ検診ですとか伴走型支援事業のくるみ相談室の周知を図っているところです。結果が思わしくなかった方につきましては、かかりつけ医等の医療機関の受診を促しています。","id":"exchange-038"},{"speaker":"えのした委員","kind":"質問","question":"それを思い出して、あと３つの動物の中からちょっと仲間が違うのではないかと思うものを１つ答えるですとか、本当に一生懸命覚えました。それでもの忘れ検診、こちらの受診率の推移、また受診率を上げるために工夫等を何かしているのか説明を求めました。","respondent":"樫村高齢者地域支援課長","answer":"もの忘れ検診につきましては、令和４年度に事業を開始をしたところです。併せて広報しながわ等でも周知を頻繁に図ったりですとか、受診機関を増やすなどの対応をしながら、区としても積極的に対応しています。","id":"exchange-039"},{"speaker":"えのした委員","kind":"質問","question":"私も先日質問しましたけれども、しながわ水族館無料入場券、これは大変魅力的だと思います。事業継続、かつ対象者の拡大などもしていただいて、区として今後の展望などどのようにお考えか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"今後の方針についてです。こちらにつきましては、また品川区医師会・荏原医師会の先生方からの専門的なご意見も頂戴しながら、慎重に検討してまいりたいと考えています。","id":"exchange-040"},{"speaker":"えのした委員","kind":"質問","question":"続きまして、コロナ禍ではシルバーセンターやゆうゆうプラザの利用が一部制限されるなどして、利用人数が下がったと認識をしております。令和５年５月にコロナが５類に移行されましたが、シルバーセンターやゆうゆうプラザの利用人数に変化はありましたでしょうか示すよう求めました。","respondent":"樫村高齢者地域支援課長","answer":"同じくゆうゆうプラザにつきましても増加しておりまして、令和４年度と比較しまして３万６,１８９名増の１０万９,８０４名の利用がございました。も、今後さらに事業の充実等も図っていきまして、利用者が増加していくものと見込んでいるところです。","id":"exchange-041"},{"speaker":"えのした委員","kind":"質問","question":"今年の夏は本当に昨年に引き続いて猛暑日が多く、特に高齢者の方などは熱中症が懸念されました。シルバーセンターやゆうゆうプラザなどの高齢者が多く集う熱中症対策は、どのように行っていますでしょうか示すよう求めました。","respondent":"樫村高齢者地域支援課長","answer":"具体的には避暑シェルターののぼり旗を館内の前に設置しまして、冷房を効かせた館内での麦茶の提供を行ってあります。８月の上旬からシルバーセンターの１室を避暑室として開放するとともに、高齢者の方をはじめとした区民の皆様に熱中症対策を行ったところです。","id":"exchange-042"},{"speaker":"えのした委員","kind":"質問","question":"今年の避暑シェルターの利用者数、こちらはどのくらいだったのか。今回、シルバーセンターで使った避暑室は、ふだんこちらはどのように利用されているのか説明を求めました。","respondent":"樫村高齢者地域支援課長","answer":"もともと８月につきましてはマッサージサービスがお休みの月であったということで活用したところです。９月以降におきましても、マッサージサービスで使用する日以外の日を避暑室として開放しています。","id":"exchange-043"},{"speaker":"えのした委員","kind":"意見","question":"大変有効的な使い方だと理解をいたしました。これから来年度の展開などがありましたら、お考えをお知らせくださいとの意見を述べました。","respondent":"樫村高齢者地域支援課長","answer":"こちらにつきましても、今年度の利用状況ですとか利用者のお声、そして現場からの意見等を踏まえながら、総合的に検討していきたいと思ってあります。","id":"exchange-044"},{"speaker":"えのした委員","kind":"質問","question":"これは私ももちろん利用させていただいたのですけれども、避暑シェルターの利用対象者、こちらについてもお知らせいただけますでしょうか。高齢者だけなのか、また近隣の方であれば誰でもいいのか、その辺を示すよう求めました。","respondent":"樫村高齢者地域支援課長","answer":"利用対象者ですけれども、高齢者に限らず地域の方、小学生などどなたでも利用可能です。現場から、小学生などが涼を取りに、また麦茶を飲みに施設へ立ち寄ることも頻繁にあると聞いております。","id":"exchange-045"},{"speaker":"えのした委員","kind":"確認","question":"小学生の熱中症対策にも利用できるということで、利用者制限なしで利用可能ということを確認できました。これは避暑シェルターをきっかけに、多くの多世代交流の場につながると考えますが、区のご見解を示すよう求めました。","respondent":"樫村高齢者地域支援課長","answer":"区としても、区民が利用しやすい避暑シェルターにしていきたいと考えています。","id":"exchange-046"},{"speaker":"塚本委員","kind":"質問","question":"私からは、それから２３３ページ地域生活支援事業、こちらは障害者の住宅あっせんというようなことについて伺いたいと思います。この２つの窓口に配備をしたときの区民の反応等を伺いたいと思います。","respondent":"樫村高齢者地域支援課長","answer":"８月上旬に、障害者支援課とそれから高齢者地域支援課のほうに設置いたしまして、１７名の方にアンケートにご協力をいただいたところです。","id":"exchange-047"},{"speaker":"塚本委員","kind":"質問・要望","question":"在宅介護支援センター、それから支え愛ほっとステーション、このように３つ並べてあります。ただ、例えば税務課とか戸籍住民課とか、こういったところへの配備についての考えをお聞かせほしいと求めました。","respondent":"樫村高齢者地域支援課長","answer":"先ほど委員のおっしゃられました今回の補正予算の３５台の中に、総合窓口予備用としまして５台を含んでおります。そういったところへの貸出しを目的としまして５台計上しておりますので、今後の展開等も含めて考えていきたいと考えています。","id":"exchange-048"},{"speaker":"塚本委員","kind":"質問・要望","question":"今後ともよく注視をしていただいて、適宜配備を進めていってほしいと求めました。次に、障害者福祉課に関わるところで質問させてほしいと求めましたけれども、課題として捉えていらっしゃるのかお伺いしたいと思います。","respondent":"松山障害者支援課長","answer":"立ち退き要求を受けていること、助成要件の内容について緩和いたしました結果、今年度お１人の方が礼金等の助成についてご利用はいただいております。","id":"exchange-049"},{"speaker":"塚本委員","kind":"質問","question":"１つ実績が出た、１件ということは、まだまだこれを利用していただく機会を増やしていかなくてはいけないと思います。その辺の認識についてはどうなのでしょうかというところと、区として支援というのは考えているようなところがあるのか、お伺いしたいと思います。","respondent":"松山障害者支援課長","answer":"令和３年度から住宅課が実施している住宅確保要配慮者入居促進事業と連携しながら現在行っております。例えば伴走型の居住支援が必要ではないかということを考えておりまして、支援策については今後検討してまいりたいと考えています。","id":"exchange-050"},{"speaker":"塚本委員","kind":"質問・要望","question":"今支援策を検討していただけるということで、ぜひここはかねがね会派としても高齢者も含めて課題と捉えていたところですので、ぜひ進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"おぎの委員","kind":"質問","question":"こちらは定員が１７名ですが、６か月たちまして、現在の入所の状況はいかがでしょうか。入所された方の障害区分の平均値は今のところどれくらいか尋ねました。","respondent":"松山障害者支援課長、佐藤障害者施策推進課長","answer":"私からは、出石つばさの家の入居状況についてご説明申し上げます。障害支援区分については、区分３が２人、区分２がお１人となっております。今、小山七丁目のグループホームと、それから戸越四丁目のグループホームについて、区として整備を予定しています。","id":"exchange-052"},{"speaker":"おぎの委員","kind":"質問","question":"続きまして、国民健康保険社会保障・税番号制度システム整備費補助金からお聞きいたします。現在品川区民のマイナンバーカードについて、マイナ保険証としての登録率、医療機関での使用の割合について説明を求めました。","respondent":"池田国保医療年金課長","answer":"１点目のマイナカードの取得率、それとマイナカードの利用率についてお答えします。これは今年の４月の状況です。","id":"exchange-053"},{"speaker":"おぎの委員","kind":"確認","question":"もうすぐ紙の保険証がなくなり、強制的にマイナンバーカードと一体になるような印象を受けますが、利用する・しないはあくまで個人の選択です。今年２０２４年２月の厚生労働省からの通知により、送られてくる資格確認書を医療機関で使用できるとのことですが、説明を求めました。","respondent":"池田国保医療年金課長","answer":"マイナカードの解除につきましてはまだ国のほうから通知が来ておりませんので、区としての方針が固まってないところです。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、２８４ページの生活保護費に関わって、エアコン設置など熱中症対策、そして２３３ページ障害者介護給付事務の同行援護について伺います。エアコンが壊れた際にも設置できるように支援をしてほしいと求めましたが、いかがか尋ねました。","respondent":"豊嶋生活福祉課長","answer":"本年度も令和６年５月３１日だったかと思いますが、エアコン設置についてはこのようにしなさいということが書かれてあります。補修については国からは書かれていませんので、そこについては現在区として何かできるものではございません。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"国からは特に出ていないということですけれども、実際問題、今エアコンなしでこの夏生活をしていくということは、本当に困難だと思います。国にも働きかけてほしいと求めましたし、その中で区としてできることをやってほしいと求めましたが、いかがでしょう。","respondent":"豊嶋生活福祉課長","answer":"一定の基準を満たせない、要は条件から外れた方に関しましては社会福祉協議会の貸付け等々を今適切にご案内をしています。そういった対応を引き続きしてまいりたいと考えております。","id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"夏季加算の実施を国に要望すべきです。併せて、国が実施するまでは区が独自に支援をすべきだと思いますが、いかがか尋ねました。","respondent":"豊嶋生活福祉課長","answer":"生活保護につきましては、国からの委託事務第１号法定受託事務ですので、区が保護費に加えて何か特別な加算をするということは、現在できかねます。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこはぜひ国に強く要望してほしいと求めましたし、実施してほしいと求めましたが、改めて伺いたいと思います。は低所得者が安心してエアコンを使用できるように、電気代の補助をしてほしいと求めましたが、いかがか尋ねました。","respondent":"豊嶋生活福祉課長、菅野高齢者福祉課長","answer":"収入認定という考え方もございまして、それから国にも一つ一つ確認を取って許可というか、認めていただかなくてはいけないということになります。そうしたことから考えまして、法定受託事務というところから… 区のほうでは民生委員やケアマネジャー等が戸別訪問することによって、高齢者に注意喚起を直接行うようにしています。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり国にもしっかり求めていただいて、この収入認定もされないような仕組みもぜひ考えていただきたいと、これは要望しておきたいと思います。現在どうなっているのか、もうこれは始まっているのか、始まっている場合はこの間の実績を伺います。","respondent":"松山障害者支援課長","answer":"重度障害者就労支援特別事業の実施状況です。本年７月から開始いたしまして、９月末時点で３人の方がご利用されていらっしゃいます。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"必要な方がしっかり利用できるように、事業所に周知徹底をしてほしいと求めましたが、いかがでしょうか。急な病気や親類の不幸などに対応できるようにしてほしいということなのですけれども、緊急時のガイドヘルパーが利用できる、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"重度障害者就労支援事業の周知につきましては、同事業開始にあたりまして団体や相談事業所へお知らせをしています。実際には相談支援員がご相談をお伺いし、同行事業者へのサービス提供を依頼し、登録されているヘルパーから探しているという状況です。","id":"exchange-060"},{"speaker":"ひがし委員","kind":"質問・要望","question":"入所を検討していた方々からは、重度の入居が難しいのではないか、入居調整指数の採点方法も見直してほしいとのご要望をお受けいたしました。担当課に確認をさせていただいたところ、点数は一緒でも区分６から優先的に面接をして進めている状況だとは確認をさせていただきましたが。","respondent":"松山障害者支援課長","answer":"入居調整指数の項目では、障害支援区分のほかに手帳の有無、それから品川区への住民登録期間、ご家族の状況等を総合的に点数化いたしました。","id":"exchange-061"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ検討をしてほしいと求めました。グループホームの入居申込面接の際には、利用者をよく理解している相談支援専門員の参加も有効だと考えますが、その点についてはいかがか尋ねました。","respondent":"松山障害者支援課長","answer":"特段、実際にグループホームを希望されているご家族の方から、ご希望どおり同席いただいて面接をしたという事例はあります。ただ、必ずしも障害者相談員を同席させたほうがいいのかどうかにつきましては、ご本人やご家族のご希望によるものだと考えております。","id":"exchange-062"},{"speaker":"ひがし委員","kind":"提案","question":"向こうからの提案だけではなくて、こちらからもどうですかというようなお声かけをしていただけるのもいいのかなと思います。ぜひ、その点については要望しますので、ご検討くださいとの意見を述べました。","respondent":"松山障害者支援課長","answer":"児童発達支援放課後等デイサービスのうちで、重症心身障害児または医療的ケア児に対応可能な障害児通所支援事業所に。令和６年度、本年度につきましては医療的ケア、重症心身障害児に対応事業所が２か所増えているところです。","id":"exchange-063"},{"speaker":"ひがし委員","kind":"質問・要望","question":"この助成、年々利用件数が増えるように、区としてもお声がけ、周知を徹底してほしいと求めました。その点について、区の取組、見解を、答えるよう求めました。","respondent":"佐藤障害者施策推進課長","answer":"区のほうは東京都の方針を受けまして、運営ですとか利用者の支援、会計などが適正に行われているか随時確認をしております。開設から運営について指導助言を行いまして、サービスが適切に提供されるよう、引き続き体制を整えてまいりたいと考えております。","id":"exchange-064"},{"speaker":"ひがし委員","kind":"質問・要望","question":"以前から、品川区では医療的ケア児等への支援に関わる情報をまとめた冊子等がなく、作成をしてほしいと要望しています。利用する際の効果についても、答えるよう求めました。","respondent":"中島保育施設運営課長","answer":"こちらに関しましては、医療的ケアのお子さんが入園を検討するにあたりまして、まとまった資料が欲しいというお声をいただいていたところです。","id":"exchange-065"},{"speaker":"ひがし委員","kind":"質問・要望","question":"前回は福祉部長からも情報発信については重要だと考えている、医療的ケア児連絡会等で意見を伺いながら検討していくというようなご答弁がありました。ぜひこのようなサポートブックについても私は必要性を感じておりますので、作っていただきたいと考えていますが、ご見解を説明するよう求めました。","respondent":"松山障害者支援課長","answer":"ライフステージを通じて網羅した共通のサポートブックというものの必要性を感じておりますので、庁内各課連携して作成する方向で考えております。作成にあたっては、医療的ケア児等の関係機関の連絡会の委員の方々から挙がった意見を頂戴しながら進めていきたいと考えております。","id":"exchange-066"},{"speaker":"ひがし委員","kind":"質問・要望","question":"１点、その中に災害というところも入れていただきたいとこちらは要望させてほしいと求めました。災害というところについてはまた別の機会に質問させていただこうとは思っておりますが、その点についてもぜひ検討を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問・要望","question":"２４５ページ、高齢者福祉施設支援事業に関連して、南大井のさくら会について、１階玄関隣の「ぽこあぽこ」の再開を求めて質問したいと思います。区の支援も検討していただいて、何とか再開をと思うのですけれども、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"現在はさくら会が設置した自動販売機、介護予防の事業の利用者などが、くつろぎの談笑の場として利用をしているというところもあります。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと月１回ですけれども、職員の方が夜７時頃まで、これもとても好評だったと伺っております。そのような場があることの意義というのでしょうか、何とか再開できる形を改めて求めたいと思いますけれども、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"年４回日曜の午後、毎回１０人から２０人ほどの参加者がいて、好評を得ているとも聞いております。特段の問題もないというさくら会の方針でもありますので、この場所においては違う形で今運営していただいているということで捉えております。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問・要望","question":"障害がある方々も含めて、ぜひ再開をと声を伺っておりますので、強く要望して終わりたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"こしば委員","kind":"質問","question":"私からは、２４９ページ、高齢者向けパソコン・スマホ教室についてお伺いいたします。ワンポイント編のほうが３倍近い費用がかかっておるわけですが、その値段設定といいますか、理由についてお聞かせ願いたいと思います。","respondent":"樫村高齢者地域支援課長","answer":"１回当たり５万円ですけれども、個別に対応ができるように、講師のほかスタッフが複数名必要となるところです。そのため、事前準備や、当日における人件費が多くかかるために、委託料の単価が高くなっているところです。","id":"exchange-071"},{"speaker":"こしば委員","kind":"質問・要望","question":"個別具体的な対応が求められ、そういった事情があるということで、この値段設定であったということは承知をいたしました。意図するそもそもの目的というようなものがどのようなものであったのか、また、実際の当時の稼働率についてお聞かせ願いたいと思います。","respondent":"樫村高齢者地域支援課長","answer":"意図ですけれども、一般的な講座では網羅していない内容を実施して、多様化する区民ニーズを満たすことを目的として実施したところです。年間通して１２回、全体で開催を予定したところですけれども、応募がなく中止とした回数も４回ほどございました。","id":"exchange-072"},{"speaker":"こしば委員","kind":"質問","question":"年間通して１２回やったけれども、途中でなかなか人が集まらずに中止をしてしまったときもあったということをお聞きいたしました。その事業を見直す１つの大きな判断の基準となると考えますが、見直しをされてきたのか、教えていただけますか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"委員ご指摘の稼働率を踏まえた結果なのですけれども、先ほど委員もおっしゃられましたとおり、今年度よりワンポイント教室は廃止しています。需要の高かった入門コース、Ａｎｄｒｏｉｄの入門コースの実施回数を増やしまして、増加する区民ニーズのほうにも対応しています。","id":"exchange-073"},{"speaker":"こしば委員","kind":"質問","question":"そういった地理的な、何ですか、環境を整えることも必要ではないかなと考えています。ぜひこれを区内全域に展開されていくことをお願いしたいと思いますが、見解を説明するよう求めました。","respondent":"樫村高齢者地域支援課長","answer":"高齢者向けのスマホ教室のニーズの高まりを受けまして、令和４年度から初めてのスマホ体験教室・よろず相談を開始したところです。それから令和６年度には平塚橋ゆうゆうプラザの会場を追加しまして、実施場所の拡大を行いながら、現在区内の５会場にて実施しています。","id":"exchange-074"},{"speaker":"こしば委員","kind":"質問","question":"それで今ご答弁の中にもありましたけれども、この初めてのスマホの体験教室や、またスマホのよろず相談についてお聞きしたいと思います。そもそもスマホを持っていない方も対象にしたものと伺っておりますが、どういった声があったのかということをちょっと教えてほしいと求めました。","respondent":"樫村高齢者地域支援課長","answer":"お持ちでない方にも参加いただけるように、所有されていない方へ、教室実施期間中１か月間の貸出しを行っております。まずはそこでお試しをいただいて、今後スマホをご自分で購入されるのかどうかというところをご判断いただくような材料としています。","id":"exchange-075"},{"speaker":"こしば委員","kind":"質問","question":"今の答弁で、１か月間無料で貸出しをして、また、自宅でも無料でインターネットを使えるという答弁のほういただきまして、ありがとうあります。その体験教室を受けた声、幾つかありましたら教えてほしいと求めました。","respondent":"樫村高齢者地域支援課長","answer":"インターネットでしか予約できない演劇の鑑賞に行けたといったような、うれしいお声をいただいているところです。","id":"exchange-076"},{"speaker":"こしば委員","kind":"質問・要望","question":"この事業を含めて、デジタルデバイド、本当に全庁的に取り組んでいただきたいことと思います。予算の規模の増大も含めて、今後全庁的に取り組んでいただきたいことを願いまして、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"やなぎさわ委員","kind":"確認","question":"ただ、捕捉率が２０％前後と言われて、要は生活保護水準以下の生活をしている方の８割の方が実は申請していないという問題がはらんでおります。金銭的な援助ができないかということを区のほうで確認をするという作業になるのですけれども、ここ数年の推移はどれぐらいになっているのか尋ねました。","respondent":"豊嶋生活福祉課長","answer":"扶養照会をした世帯、４４０世帯へ生活保護を開始しておりまして、うち１９７世帯に扶養照会をしました。今手元にある数字で４年前の数字が一番古いのですが、４年前の扶養照会率は５９.７％となっております。","id":"exchange-078"},{"speaker":"やなぎさわ委員","kind":"質問","question":"２０２０年、２０２１年はゼロということでした。１％未満になってしまっているこの扶養照会をかけることによって、何か今、時間を割いている業務というものは具体的に何かありますか尋ねました。","respondent":"豊嶋生活福祉課長","answer":"令和３年の２月の段階で、扶養照会をしても、しなくてもいいですよという見解は出されております。様々な方がこちらのほうにお見えになりますので、本当にこうしたからこうという答えがなかなかない仕事をしているというようにも考えております。","id":"exchange-079"},{"speaker":"やなぎさわ委員","kind":"質問","question":"かしこまりました。ちなみになのですけれども、品川区では、ケースワーカー１人あたり生活保護世帯何世帯を受け持ちというか、担当されていますか尋ねました。","respondent":"豊嶋生活福祉課長","answer":"現時点でのケースワーカー一人あたりの受け持ち数ですが、国は８０人を１つの標準数としています。現時点では、８０人を若干下回る７８.７人です。","id":"exchange-080"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そういった方に対して、ちょっと要望ですけれども、ぜひ改善を要望させてほしいと求めました。現在の品川区の生活保護のしおりを私も確認させてもらったのですが、その辺の受け止めというか、何かあれば説明を求めました。","respondent":"豊嶋生活福祉課長","answer":"やはり少し字が小さかったり、少し量が多かったりなど今しているところで、今年度改訂作業に今入っています。イラストを増やす、なるべくページ数を少なくしてエッセンスにしていくというような流れで、今現在改訂作業を進めているところです。","id":"exchange-081"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"これは要望です。障害者グループホーム運営費助成なのですけれども、これ２４０万円が計上されていますが、詳しい内訳を説明するよう求めました。","respondent":"松山障害者支援課長","answer":"２４０万円の内訳ですけれども、有資格者の方に対して助成したものになっております。１事業所なのですが、２名いる資格者の方を配置していたため、その助成ということになります。","id":"exchange-082"},{"speaker":"やなぎさわ委員","kind":"質問","question":"これはもともとの見込みというものはいかがだったのでしょうか。もともと２４０万円ぐらいなのか、それより多かったか、少なかったか、見込みと比較して。","respondent":"松山障害者支援課長","answer":"当初の予算としては倍の予算、当初４件を見込んでおりました。","id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"意見","question":"思ったよりも利用されなかったということで、やはり、介護施設で３年は結構ハードルが高いと思うので、ぜひこれ１年とか、もしくは２年、少し短縮して、今後実施をお願いしたいのですけれども、その辺いかがでしょうとの意見を述べました。","respondent":"松山障害者支援課長","answer":"有資格者助成については、入居者が中重度で支援がより必要な方に対して有資格者を配置している場合の助成だということで、それらの趣旨も踏まえて、質も担保しつつ、また、あと実務経験等については事業者の声を聴きながら、緩和していく方向で検討をしてまいります。","id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"意見","question":"最後に外国人材の受入れなのですけれども、れいわ新選組、私の所属しているれいわ新選組は、移民政策に反対しております。技能実習生や特定技能を含めた外国人の受入れというものに対して、非常に慎重ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-085"},{"speaker":"こんの委員","kind":"提案","question":"今回の私の一般質問でも、この介護人材の確保、それから介護者の負担軽減の観点から、ユマニチュード技法の導入を提案させていただきました。先日一般質問で提案をしました、導入してはどうかと提案をいたしますが、ご所見を伺いたいと思いますとの意見を述べました。","respondent":"菅野高齢者福祉課長","answer":"在宅で高齢者の方を介護されている方の対応の仕方等についての、いろいろな講師を、専門家の方を招いて実施している研修となっております。","id":"exchange-086"},{"speaker":"こんの委員","kind":"質問","question":"費用は７,７００円という、このような形です。こちらの日本ユマニチュード学会の講座を活用するということも考えられますけれども、こうしたことへのご見解をお聞きしたいと思います。","respondent":"樫村高齢者地域支援課長","answer":"ユマニチュードのオンライン講座の補助についてのお尋ねです。こちらにつきましては、情報収集しながら、区としても研究してまいりたいと考えています。","id":"exchange-087"},{"speaker":"こんの委員","kind":"確認","question":"そこでまず現状を確認したいのですが、現在借り上げ住宅、これは７棟、１２４戸と認識をしております。どのような契約の期間の考え方になっているのか確認したいということと、期限あるのか、今後の事業の方向性も併せて確認したいと求めました。","respondent":"樫村高齢者地域支援課長","answer":"２回目以降につきましては、１０年で更新しているといった考えです。今後継続していけるかどうかといったところですけれども、住宅の状態を見ながら、オーナーとも協議を重ねて、契約更新をしていくような考えです。","id":"exchange-088"},{"speaker":"こんの委員","kind":"質問・要望","question":"オーナーと状況も確認をしながらということですが、５年契約となっているところも、いわゆるオーナーのご希望で５年としているのでしょうか。このように捉えていますので、今後この捉えたことに対しての対策、具体的に何か考えていることがあればお聞かせほしいと求めました。","respondent":"樫村高齢者地域支援課長","answer":"１か所、１０年間はできないということで、特例的に５年ということで契約した件数が１件あります。需要の高さというものは区としても認識していますが、こういった事業を活用しながら、バランスよくご案内を進めていきたいと考えています。","id":"exchange-089"},{"speaker":"こんの委員","kind":"質問・要望","question":"款を外れないように質問をさせていただきたいところですが、このような仕組みになっていくと思いますけれども、この仕組み自体。ですから、その点について、福祉の観点からのご所見を伺いたいと思います。","respondent":"樫村高齢者地域支援課長","answer":"住宅課と一緒に連携しながら、全体的な区としてのバランスも考慮しながら、検討してまいりたいと考えています。","id":"exchange-090"},{"speaker":"こんの委員","kind":"質問・要望","question":"次の質問に参ります。利用したい日時のご希望に合わない場合、利用者からの声がありますが、そのようなお声は入っておりますか尋ねました。","respondent":"染谷子ども家庭支援センター長","answer":"産後の家事・育児支援、産後ドゥーラのマッチングに関するご質問かと思います。９割を超える方が満足をいただいているという、委員のお話にあったマッチングや、改善を検討しています。","id":"exchange-091"},{"speaker":"こんの委員","kind":"意見","question":"アンケートのお声から改善を考えてくださっているということですので、マッチングの改善をぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-092"},{"speaker":"石田（し）委員","kind":"質問","question":"２３０ページ、時間があれば２８５ページ、在宅子育て支援拠点事業についてお伺いをしていきます。これまでも様々取組をされてきたと思いますけれども、令和５年度の決算において、令和５年度の実績がどのようになっていたのか説明を求めました。","respondent":"菅野高齢者福祉課長","answer":"福祉人材確保の令和５年度決算についてということでのご質問についてです。そしてＩＣＴ見守りシステム設置や、多岐にわたった事業内容で、こちらの決算額が１億１,４６８万８,０００円というようにご報告します。","id":"exchange-093"},{"speaker":"石田（し）委員","kind":"質問","question":"昨年の福祉のやなぎさわ聡議員から質問もあった、実績を見るとなかなか件数が上がってこない。半分ですか、年度の半分ぐらいが経過したのですけれども、この事業についての実績は今どのようになっているか説明を求めました。","respondent":"菅野高齢者福祉課長","answer":"今ご質問のございました、まず遠隔地からの人材確保支援につきましては、令和５年度につきましては３件ということになっております。","id":"exchange-094"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ですから、ここはやはり現場の声をしっかり聴いていただいて、現場に即した支援事業にぜひしていただきたいなと思います。この障害児の支援について、現在品川区で所得制限がかかっているものがあるのかどうか説明を求めました。","respondent":"松山障害者支援課長","answer":"現在、品川区で所得制限がかかっているものは、障害児福祉手当になります。","id":"exchange-095"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ですから、区としても取り組んでいただきたいなと思いますが、これも要望で終わります。最後、在宅子育て支援ですが、今現在において、子どもを預けている方と、いわゆる在宅で子育てをされている世帯の割合、分かれば説明を求めました。","respondent":"藤村子ども育成課長","answer":"今在宅で子育ていただいている方の割合というものは、すみません、おおむね２万人中の、半数弱だったと思います。","id":"exchange-096"},{"speaker":"石田（し）委員","kind":"質問","question":"この２８５ページに出ていますけれども、そのほか、今すごく子育て支援を充実させている品川区だからこそ多いわけです。在宅で子育てもできるのだよという環境づくりを行うことは、必要だと思うのですが、その辺区として考えがあれば説明を求めました。","respondent":"藤村子ども育成課長","answer":"ゼロから６歳児が大体２万人いらっしゃって、保育園児が１万１,０００人、在宅児が約９,０００人というところになっています。例えば今八潮の子育て支援施設というものを計画しておりますが、子育てを楽しんでいただける環境をできるように取り組んでいるところです。","id":"exchange-097"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"改めて、今このような時代だからこそ考えていただきたいなと思いますので、子育て支援のさらなる充実を図っていただきたいなと思います。よろしく願います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"西村委員","kind":"質問・要望","question":"ひとり親家庭支援の広がりを要望したく質問します。令和５年度、どのようなご相談が多かったのかを併せて伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"現在の離婚相談も含めた家庭相談の数字等なのですけれども、若干の微増というようなところです。離婚後にひとり親になったときの支援、就労支援、生活支援など。","id":"exchange-099"},{"speaker":"西村委員","kind":"質問・要望","question":"ひとり親家庭の通勤定期の割引や水道料金の助成の申告、様々な場面でオンライン申請、郵送対応のご検討をいただきたいと考えています。この辺り、区のお考えと対応を伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"現在児童手当の申請や子どもすこやか医療証の交付など、マイナポータルの電子申請機能を利用して、電子申請ができるようになっております。窓口の申請だけになっておりますので、今後電子申請を受け入れられるように検討していきたいと考えております。","id":"exchange-100"},{"speaker":"西村委員","kind":"質問・要望","question":"養育費や婚姻費などの申立ても全て郵送でいいということを私も初めて知りまして、聞き取りは電話対応で大丈夫というように確認を取っております。例えば、課題を解決する１つの方法としまして、国の進める離婚前後親支援モデル事業の導入をご要望させてほしいと求めました。","respondent":"飛田子育て応援課長","answer":"区の養育相談支援事業のほうなのですけれども、現在、今年度よりＡＤＲや親子交流支援に触れて、そのようなところの助成も始めているところです。離婚前後の支援体制強化ということで、他区の実施状況や実施方法などを精査しまして、検討していきたいと考えております。","id":"exchange-101"},{"speaker":"西村委員","kind":"提案","question":"もう一つご提案させていただきたいのですが、母子家庭が住むことは難しいと、お声が届いております。ほか自治体も参考にしていただきながら、住宅費助成の検討もしていただきたいと要望しますけれども、いかがか尋ねました。","respondent":"飛田子育て応援課長","answer":"民間賃貸住宅の入居に当たりまして、連帯保証人が立てられない方については、保証委託の契約を締結する際の保証料を助成しているところです。今年度より、国のほうも児童手当や児童扶養手当の拡充もありましたので、国や他の自治体の動向を注視していきたいと考えております。","id":"exchange-102"},{"speaker":"西村委員","kind":"質問","question":"次に、児童保育費全般から、休園判断について伺ってまいりたいと思います。品川区の今のご判断の基準と状況を伺います。","respondent":"中島保育施設運営課長","answer":"保育園につきましては、児童福祉法で定められている福祉施設でありまして、閉園に関する一律の規定はないところです。区としましては、できる限り休園せず、最大限登園自粛する方向で考えているところです。","id":"exchange-103"},{"speaker":"西村委員","kind":"質問","question":"通勤に危険を感じる職員は早めに帰し、それに伴い、保護者にお迎え要請を現場判断で許可をしたと伺っております。明確に基準をつくるなど、ご検討をお願いしたいと思いますが、ご答弁をお願いいたします。","respondent":"中島保育施設運営課長","answer":"当然園児の、保護者そしてそこで働く職員も含めまして、安全確保は非常に重要な問題だと考えております。登園自粛という考えではありますが、様々情報把握に努めて、安全確保については慎重に考えていきたいと思います。","id":"exchange-104"},{"speaker":"鈴木委員","kind":"質問・要望","question":"やってくれというようなことでずっと要望してきたものなのですけれども、そのときもう既に所得制限をつけていたのは４区しかなかったのです。改めて、なぜ所得制限をなくすことになったのか、その理由を伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"聞き取ったところによりますと、それを３０日で掛けると、大体１万５,０００円程度は皆さんご負担されているのかなというところで把握しております。","id":"exchange-105"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それからポスター８０枚分が計上されているのですけれども、これがどのように活用されているのか伺いたいと思います。今回、これからいつ頃、この所得制限をなくすことと、額も上げていくということはいつ頃の見通しなのか、そのことも伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"介護事業者にもお願いをさせていただいているというところで、周知のほうは今後も社会福祉協議会と連携して、努めてまいりたいと考えています。","id":"exchange-106"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのようなところで、ＭＳＷの方など、そういうところにもぜひ知らせていただいて、この周知をぜひお願いしたいなと思っています。これは変わったのかどうなのか、要綱は変わっていないようなのですが、これはどうなのかということを具体的に教えてほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"今年度社会福祉協議会のほうにお願いして、社会福祉協議会の自主事業と、区のほうでは補助させていただいている次第です。社会福祉協議会とともに病院とも連携して、せっかく所得制限も撤廃していい事業になっていくということですので、広く広めていきたいと考えています。","id":"exchange-107"},{"speaker":"田中委員","kind":"質問・要望","question":"２７５ページ、２８３ページ、私立幼稚園を中心にお伺いをしたいと思います。要望もあり、この要望に対して、まずは今のお考えをお聞かせほしいと求めました。","respondent":"佐藤保育事業担当課長","answer":"私立幼稚園に対する補助金の考え方ですが、品川区の保育行政を支えていただいてきた大切な施設であると考えております。区といたしましては、保護者の方が保育、引き続き幼児教育の質の向上を図れるように支援をしてまいりたいと考えております。","id":"exchange-108"},{"speaker":"田中委員","kind":"質問","question":"１０２条園もありますし、今の補助の出し方を見ると、結構一律に出しているような気がしております。建学の精神をどうするか、そういったこともしっかり踏まえた中で補助の在り方を考えるべきだと思いますが、いかがか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"現在区のほうで私立幼稚園にお支払いしている補助金の考え方ですが、幼児教育の充実を図るために、一律の対応をしています。そのため、法人の経営種別による区分等々については考えてございません。","id":"exchange-109"},{"speaker":"田中委員","kind":"質問・要望","question":"これを今後どう増やしていくのかということを幼稚園協会側に対しても、こちら側からしていくべきなのかなと考えています。何というのでしょうか、今後持続可能な幼児教育を区で行うに当たって、私は今後私立幼稚園が大きく発展する可能性はちょっと厳しいのではないかなと。","respondent":"芝野保育入園調整課長","answer":"公立、私立を合わせた今後の幼稚園の在り方ですが、既に在り方検討のほうで方針を詰めしています。教育委員会などと連携を取りまして、接続など、そのような部分を公立幼稚園の強みを活かした施策を展開していきたいと考えております。","id":"exchange-110"},{"speaker":"田中委員","kind":"意見","question":"ある意味、延命のために補助金を出すということも１つの考え方としてありますが、一方で建学の精神や自主独立の視点から、やはり経営は自主的に努力してもらわないと困る部分も私はあると考えていますので、その辺のバランスをぜひ取った上での運営をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-111"},{"speaker":"吉田委員","kind":"質問・要望","question":"去年の一般質問で、それから支援区分とか、そのようなところのバランスを取っていただきたいということを求めました。この出石つばさの家については支援区分６の方も取ってくださっているということでしたが、その辺についてどうなっているか、まず伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"定員１６名のところ１２人が入居に至っておりまして、男性が６名、女性が６名というような状況になってあります。今後開設予定の区の整備案件としまして、男女ともに受け入れる予定ということで、現在事業者と調整しています。","id":"exchange-112"},{"speaker":"吉田委員","kind":"意見","question":"では今のところ、それぞれの施設で男女ともにということですね。その辺については事業者との話合いというか、要は区から何か支援が入るなど、そのようなことについてお聞かせほしいと求めました。","respondent":"佐藤障害者施策推進課長","answer":"男女比はある程度均衡しているというような認識でおりますが、小規模の施設など、個別にはある状況であるのかというように認識しております。","id":"exchange-113"},{"speaker":"吉田委員","kind":"質問・要望","question":"ちょっと１点だけ、支援区分５・６の方が入っておられるグループホームの数が、やはり他区に比べてとても少ないということが分かりました。この時点は去年の４月１日現在の数を聞いていますので、品川区の支援区分５、６の入所者がいる施設は３という数になっております。","respondent":"佐藤障害者施策推進課長","answer":"入居者の選定方法等につきましても調整をしまして、受入れを進められるようにしていきたいと考えております。障害者支援課と連携しながら、既存のところ、重度の方の受入れをできるような形の施策を検討してまいりたいと思います。","id":"exchange-114"},{"speaker":"吉田委員","kind":"質問・要望","question":"もし何か後で見解があったら伺います。子どもの権利擁護を基にした児童相談所にしていただきたいということで、その理念はしっかり取り入れるということは確認をしております。","respondent":"金子一時保護担当課長","answer":"運営の仕方についても、そのやり方も実施していきながら、子どもの声とアドボケイトの事業者とともに相談をして進めていくという形で行っていきます。今、そのような形で進めているところであります。","id":"exchange-115"},{"speaker":"吉田委員","kind":"提案","question":"今、仕組みづくりに向けて進めておられるということを確認させていただきました。私も全然専門性はありませんので、こうしなさいという提案はないのですが、その辺の話合いの状況などもあったら説明を求めました。","respondent":"金子一時保護担当課長","answer":"アドボケイトに関しては、基本的に、それこそ子どもが言葉で表現できるお子さんもいれば、言葉でなかなか表現できないお子さんもいらっしゃいます。","id":"exchange-116"},{"speaker":"吉田委員","kind":"提案","question":"今お答えいただいたことを、私たちもしっかり見させていただきたいですし、これからもできる提案はしていきたいと考えています。これは要望ですとの意見を述べました。","respondent":"長谷川児童相談課長","answer":"児童相談所を開設いたしましたので、実際に通っているお子様向けに周知を図っていきたい、強化していきたいと考えています。そのような機関があるのだということをお子さん自身に理解をしてもらう、そのようなフェーズに入っているのかなと考えています。","id":"exchange-117"},{"speaker":"吉田委員","kind":"確認","question":"そのようなことを考えておられるということを確認してよかったなと思いますが、それが今、これから配られるということなのでしょうか。その辺のスケジュールを説明するよう求めました。","respondent":"長谷川児童相談課長","answer":"今月中に配布できるように準備しているところです。","id":"exchange-118"},{"speaker":"吉田委員","kind":"質問","question":"それは学校を通してなど、そのような形になるのでしょうか。それぞれの対象児童のいるところに直接配られる形なのか、その辺についても説明を求めました。","respondent":"長谷川児童相談課長","answer":"周知カードの配布方法になりますけれども、各学校に依頼文を送りまして、その依頼文と一緒に保護者宛ての通知文も送ります。その保護者宛ての通知文と通知カードをセットにして、各担任からお子さんに配ってもらうということを考えています。","id":"exchange-119"},{"speaker":"吉田委員","kind":"質問","question":"ヤングケアラーのときも感じたのですが、小さい子どもたちは何か除かれるのです、そのようなときに。大人としては、何らかの形で伝えていくべきだと思うのですが、その辺について検討されていることがあったら伺います。","respondent":"長谷川児童相談課長","answer":"当然字が読めないお子さんにはちょっと配るのは難しいかなというところで、今回は小学校１年生以上を対象にしたカードを配らせていただきます。どれぐらい増えるか等も見ながら、足りていない部分への支援を考えていきたいと、このように考えています。","id":"exchange-120"},{"speaker":"吉田委員","kind":"質問・要望","question":"いろいろ配慮されていることが確認できてとてもよかったと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"若林委員","kind":"質問・要望","question":"５０３ページ、介護保険の地域包括支援センター等では、地域包括支援センターと在宅介護支援センターの在り方を一般質問でも伺いました。品川ですと１３地域ですか、適切に提供できる体制が制度の根本というように、私は認識をしています。","respondent":"菅野高齢者福祉課長、樫村高齢者地域支援課長","answer":"私のほうからは、地域包括支援センターの今後の再構築に向けての検討スケジュール等について、お答えさせていただきたいと思います。今後より一層、地域包括支援センターの在り方を検討する場としては… 利用者の反応の手応えですけれども、９月末現在で３会場で実施をいたしまして、１８８名の方にご助言をいただいたところです。","id":"exchange-122"},{"speaker":"若林委員","kind":"質問・要望","question":"２点目の補聴器のほうは、少し私聞き方がまずかったですかね。これは要望で終わります。","respondent":"樫村高齢者地域支援課長","answer":"補聴器の件です。それぞれ個々に応じて、医師の方、それから販売店とつながりを持っているというように認識をしています。","id":"exchange-123"},{"speaker":"若林委員","kind":"意見","question":"そこで、要するに何台売ったということが成果ではないですよねと冒頭で申し上げました。そこからの成果をしっかりと、その後の生活の質のＱＯＬの向上のために、品川区は一定の対応、何か介入をということで、また改めてやりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-124"},{"speaker":"西本委員","kind":"確認","question":"２５７ページのすまいるスクール運営費にお伺いします。それに対する経費が幾らかかったのかということ、それから、アレルギー対策にはどのような指示を出したのかを確認したいと思います。","respondent":"藤村子ども育成課長","answer":"目的ですが、昼食の選択肢を増やすというところを第１に、保護者の負担軽減というところを考えて実施しているものです。まず仕出し弁当の対応補助委託ということで、そちらが５７６万４,０００円、こちらが１４７万８,０００円という形になっております。","id":"exchange-125"},{"speaker":"西本委員","kind":"確認","question":"各校に１人、配膳等々で配置した方々全員にアレルギー対応のエピペンの使い方も含めて指導したということの理解でよろしいでしょうか。そこの、かなりちぐはぐ、何というのでしょうか、ずれが出てきてはいないでしょうかということが非常に気になりますが、いかがか尋ねました。","respondent":"藤村子ども育成課長","answer":"保護者の方から、今回、基本的にはすまいるスクールのほうではアレルギー対応していないので。こちらのすまいるスクールにつきましては、アレルギー対応というものは非常に慎重にやっているという形になっております。","id":"exchange-126"},{"speaker":"西本委員","kind":"質問・要望","question":"やはりそのようなことをきちんとお知らせしなければいけないのではないでしょうかということが１点です。ですから、この考え方、お弁当１つとっても、やはり子育て支援というものはどうあるべきなのかということを、ぜひお言葉ほしいと求めました。","respondent":"藤村子ども育成課長","answer":"こちらのお弁当の実施に当たっても、お弁当のご注文をされる際はご注意くださいということで、口頭でも書面でも保護者の方にお知らせしています。","id":"exchange-127"},{"speaker":"高橋（伸）委員","kind":"質問","question":"２７５ページ、病児保育、時間があったら２３７ページ、心身障害者福祉会館運営費についてお伺いをいたします。この事務費の計上について、現在、品川区は区としてどのような対応をされているのか尋ねました。","respondent":"中島保育施設運営課長","answer":"こちら、今３つの病児保育施設に委託をしていますが、こちら費用につきまして、平成３０年に見直して以降、そのまま据置きという形になっております。来年度予算に検討する上で、その辺のところのご意見等々も含めまして、ただいま検討を進めているところです。","id":"exchange-128"},{"speaker":"高橋（伸）委員","kind":"質問","question":"今課長おっしゃられたように、前は４か所あって、今１閉室になっております。それも含めて、今後拡大が私は急務だと考えておりますけれども、区のお考えはいかがか尋ねました。","respondent":"中島保育施設運営課長","answer":"その解消に向けて、解消がまず最優先と考えて取り組んでいるところです。それに向けて、今努力を進めているところです。","id":"exchange-129"},{"speaker":"高橋（伸）委員","kind":"意見","question":"それと医療機関併設型の拡大に向けては、現在区から医療機関についていろいろ働きかけをしていると思うのですけれども、実際どのように行われているのかと、その働きかけの実際とその取組について、これまでの取組についてのご報告をお願いいたしますとの意見を述べました。","respondent":"中島保育施設運営課長","answer":"具体的には、先月９月２５日に募集説明会を行いまして、４施設の医療機関にご参加いただいたところです。こちら説明会では、参加者に理解を深めていただきまして、今検討のほうをしていただいているところです。","id":"exchange-130"},{"speaker":"高橋（伸）委員","kind":"確認","question":"今後、実際、この先どのぐらいの期間を見据えて決定をなされるのかどうかということを確認をさせてください。お分かりになっている範囲で、今現時点のことをお尋ねします。","respondent":"中島保育施設運営課長","answer":"ただ、保育士の確保や、施設の様々な条件ありますので、そこは各医療機関の実情等も確認しながら進めてまいりたいと思います。期間については、ちょっとまだ明確には申し上げられないのですが、できるだけ早く、可能な限り早く進めてまいりたいと考えています。","id":"exchange-131"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"やはり偏りがあるので、広域的に品川区内に設置をしていただきたいということは、区のほうも当然お分かりになっていると思います。それを含めて、何か地域のこの辺を想定しているのだという、大体候補地この辺ですよということがもしお分かりになれば教えてほしいと求めました。","respondent":"中島保育施設運営課長","answer":"ただいま３施設、今立地、運営しているところが目黒の駅の近くということと、あとは戸越と中延という３地区になっております。東側のエリア、そのようなところを中心に、幅広い形でご利用いただけるような場所について進めていきたいと考えています。","id":"exchange-132"},{"speaker":"高橋（伸）委員","kind":"提案","question":"本当に我が会派からも以前から提案しています、このネットワークの構築をぜひよろしくお願いいたします。以前質問をさせていただいた、この先どのような方向性でいるのかどうか、教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"障害者支援課、それから支援者であるＳＴ、言語聴覚士の方からもご意見を伺っております。今後に向けて、具体的にその先行区の状況を調査しまして、検討してまいりたいと考えています。","id":"exchange-133"},{"speaker":"高橋（し）委員","kind":"意見","question":"就学前の特別支援の保育についてお尋ねします。特別支援保育という項目と特別支援巡回相談という表現が２つあるのですけれども、その表現の違いがどのような形であるのかお尋ねしますとの意見を述べました。","respondent":"中島保育施設運営課長","answer":"特別支援保育に関するお尋ねです。特別支援保育といいます、また審査会など、それぞれ所要の経費のほうを特別支援保育というところで計上しています。","id":"exchange-134"},{"speaker":"高橋（し）委員","kind":"質問","question":"その巡回相談についてお尋ねするのですが、巡回している臨床発達心理士、学校心理士たちと区の契約はどのような形になっているのでしょうか。１時間で１万２,０００円と伺っています。","respondent":"中島保育施設運営課長","answer":"今委員おっしゃるとおり、報償費でお支払いをしています。","id":"exchange-135"},{"speaker":"高橋（し）委員","kind":"質問","question":"どのような契約の形態で、この心理士の方たちと契約を行っているのでしょうか。委嘱とか、委任とか、いろいろあると思うのですが。","respondent":"中島保育施設運営課長","answer":"契約の形態はちょっとすみません、恐らく委嘱ではないかと思いますが、すみません。少し曖昧です。","id":"exchange-136"},{"speaker":"高橋（し）委員","kind":"意見","question":"恐らくということですが、例えば委嘱だとすると、委嘱状をお渡ししているのか、あるいは口頭で契約をしているのか、それとも文書で心理士たちと契約をしているのか、どのような位置づけで契約をされているのかということをお尋ねしたのですけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-137"},{"speaker":"高橋（し）委員","kind":"質問","question":"例えばどこを回るだとか、どのようなことをするだとか、そのような目的や細々としたことを定めているものがあるのでしょうか。例規集を拝見したのですが、私ちょっと見つけられなかったので。","respondent":"中島保育施設運営課長","answer":"こちら巡回相談等に関する内容ですが、特別支援保育の手引きというものを保育施設運営課で作成しておりまして、そこに目的等、体制等は定めているところです。","id":"exchange-138"},{"speaker":"高橋（し）委員","kind":"質問","question":"要綱で定めて、心理士にお願いするわけです。要綱がないとすると、１件１件それぞれ、１件決定というのですか、毎年毎年どのように、この事業を心理士にお願いしますと決定しているのか尋ねました。","respondent":"中島保育施設運営課長","answer":"毎年度、１件決定という形でしていると思います。","id":"exchange-139"},{"speaker":"高橋（し）委員","kind":"質問","question":"それをつくる必要があると思うのですが、いかがか尋ねました。","respondent":"中島保育施設運営課長","answer":"こちらの巡回相談、特別支援保育につきましては、ノウハウも長らくやっておりまして積み上がってきておりますので、要綱の作成については検討してまいりたいと考えています。","id":"exchange-140"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"必ず決めていただいて、そして心理士の方たちに示して、さらにこの事業を進めていってほしいと求めました。何でしょうか、突然こういった事業が打ち切られる可能性もあるのではないかと心配してしまうのですけれども、それは杞憂なのか尋ねました。","respondent":"中島保育施設運営課長","answer":"この事業自体はとても必要性の高いものですので、継続的にやっていきたいと思っているところです。ちょっとその形というか、事業継続性を示すようなものにつきましては、今後検討してまいりたいと考えています。","id":"exchange-141"},{"speaker":"高橋（し）委員","kind":"質問","question":"幾つかそのほかの事業も行っていきたいと思います。私立の保育園と区のほうが保育委任しているわけですから、拡大してもらいたいと思うのですが、いかがか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"私立保育園における特別支援児の対応ですが、特別な支援が必要なお子様の加配に関して、充実した保育内容とする必要があると考えています。特別支援児に対する相談等におきましても、充実した事業実施をしようとしております。","id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問","question":"私立のほうも公立のように充実したものにしていくというお話ですから、お願いしたいと思います。ですから、さらにそれを、臨床心理士は１０５行っているのですが、学校心理士のほうは９０なので、臨床心理士のほうに合わせていただくよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"},{"speaker":"松本委員","kind":"質問","question":"私からは、２８７ページ、生活保護経費について伺います。システム改修の中身についてお願いいたします。","respondent":"豊嶋生活福祉課長","answer":"システム改修費の中身ですが、主に２つあります。６６０万円ほど、５年に一度の生活保護の基準改定がございまして、こちらが４６２万円で計上されてあります。","id":"exchange-144"},{"speaker":"松本委員","kind":"質問・要望","question":"この６５歳からの５年分の年金の一括の受給を受給者の方に求めて、その支給された年金に対して６条返還を求めていくということになるかと思います。そうすると、それで自立更生が図られなくなるのではないかということを、初日にそこまでの導入ということで伺いました。","respondent":"豊嶋生活福祉課長","answer":"今のお話で当てはめますと、住民税につきましては、控除ということが１つ言えるかとは思います。最終的には所管が判断するものとは考えてありますが、今のお話であれば、基本的には控除という考えで間違いないのではないかと考えております。","id":"exchange-145"},{"speaker":"松本委員","kind":"質問","question":"５年分年金振り込まれたけれども、これ所得税や住民税どうしたらいいのだろうというようなご相談、やはりあり得るのだと思います。ですから、丁寧に説明していただけないかなと思うのですが、いかがか尋ねました。","respondent":"豊嶋生活福祉課長","answer":"そもそも年金が遡及にならないように、６５歳の時点で、こちらのほうは各受給者の方にご案内をしています。保護開始時に２９条調査と申しまして、課の中で周知するとともに、その辺りはシステムを徹底してまいりたいと考えています。","id":"exchange-146"},{"speaker":"松本委員","kind":"質問・要望","question":"ですから、生活保護課、窓口のほうで見ていただくということも１ついいのではないかなと思います。相談体制含めて、いろいろとフォローをしていただけないかなと、最後はご要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-147"},{"speaker":"藤原委員","kind":"質問","question":"２５２ページの児童福祉費で、まず大きく伺います。子どもの未来でどのような施策をして、どのようにしていきたいかということを、まず初めにお伺いします。","respondent":"佐藤子ども未来部長","answer":"現在策定しておりますこども計画の検討の中で、保育の需要・供給や、老朽化施設の改築計画等に活かしてまいりたいと考えております。さらにヤングケアラーやひきこもりの支援など、本日の答弁の反省も含めて、しっかり事業を進めてまいりたいと思います。","id":"exchange-148"},{"speaker":"藤原委員","kind":"質問","question":"先ほどまで席がなかったようなのですがその席に座られて、第３庁舎も部長中心に子どもの席があるのに、担当課長の席はないですよね。課長、自分はこの課の担当課長としてこのようにやっていきたいのだという思い、その辺をぜひ教えていただけますか。","respondent":"柴田子ども施策連携担当課長","answer":"子ども、それから子育て世帯、そういったところのウエルビーイングにつながる施策というものを進めていくべきと考えております。そういった観点からも、幅広く子ども施策というものを見て、進める一助となりたいと考えておるところです。","id":"exchange-149"},{"speaker":"藤原委員","kind":"質問・要望","question":"これ３点セット、ぜひ来年度の予算でしっかりつけていただきたいと思うのですけれども、いかがでしょうか。２４５ページ、荏原特別養護老人ホーム等大規模改修工事に関連してなのですけれども、これ所管といいますか、総合的に所管するのはどこか尋ねました。","respondent":"松山障害者支援課長、東野福祉計画課長、菅野高齢者福祉課長、樫村高齢者地域支援課長、豊嶋生活福祉課長、佐藤障害者施策推進課長","answer":"車椅子やストレッチャーを利用される方にとっては、予約料等、この３点セットは必須な、欠くことができないもので、必ず発生してしまいます。… ７５歳以上の独り暮らし高齢者、または高齢者だけの世帯についての調査を行いまして、それから見守りの情報のデータとしていくものです。… 私からは、荏原特別養護老人ホームについてのご質問にお答えします。","id":"exchange-150"},{"speaker":"藤原委員","kind":"質問・要望","question":"前社会福祉協議会にいらっしゃったわけですから、いろいろな全体を見られるので、ぜひその辺安定した運営をしていってほしいと求めました。新しいものをやろうと思うのですが、今どのような状況で、これ進んでいますか。","respondent":"菅野高齢者福祉課長","answer":"こちら２か年度にわたって、この事業を実施してまいりました。スケッター事業という、ちょっと別の仕掛けの事業を魅力発信事業としてしていますので、こちらの事業もどうぞよろしくお願いいたします。","id":"exchange-151"},{"speaker":"藤原委員","kind":"質問・要望","question":"なぜこのようなすばらしいことをやめてしまうのですか。どのようにやったのですかなど、来ていますよね。","respondent":"森澤区長","answer":"介護の質問にお答えします。生活保護のケースワーカーもいろいろ、区民の皆さんの幸せのためにしっかりと支えられるような環境整備に引き続き取り組んでいきたいと考えています。","id":"exchange-152"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、２３０ページの障害者支援費から、区役所の手話通訳者の配置についてと、障害者相談員への相談について伺いたいと思います。本当によかったと思っているのですが、拡充した理由と、何人体制でやられているのか伺いたいと思います。","respondent":"松山障害者支援課長","answer":"区役所だけではなく、区役所以外への派遣も行っておりますので、どれぐらいのめどで派遣できるかということで調整がついたのが今年度だったです。体制につきましては、それぞれ手話通訳者の方のご都合等もありますので、派遣可能な方を配置していただいている現状にあります。","id":"exchange-153"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今回月曜から金曜まで要望があったからという理由でしたが、５時までという検討はされたのでしょうか、伺います。課題等がもしあるなら伺いたいと思います。","respondent":"松山障害者支援課長","answer":"手話通訳者の配置時間の検討です。派遣件数はかなり増えてきていることから、区役所以外の派遣件数も担保できるのかというようなことも踏まえながら、今回調整したです。","id":"exchange-154"},{"speaker":"石田（ち）委員","kind":"質問","question":"手話通訳者、この登録者がさらに増えると、もう少し違ってくるのかなと思うのです。昨年手話通訳者の登録者数が２８人だったと思うのですけれども、現在はどれぐらいになっているのか伺います。","respondent":"松山障害者支援課長","answer":"手話通訳者の登録者人数についてです。現在も２８人です。","id":"exchange-155"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"その検討はどうだったのか伺いたいということと、区としても、たしか遠隔通訳はやられていると思うのです。何か２３区で初で試験実施しますというようなものが、平成３０年でしたか、そこの状況はどうなっているのか伺いたいと思います。","respondent":"松山障害者支援課長","answer":"全国統一の手話通訳の試験については、実施予定、今年度からもう実施予定です。こちらを実施に向けて検討していたのは、会館のほうにパソコンを単独で設置しまして、そちら行える状態にはなっています。","id":"exchange-156"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですから、押した後通話ができない、会話ができない。この合理的配慮をと、やはり国や都のさらなる積極的な支援も必要なのではないかなと思うのですけれども、区はその辺どのようにお考えか尋ねました。","respondent":"松山障害者支援課長","answer":"例えば品川区で手話通訳者を手配できず、足りなくなった場合、東京都の派遣センターのほうに今応援を求めております。恐らく国や都も、人材確保というものはそれぞれ努めているところだと認識をしております。","id":"exchange-157"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり法律になることで、国連のほうからも勧告で、日本にはそのような手話言語の法律が必要だというように求められております。引き続き、手話言語通訳者の配置、最低限の合理的配慮として、庁舎が開いている時間の配置を強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-158"},{"speaker":"大倉委員","kind":"質問","question":"ページ２７３ページ、保幼小ジョイント事業、ページ２３３ページ、障害者介護給付事務の同行援護について伺います。その研修を受けた方へのガイドヘルパー登録というものはどのように働きかけをしているのか、説明を求めました。","respondent":"中島保育施設運営課長、松山障害者支援課長","answer":"小１プロブレムというところも事業発足の起点となっているところですが、幼稚園等連携して、円滑な就学につなげているところです。そのような課題解決にはまだまだ道半ばかなというところではありますが… 同行援護従事者養成研修を区が委託しまして、例年実施して継続しているところです。養成研修のほか、今年度、居住支援手当を支給しまして、従事者の確保に努めているところです。","id":"exchange-159"},{"speaker":"大倉委員","kind":"質問・要望","question":"私が伺ったところだと、その辺しっかり働きかけて、少しでも増やしていっていただきたいなというところでお願いします。そうした検討についてお話を伺わせてほしいと求めました。","respondent":"中島保育施設運営課長、松山障害者支援課長","answer":"まだなかなかそのような、ちょっとタイミング等もございまして、できていないところです。毎年お願いしていますので、これからも一層連携を図って、１人でも多くの園児を交流できるようにしてまいりたいと考えています。 私からは、ガイドヘルパー以外の視覚支援用具の活用についてです。今、日常生活用具検討会等で、日常生活用具としての活用の可能性があるかないかということは検討してまいりたいと考えております。","id":"exchange-160"},{"speaker":"大倉委員","kind":"質問・要望","question":"３園とか、４園とか、その辺聞き取ってほしいと求めました。スマホやタブレットなどとなってくると思いますので、タブレットなども日常生活用具で検討していただければと思うのですが、最後お願いします。","respondent":"松山障害者支援課長","answer":"スマホ等の活用については、引き続きまた検討会等で検討してまいります。","id":"exchange-161"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１点目は今年度の結果やご意見を踏まえて、来年度もぜひ拡充をした上で継続をしてほしいと求めましたが、いかがでしょうか。２点目は、ご家庭へ誰一人取り残さずお知らせしてほしいと求めましたが、いかがか尋ねました。","respondent":"飛田子育て応援課長","answer":"今後のことにつきましては、今回の支援の効果など見極めながら、来年度の施策については検討してまいりたいと考えております。現在の取組状況や各子ども食堂の現場の声、しながわ子ども食堂ネットワークとも、企業とも意見を聞きながら、検討してまいりたいと考えております。","id":"exchange-162"},{"speaker":"あくつ委員","kind":"質問","question":"品川区は令和４年度から、在宅人工呼吸器の利用者への自家発電機および蓄電池バッテリーの給付を開始し、災害時の電源確保を支援しています。令和５年度の支給件数をそれぞれ説明を求めました。","respondent":"松山障害者支援課長","answer":"昨年１２月時点で２５人です。令和５年度は合計で９件です。","id":"exchange-163"},{"speaker":"あくつ委員","kind":"質問・要望","question":"その前提として、医療的ケア患者にご参加いただいての実証実験、訓練を行ってはいかがでしょうか。ご家庭へマップと併せて周知をしていただきたい、こうしたご要望だったのでそのままお伝えをしますけれども、ご所見を伺います。","respondent":"松山障害者支援課長","answer":"やはり人工呼吸器を使用している方にとりましては、発災時の電源確保というものは非常に重要と考えております。電源確保の可能性や包括協定との連携と、あと区有車の利用等々、委員ご提案のものについて検討してまいります。","id":"exchange-164"},{"speaker":"あくつ委員","kind":"質問・要望","question":"品川区がかなり前から行っているものですから、ちょっと目からうろこのような、このような意見を我々会派として伺いました。第２回定例会における公明党の一般質問の中で、これを求めましたところ、このようなご答弁もいただきました。","respondent":"豊嶋生活福祉課長","answer":"身元が分かっていて引取り手がない方、墓地、埋葬等に関する法律によって、区として対応した件数ですが、昨年度６２件あります。過去５年見ましても、年々増えている状況は品川区も同様です。","id":"exchange-165"},{"speaker":"あくつ委員","kind":"提案","question":"こうしたことをぜひ品川区でも行っていただきたいということで、これも東京都も補助金を、今年度から上限５００万円で始めています。","respondent":"東野福祉計画課長","answer":"例えば重要書類のお預かりということでは、社会福祉協議会のあんしん３点セット、あんしんサービス契約の中に含まれております。先ほどの重要書類のお預かり、５００円ですが、区としては、無償化というところでも一定程度考えていきたいと考えています。","id":"exchange-166"},{"speaker":"まつざわ委員","kind":"確認","question":"私からは、成果報告書の３５ページ、認知症高齢者支援事業と、決算書２４７ページの認知症理解促進事業について質問いたします。は認知症高齢者事業の中で、例えばサポーターの在り方、検診事業についての状況をまず確認したいと求めました。","respondent":"樫村高齢者地域支援課長","answer":"令和４年度に開始した事業でございまして、当初の実施医療機関は１５機関でございましたが、令和４年度と比較しまして約１％増加しております。引き続き区民の方がより受診しやすいような環境というものを整備していきたいと考えています。","id":"exchange-167"},{"speaker":"まつざわ委員","kind":"質問","question":"区ではこの課題にどう向き合っているのか、まずは教えてください。こういった品川区ではありますけれども、企業との連携、そしてまた拠点の考え方について、ご見解を説明するよう求めました。","respondent":"樫村高齢者地域支援課長","answer":"それから拠点についての考え方ですけれども、こちら委員ご指摘のとおり、現在区のほうでは、拠点を決めずに各事業を実施しています。今後につきましては、他自治体の情報も収集しながら、進め方について検討してまいりたいと考えています。","id":"exchange-168"},{"speaker":"まつざわ委員","kind":"質問","question":"チームを組んで認知症の人のその家族、これ来年、２０２５年までに全ての市町村でチームが活動を始めることを目標にしています。全国３３９自治体と、全体の２割にも満たないことが現状でありますが、現在品川区の現状を説明するよう求めました。","respondent":"樫村高齢者地域支援課長","answer":"来年度、２０２５年度末を目標といたしまして、品川版のチームオレンジ化というものを目指して取組をちょうど開始したところです。先行自治体などの情報も参考にしながら、品川区独自のチームオレンジ化というものを目指して、課一丸となって取り組んでまいりたいと考えています。","id":"exchange-169"},{"speaker":"まつざわ委員","kind":"提案","question":"そういったスタイルで、認知症の人とサポーターの人のそれぞれの要望がうまくマッチングしていければと考えています。しながわオレンジガイドの見直しというものを提案させていただきましたが、昨年度からいよいよ改訂に向けて動き始めたと答弁をいただいていますとの意見を述べました。","respondent":"樫村高齢者地域支援課長","answer":"なお名称も、これまで使用しておりました品川“くるみ”認知症ガイドから、しながわオレンジガイドに名称を変更いたしました。より多くの方に手にしていただけるよう、周知啓発を積極的に行ってまいりたいと考えています。","id":"exchange-170"},{"speaker":"まつざわ委員","kind":"確認","question":"改訂したことの確認が取れました。その改訂の中で、工夫した点、また参考にした自治体、あったら説明を求めました。","respondent":"樫村高齢者地域支援課長","answer":"施行など、それから認知症の人や家族を取り巻く状況が変化いたしまして、冊子の内容へのニーズが変化したことを受けて実施したところです。それから認知症地域支援推進員、関係機関等との意見交換を何度も重ねまして、より内容を分かりやすく整理しまして。","id":"exchange-171"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"千代田区のお話が出ましたけれども、やはり当事者のメッセージというのですか、本人たちが発信するということが本当に好評です。どうしてもいいものというのはよく宣伝していただきたいので、そういった配布先や周知の方法、そこの考え方を説明するよう求めました。","respondent":"樫村高齢者地域支援課長","answer":"オレンジガイドの増刷の考え方ですけれども、当初８,０００部発注をかけたところですが、現在追加で１万部の発注をかけております。ちょうど今週に１万部が納品されるような予定になっております。","id":"exchange-172"},{"speaker":"まつざわ委員","kind":"質問","question":"それこそ寺嶋部長が課長時代から、もう６年になりますけれども、もの忘れの検診をやってしまいました。ですから、そういった部分で、事業の整理に関してご見解を説明するよう求めました。","respondent":"樫村高齢者地域支援課長","answer":"今まで進めてきた新規事業を進めるだけでなく、進めるだけでなくて、着実に事業を実施していきたいと考えております。そして、認知症の人やその家族が、地域の中で尊厳を保持して、希望を持って暮らし続けられるまちづくりというものを目指していきたいと考えています。","id":"exchange-173"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/285407?Template=document&Id=6853#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":120484,"voices":394}},{"id":"r06-20241008-4","meetingId":"r06-c-settlement","date":"2024年10月8日","dateIso":"2024-10-08","committee":"決算特別委員会","time":"午前 ９時３０分～午後 ４時４１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を164件整理しています。","topics":[{"id":"topic-01","title":"９時３０分開会 ◯新妻委員長 ただいまより、決算特別委員会を開きます。 それでは、令和５年度品川区一般会計歳入歳出決算","agenda":"９時３０分開会 ◯新妻委員長 ただいまより、決算特別委員会を開きます。 それでは、令和５年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"えのした委員","kind":"質問","question":"私からは、３３１ページのホリデー・トレーニング事業助成、３２９ページ、省エネルギー対策設備更新助成金についてお伺いいたします。一番落ち込んだ令和２年度と前年度、令和５年度との比較を説明するよう求めました。","respondent":"小林地域産業振興課長","answer":"商店街が３分の１ということで、これは１００万円以上のイベントになるのですけれども、１商店街当たり上限３００万円という支援制度があります。令和６年度はさらにもう少し、４０件を超えるぐらいまでいくのかというところで、予算上は計画しています。","id":"exchange-001"},{"speaker":"えのした委員","kind":"質問","question":"先日、私も、しながわ宿場まつりにお伺いいたしました。小規模なイベントでも支援が行われているホリデー・トレーニング事業になりますが、この支援の内容と意味合いについてご説明をお願いいたします。","respondent":"小林地域産業振興課長","answer":"令和５年度は１７件の支援です。商店街の中で、次世代の担い手の方たちがこういったイベントを自主的にいろいろ企画実施するということを通じまして。","id":"exchange-002"},{"speaker":"えのした委員","kind":"質問","question":"私も視察に伺いましたが、ＮＰＯ、そして学生の皆さんとつながりができることはとてもよいことだと考えています。商店街の新しい役割に即した区からの支援も進むと、地域にとって非常にプラスになると考えますが、区としてのご見解をお伺いいたします。","respondent":"小林地域産業振興課長","answer":"この取組は、今年２月に消防庁長官賞、あるいは９月には内閣総理大臣表彰を受けたすばらしい取組だと評価しております。今後、商店街の新しい役割に、区が何か支援できないかということを考えてまいりたいと思います。","id":"exchange-003"},{"speaker":"えのした委員","kind":"提案","question":"総務省が９月２０日に公表した消費者物価指数は前年同月比で２.８％上昇、政府の支援策が一旦終了した影響もあり、２６.２％も上がっております。区ではこうした事態を踏まえ、９月の議会に物価高騰対策の補正予算案を提案されていますが、その内容と狙いをお伺いいたしますとの意見を述べました。","respondent":"小林地域産業振興課長","answer":"令和５年度でいきますと、省エネの効果があるような冷凍・冷蔵庫等の厨房設備・調理機械などへの更新が非常に進んだと認識しております。今回、企業の業務改善・業務効率化も狙いとしておりまして、例えば新紙幣の対応券売機も本助成金の対象とする予定としております。","id":"exchange-004"},{"speaker":"えのした委員","kind":"質問","question":"先日、ラーメン屋にお伺いしたときに、私は新紙幣しかなくて券売機が使えずに、お店の方に両替をしていただきました。お話を伺ったところ、両替をするのは毎朝のことで、銀行への両替業務も大変だということでした。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは、３０９ページの猫の不妊・去勢手術費助成、また２９７ページのＡＥＤ管理費から、それぞれお伺いしたいと思います。初めに、猫の不妊・去勢手術費助成についてお伺いします。","respondent":"赤木生活衛生課長","answer":"現状としまして、申請していただいているチームとしましては、１チームになります。そのほか、２件ほど、今、協力員として活動できないかどうかについて相談を受けているところです。","id":"exchange-006"},{"speaker":"ゆきた委員","kind":"質問","question":"１件のチームと、今、２件が見えているということで、事業開始から約半年ということで、区民への浸透がまだ十分ではないかと思いますが、こちらについての分析と、今後の展開についてお聞きできればと思います。","respondent":"赤木生活衛生課長","answer":"本年の６月に全町会長宛てに、希望がございました町会長に個別にご説明をさせていただきに、町会長会議にお伺いしています。そういった制度につきまして、個別の相談はもちろんですけれども、広く周知を図っていきたいと考えております。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"申請後の約１か月半後に支給となりますが、二匹の話ではないため、改善を求める声が上がっています。治療後に譲渡できる猫１０匹前後で行っていると、手続が短いとの現場の声があり、せめて６０日の申請にはできないでしょうかというお話もあります。","respondent":"赤木生活衛生課長","answer":"今後の在り方につきましてですけれども、他自治体の動向も含めまして、在り方については引き続き検討してまいりたいと考えています。先ほどお伝えした１チームにつきましてですけれども、ボランティアの方を中心にやっていただいているというところは認識しています。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"５０匹以上いる猫の約半数が、雌猫が５匹前後の猫を出産していくと、増え続けていく猫を食い止めることができない状況になります。ここまで抑えられていますが、さらなる対策が必要であると思われますが、こちらについて改めてお聞きできればと思います。","respondent":"赤木生活衛生課長","answer":"ボランティアの方が高齢化しているであったり、担い手の不足というところが、こちらとしても課題と考えております。１１月にまず実施しますけれども、そういった講習会を通じまして、引き続き地域猫活動について周知・啓発を図ってまいりたいと思います。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"来年の３月妊娠が一斉に出産となる４月が、１つの町会だけではなく、周辺の町会にもまたがって倍増していくと伺っています。は、保健所が橋渡し役となっていく必要があると思われますが、改めて区の見解をお聞きしたいと思います。","respondent":"赤木生活衛生課長","answer":"個別にそういった餌やりをされている方に対して、現場にお伺いさせていただきまして、お話をしています。そういったところを含めまして、そういったことをしないようにというところで、お話をさせていただいているところです。","id":"exchange-010"},{"speaker":"山本委員","kind":"質問","question":"３２７ページの雇用確保支援事業、３２９ページの外国人材受入・定着支援事業、３３１ページの共通商品券普及促進事業について伺います。商店街活性化事業費に関連し、この６月に行われた総額５億円のキャッシュレス決済ポイント還元事業について伺います。","respondent":"小林地域産業振興課長","answer":"６月１日から３０日に実施いたしました。これは前回実施したキャッシュレス事業と、区民割合が約４割、ｄ払いが約５割です。","id":"exchange-011"},{"speaker":"山本委員","kind":"確認","question":"区民利用が４割から５割ということで理解いたしました。利用者アンケートや満足度確認の実施の有無、区としての評価、今後の実施予定について説明するよう求めました。","respondent":"小林地域産業振興課長","answer":"アンケート等の実施をしているかですけれども、こちらについては特段、アンケートというのは実施してございません。今後、令和６年度６月は８,０００店舗に近いような店舗数でやっておりましたけれども、店舗の拡大がさらに進むことが望ましいと認識しています。","id":"exchange-012"},{"speaker":"山本委員","kind":"質問・要望","question":"後ほどの話につながりますが、デジタル商品券、デジタル地域通貨など、より有効で効果的な手段を検討していくことを引き続き要望します。次に、共通商品券普及促進事業について伺います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"今ご質問いただきましたデジタル商品券検討の進捗ですけれども、上半期につきましては、デジタル地域通貨およびデジタル商品券を実施している先行自治体の複数の事例を調査したところです。","id":"exchange-013"},{"speaker":"山本委員","kind":"質問","question":"現在の検討状況について理解いたしました。この後ご質問する、区としてのデジタル商品券の導入に対する今後の見通しおよび、課題があれば説明するよう求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"まずはその初期投資や、毎年度運営していくに当たるランニングコスト、それからデジタルデバイド対策などを課題として考えております。それから、今、委員からお話がありましたＴＴＰとの関係もあろうかと考えていますので、そういった課題を含めて検討していくところです。","id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"次に、ＴＴＰについて伺います。我々、しながわ未来は、今年７月に東京都に伺い、ＴＴＰについて勉強会を開催いただき、理解を深めてまいりました。","respondent":"横田デジタル推進課長","answer":"本年７月に都主催の説明会があったほか、８月に都と品川区で意見交換を行いました。その際に都から、都内自治体と効果的に連携できるアプリとして段階的に構築する旨の話は聞いておりますが、詳細は分からないような状況であります。","id":"exchange-015"},{"speaker":"山本委員","kind":"質問・要望","question":"区としてできることは、区の要望を都に前広に伝えた上で、今後の都の動向を見守ることと考えます。次に、ＩＴスタートアップ支援事業の中で、品川スタートアップ・エコシステムについて伺います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"目的につきましては主に３つ考えてございまして、２点目につきましては、そういった文化の醸成を図っていくことです。現在の企業の参加状況につきましては、直近では７８社の企業にご参画いただいているところです。","id":"exchange-016"},{"speaker":"山本委員","kind":"質問","question":"業務効率化など、品川区に貢献する仕組みに関するコンテストを開催し、よければ実証実験で積極的に採用する仕組みをつくってはいかがでしょうか。区の考えを伺います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"例えば品川区が実施するウェルビーイング・ＳＤＧｓ推進ファンドに、行政課題の解決への貢献の場を提供したりといった取組をしています。参画者同士のマッチングや、パートナー企業のほうで、そういったところでの実証実験などのつなぎを図っていきたいと考えているところです。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問","question":"ぜひ庁内でも連携していただきつつ、この仕組みの中でも多くの区内企業を巻き込み、進めてほしいと思います。次に、雇用確保支援事業について伺います。","respondent":"小林地域産業振興課長","answer":"建設業やＩＴ、ものづくりといった企業に対して、大学生等が奨学金の返還費用を返す際の一部を助成する事業を実施しています。６社が今、３名の方に対して、区内の企業でも働いていただくというような仕組みが動いているところです。","id":"exchange-018"},{"speaker":"山本委員","kind":"質問","question":"利用されているということで、とてもすばらしいと思います。一方で、あまり利用が多くないということですが、課題は何と考えますか尋ねました。","respondent":"小林地域産業振興課長","answer":"先ほどご説明したとおり、品川区はそこに上乗せをしていますけれども、やはり東京都全体で使える事業であるということ。そういう取組を見ながら、我々として何か改善できるところはないかということは考えていきたいと考えています。","id":"exchange-019"},{"speaker":"山本委員","kind":"提案","question":"３つ目は款が異なりますので、連携を要望することにとどめます。それぞれ、区のご見解を伺いますとの意見を述べました。","respondent":"小林地域産業振興課長","answer":"全国の自治体の中でも独自の取組と考えておりますが、技術人材、日本の教育方式を取り入れた学校との交流事業というものを進めてきているところです。","id":"exchange-020"},{"speaker":"山本委員","kind":"質問・要望","question":"モンゴル高専だけでなく、ほかの事業にも幅広くご対応いただけるように、引き続きやってほしいと求めました。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"伺いますけれども、こちらの調査の対象には、個人事業主やフリーランスは入っているのでしょうか。どなたが決めているのか、どのように決めているのか、伺いたいと思います。","respondent":"小林地域産業振興課長","answer":"国勢調査などから見る実態の中で比率を見ながら考えておりますので、今は、含まれていないものです。その中で多く頂くようなご相談を踏まえて、より我々として深掘りをしたいようなものにつきまして、調査項目の中で聞いているようなものです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"意見","question":"インボイス開始前の２０２２年７月から９月期と、２０２３年１０月から１２月期に、特別調査項目に入れて調査を２回も行っていたのです。これをやっていたことを、課長はご存じでしたかとの意見を述べました。","respondent":"小林地域産業振興課長","answer":"こちらにつきましては特別調査ということではありますけれども、いわゆるアンケートという形でお聞きしております。いわゆる個人事業主や、あるいは課税情報を含めた、制度の影響がどうかというところを我々として把握するのは困難であると考えております。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"アンケートで影響を聞いているわけですから、伺いたいのは、解せないのです。理由を伺います。","respondent":"小林地域産業振興課長","answer":"ご質問の中で、今回、陳情として頂きましたのは、インボイス制度の影響というところでの実態調査ということでご質問を頂いていたところです。そういったものまで含めて詳細に分析し、また確実に把握するというのは困難であると、引き続き考えております。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"私が改めて伺いたい、求めたいのは、しかも開始から１年たっています。まだやっていないので、契約や取引への影響などを聞く調査項目で調査してほしいと求めましたけれども、いかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"ほかの自治体の中でもそういったところに踏み込んで何か具体的に調査できているか、あるいは調査する能力があるかというところにつきましては、引き続き課題も多いと認識しています。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いたいと思います。これは、大気汚染、電波障害について、環境調査測定が必要な案件ではないかと思いますけれども、いかがか尋ねました。","respondent":"中西環境課長","answer":"大気汚染に関しましては、品川区では、一般環境大気測定を２拠点、八潮と豊町で行ってあります。それから、浮遊粒子状の物質測定やＰＭ２.５の測定、それぞれが環境基準内に収まっているといった状況になっているところです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"自由意見を「大気汚染」、「電波障害」というキーワードで検索すると、大気汚染が１４５件、電波障害が１３６件もあるのです。これは区が実施したアンケートなのですから、出た声に対して調査するというのは行政の責任だと私は思いますので、実施を強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"３１３ページ、３２０ページ、ナイトタイムエコノミーについてお伺いいたします。令和４年度と令和５年度を比較すると倍増、登録参加者数の目標達成数が２倍になっているのですけれども、その根拠と理由を説明するよう求めました。","respondent":"若生健康課長","answer":"令和３年、令和４年と、１,０００人以上のペースで増加してきている経緯もあります。５年間で５,０００人プラスということで、令和１１年度、１万人という目標を立てているところです。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"順調に、そのように参加者数が増えていけばいいと私は思っております。シナモロールを使用することは結構大変なことだということを伺っておりますけれども、その辺り、そうした今後の展開を示すよう求めました。","respondent":"若生健康課長","answer":"文化観光戦略課に申請を行いまして、それにのっとって進めているわけですけれども、周知・啓発に努めていきたいと思ってあります。今後改善していって、より使いやすく区民の方が楽しめる事業になるよう、今後も努力していきたいと思ってあります。","id":"exchange-029"},{"speaker":"筒井委員","kind":"意見","question":"分かりました。廃止されるのか、それとも連動していくのか、今後の動向を説明するよう求めました。","respondent":"若生健康課長","answer":"「健康プラン２１」という健康増進計画の改定作業を行っておりまして、今後、こちらのリニューアルというところも現在検討しています。そういったところで、ウォーキングマップと健康ポイントの連動というところも今後やっていきたいと考えております。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"関連して健康づくり推進委員についてお伺いいたしますけれども、令和４年度の行政評価シートを見ますと、推進委員の平均年齢が上がってきている。現在の健康づくり推進委員の活動を載せていっていただきたいのですけれども、その点、いかがお考えか尋ねました。","respondent":"若生健康課長","answer":"委員ご指摘のとおり、ホームページは大変、活動の情報について不足している部分があることを認識しています。年に１回、そういった活動報告の内容を載せるなど、今後検討していきたいと考えております。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"続いて、太陽光発電・蓄電池システム設置助成についてお伺いいたしますけれども、気候変動対策をしなくてはいけないと考えております。やはり、現実的に太陽光発電しかないのかと私も思うのですけれども、区の認識を説明するよう求めました。","respondent":"中西環境課長","answer":"再生可能エネルギー導入を進めていくに当たりましては、太陽光が一番、比重が大きくなっているところもあります。そういったところも含めまして、品川区では太陽光の発電を積極的に進めているといった状況です。","id":"exchange-032"},{"speaker":"筒井委員","kind":"意見","question":"分かりました。東京都でも、区と都で重なっている助成事業はどの程度あるのか、そして区と都が重なっている場合の対応をお知らせくださいとの意見を述べました。","respondent":"中西環境課長","answer":"太陽光に関しましては、都の補助金との併用を可能としています。それから、ほかの例えば今年度開始いたしました省エネ家電の設置助成等々も。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"２０年から３０年と言われているのですけれども、そうすると二、三十年後に大量廃棄問題が出てくると思います。この廃棄の問題もやはりある程度、二、三十年というスパンですから考えていかなくてはいけないと思うのですけれども。","respondent":"中西環境課長","answer":"太陽光パネルの設置が増えておりまして、２０３０年代後半から４０年頃、我々としても認識しています。今、国でリサイクルの義務化に向けた検討が進んでいるといったところもありますので、私どもとしても対応を考えてまいりたいと考えています。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"よろしくお願いします。ナイトタイムエコノミーについてお伺いいたしますけれども、私の質問でも前向きなご答弁を頂きましたけれども、その辺りはいかがお考えか尋ねました。","respondent":"小林地域産業振興課長","answer":"「しながわ宿場ナイト」というような形で、夜のイベントということも行いながら観光客を集めるような取組を進めているところです。両課でも連携しながら、観光客にもＰＲというような取組を何かできないかということを、引き続き考えてまいりたいと思います。","id":"exchange-035"},{"speaker":"筒井委員","kind":"意見","question":"きっかけは観光でもいいのですけれども、やはり観光というのはどうしても単発になりがちなので、これを中長期的に、持続的に、夜の経済活動というのを復活させて、昼と夜。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"せらく委員","kind":"質問・要望","question":"誤飲についても家庭内で起きやすいので、子どもがいる家庭への周知・啓発が求められると考えています。そこで、乳幼児健康診査などでの当区の誤飲防止のための取組を教えてほしいと求めました。","respondent":"石橋品川保健センター所長","answer":"委員ご質問の誤飲防止の対策について、私からご回答いたします。４か月健康診査の集団指導やマタニティクラスなどの事業において、誤飲チェッカーというものを使用した指導や周知、周知を実施しております。","id":"exchange-037"},{"speaker":"せらく委員","kind":"質問・要望","question":"缶バッジは、区でもいろいろな啓発の手段で作成されていると思いますが、１つ１００円程度で作れると思っています。当区でも、母子手帳の交付時や４か月健康診査でこういったものを配付することで啓発ができないかと思ったのですけれども、いかがか尋ねました。","respondent":"若生健康課長、石橋品川保健センター所長","answer":"グッズも渡していますが、それ以外のグッズなどについては現在、無償で事業者に提供していただいているというところもあります。そういったところから、妊婦の方にお渡しする際に… 先ほどもご説明をさせていただいたとおり、４か月健康診査では、誤飲チェッカーといいまして。実物をご本人に配るということはしておりませんので、今後、そういったことも含めて検討してまいりたいと考えています。","id":"exchange-038"},{"speaker":"せらく委員","kind":"確認","question":"次に、予防接種の任意接種について伺っていきたいと思います。任意接種は自由診療でクリニックが金額を決めることができるので、問題ないという認識にはなると思うのですけれども、確認したいと求めました。","respondent":"五十嵐保健予防課長","answer":"委員ご指摘のとおり、予防接種に関しては全て、保険診療ではなく自由診療となっております。現在、２３区乗り入れで実施しているということで、各医療機関が金額を設定しているという状況になってあります。","id":"exchange-039"},{"speaker":"せらく委員","kind":"提案","question":"該当のクリニックへ確認していただくことでご対応いただけないでしょうか。この２点について伺いたいと思いますとの意見を述べました。","respondent":"五十嵐保健予防課長","answer":"そちらのことは区では把握していない状況になっておりますので、平均価格を出すということは難しい部分があるかと思います。病院に金額を出すようにという指導も、できる権限がございませんので、区では実施できないという状況になってあります。","id":"exchange-040"},{"speaker":"せらく委員","kind":"質問","question":"こちらについて消費者センターにも伺ってみたいのですけれども、消費者を保護するために、価格の表示を進めているところだと思います。医療機関における価格表示についてはどんな対策・方法ができると思われるか尋ねました。","respondent":"小林地域産業振興課長","answer":"年間３,０００件近い、医療分野でのというよりは、ふだんの契約トラブルに関するものが中心となっております。そういった問題についても引き続き、我々も研究を重ねてまいりたいと考えています。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問","question":"私からは、２９７ページ、地域医療連携、３０１ページ、母子保健指導事業費についてお伺いいたします。１点目に、母子保健指導事業費についてお伺いいたします。","respondent":"石橋品川保健センター所長","answer":"妊娠初期の面談、妊娠８か月頃の面接を、保健センターやオンラインで実施しております。０歳児見守り・子育てサポート事業においては、妊婦だけではなく、産後のお母さんとの顔の見える関係づくりを構築しております。","id":"exchange-042"},{"speaker":"横山委員","kind":"質問・要望","question":"今後も研修などにより、さらに共感性を高めていただきたいと考えていますが、いかがでしょうか。保健師の方々の共感性を活かしてほしいと求めましたが、区のお考えを説明するよう求めました。","respondent":"石橋品川保健センター所長","answer":"そちらの支援記録の共有や、あとは支援が必要なご家庭においては、保健センターの保健師が専門職で集まりまして定例会を実施しておりまして。専門職のスキルアップ、また関係機関との連携強化により、相談機能をしっかりと高めてまいりたいと考えております。","id":"exchange-043"},{"speaker":"横山委員","kind":"質問・要望","question":"子育て期にわたって気軽に助けを求められるよう、引き続き相談事業や伴走型支援を推進してほしいと求めましたので、よろしくお願いいたします。２点目に、地域医療連携についてお伺いいたします。","respondent":"三ツ橋荏原保健センター所長","answer":"国の考え方ですけれども、精神障害にも対応した地域包括ケアシステムの構築、いわゆる「にも包括」についてです。令和５年に開催されました品川区精神保健福祉地域連絡会ですけれども、それぞれの事業の実施の状況や法改正などの連絡・調整を行っておりました。","id":"exchange-044"},{"speaker":"横山委員","kind":"意見","question":"岐阜県が設置する７か所の保健所が、５つの保健所圏域に分かれて、「にも包括」構築の取組を実施しているところです。品川区における、保健センターと精神科病院などとのネットワーク体制の現状について説明を求めました。","respondent":"三ツ橋荏原保健センター所長","answer":"先ほどご紹介いたしました令和５年度の連絡会等の中で、またクリニックの医師などをお呼びして、連携しています。","id":"exchange-045"},{"speaker":"こしば委員","kind":"意見","question":"私からは、３０５ページの予防接種費に関連しまして、ＲＳウイルス母子免疫ワクチンのアブリスボについてお尋ねいたします。本年の５月３１日に発売されましたＲＳウイルス母子免疫ワクチン、アブリスボについて、この２点についてご紹介をお願いいたしますとの意見を述べました。","respondent":"五十嵐保健予防課長","answer":"新生児に関しましては重症になる方も多くて、気管支炎等をその後、患ったりするような方もいらっしゃると認識しております。は６０歳以上の方に対しましてＲＳウイルス感染症の予防ということで使われるということになってあります。","id":"exchange-046"},{"speaker":"こしば委員","kind":"質問","question":"ただ、任意接種のため、大変高額であり、およそ３万円から４万円かかると言われております。この母子免疫ワクチン、アブリスボに対する品川区の評価についてお伺いいたします。","respondent":"五十嵐保健予防課長","answer":"特に妊婦に対する投与につきましては、やはりセンシティブな話になりますので、しっかりとした検討が必要と考えております。今までの検討の結果では、ワクチンが原因と考える方も多くいらっしゃいますので、その辺の議論もこれから国でされていくものと考えております。","id":"exchange-047"},{"speaker":"こしば委員","kind":"質問・要望","question":"しかし、いかんせん高額な接種費用が、接種そのものをちゅうちょさせてしまっているのも現実です。ぜひ将来の子育て家庭の負担を軽くするために、アブリスボの接種費用の一定の助成を強く要望したいと思いますが、区のご見解をお伺いいたします。","respondent":"五十嵐保健予防課長","answer":"恐らく主治医の許可がないところで打つということは難しいと考えられますし、全国的にできるような体制を整えていくことが必要かと考えております。ですので、国の検討会を待ちまして、定期接種化されるのを、様子を見ながら検討させていただきたいと考えております。","id":"exchange-048"},{"speaker":"こしば委員","kind":"質問","question":"そのときは大変、専門家の間では高く評価されたと聞いております。ぜひ区民に周知をお願いしたいと思いますが、最後、その周知についてご見解をお伺いしたいと思います。","respondent":"五十嵐保健予防課長","answer":"周知についてですが、現在は周知を全く行っていない状況です。様々な予防接種につきましての周知は必要かと考えますので、状況を見ながらホームページ等での周知も考えていきたいと考えています。","id":"exchange-049"},{"speaker":"塚本委員","kind":"質問","question":"初めに３１５ページ、もったいないプロジェクト等ということで伺っていきたいと思うのですが、フードドライブや。どういったものになっていくのかというところでお伺いしたいと思います。","respondent":"中西環境課長","answer":"連携協定に関しまして、まだ具体に詰めているところではございません。事業者と検討していますが、連携ができないかといったところで、調整しています。","id":"exchange-050"},{"speaker":"塚本委員","kind":"質問・要望","question":"これから詰めていくというようなところかと思います。そういったことで包括的な連携協定みたいなものを考えているのかというところを１つ確認させていただきたいのと、商店街や、お考えをお伺いします。","respondent":"中西環境課長","answer":"今、想定しておりますのは、２３区の中でも導入実績のあるアプリを検討しています。今後進めていくに当たりましては、どういったイベントがいいのかといったところもありますけれども、様々な形を検討してまいりたいと思ってあります。","id":"exchange-051"},{"speaker":"塚本委員","kind":"質問","question":"５％ぐらいの廃棄というのは計画上の中に織り込んで、生産というか、作っていく。これは１つ、今回のアプリを展開する上でも大事な考え方かと思いますけれども、最後に区のご見解をお伺いしたいと思います。","respondent":"中西環境課長","answer":"今、導入を検討していますアプリに関しましても、いわゆるレスキュー隊というような言い方をしているものです。私どももあくまでも、もったいない推進店からの派生の事業と捉えてありますので、食品ロスに関しまして引き続き取り組んでまいりたいと存じます。","id":"exchange-052"},{"speaker":"塚本委員","kind":"質問・要望","question":"次に３０５ページの帯状疱疹ワクチン接種助成の件をお伺いしたいと思います。２分の１は都の補助で助成しているというところがあるのですが、常に２分の１は区のやり方に応じて補助されるものと捉えてよろしいのか尋ねました。","respondent":"五十嵐保健予防課長","answer":"帯状疱疹ワクチン助成についての東京都の補助についてですが、区が実施しているものの半額の補助をしていただいていると認識しています。","id":"exchange-053"},{"speaker":"塚本委員","kind":"質問","question":"区として今後、定期接種の中でも定期接種の年齢が５０歳以上にはならないのだろうという中で、この補助額の考え方は区としていかがでしょうか。お伺いしたいと思います。","respondent":"五十嵐保健予防課長","answer":"上限か何かがあったように記憶しておりまして、それで恐らく１万円とか１万１,０００円の区が多かったのはそのせいではなかったかと考えております。","id":"exchange-054"},{"speaker":"塚本委員","kind":"質問・要望","question":"より区民にとって使いやすいというか分かりやすいというか、そういう助成であってほしいと求めましたので、よろしくお願いしたいと思います。都の補助額というのは上限が１０万円ということになっておりまして、上限３万円と品川区が今している理由について、初めにお伺いしたいと思います。","respondent":"若生健康課長","answer":"区の検討段階のところでの各先行区等の調査におきましては、その３割程度を補助するのが適切ではないかという考えから、上限３万円としています。ただ、今後、がんの当事者からのご意見や声といったところも踏まえながら考えてまいりたいと考えております。","id":"exchange-055"},{"speaker":"塚本委員","kind":"質問・要望","question":"使える予算の上限が決められるというような類いのものと伺っていますけれども、例えば上限３万円から１０万円、何かしら。そこについて最後にお伺いしたいと思います。","respondent":"若生健康課長","answer":"アピアランスケア事業については、ポイントの上限の制限から外れておりますので、そういったことは影響しないと考えております。","id":"exchange-056"},{"speaker":"おぎの委員","kind":"質問","question":"本日は、３０５ページ、予防接種費、新型コロナウイルスワクチン追加接種についてお伺いいたします。このデータを見てどう思われますか。","respondent":"五十嵐保健予防課長","answer":"３年にわたって予防接種を実施してまいりましたので、予防接種を受けた後に具合が悪くなった方などが申請されている状況と考えておりますので、今後少しずつ減ってくるものかと考えております。","id":"exchange-057"},{"speaker":"おぎの委員","kind":"確認","question":"政府やマスコミは言いませんが、日本の新型コロナワクチン政策は果たして正しかったのでしょうか。平成１１年、地方分権一括法で自治事務と再確認されていますが、今回のコロナワクチンに関しては法定受託事務でした。","respondent":"五十嵐保健予防課長","answer":"実際、データを見ましても、ほかの予防接種と比して、特別強く被害があるというような認識は持っていないところです。定期予防接種として実施されるものですので、もちろん私どもは実施していくという形になりますが、予防接種に関する情報につきましては。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問","question":"私からは、３１３ページの温暖化対策事業に関わって、気候危機打開に向けた取組について伺います。その認識を品川区も持っているかどうか伺います。","respondent":"中西環境課長","answer":"品川区環境基本計画の中でも、２０３０年度カーボンハーフ達成実現に向けてということでうたってあります。２０３０年度までにカーボンハーフを達成するといった意気込みは持っているところです。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"これをさらに進めていってほしいと求めましたけれども、この間も指摘していますが、具体的にどうやって実現していくのかということが重要です。は２０３０年カーボンハーフに向けて、具体的なロードマップを示すべきだと思いますが、いかがか尋ねました。","respondent":"中西環境課長","answer":"オール東京６２市区町村の共同事業の中で、例えば産業部門、家庭部門といったものの排出量といったものは算定されてあります。そういったものもにらみながら、様々取組を進めてまいりたいと考えているところです。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問","question":"私が伺ったのは、再エネ、省エネでどれだけ減らしていくのかと。そういうことを含めてやっていかなければならないと思いますけれども、いかがか尋ねました。","respondent":"中西環境課長","answer":"いずれも５０％なのかといったところですが、１つ、目標としてはそこになってくるかと思います。一部、出っ張り引っ込みはあるのかと考えていますが、総体としては５０％削減といったところを目標にしているものです。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問・要望","question":"合計で２６０ｔＣＯ２の削減ということですけれども、２０３０年の目標達成には６６２ｋｔＣＯ２の削減が必要だということで、また桁が違う。やはりこれを増やしていかなければ達成できないと思いますので、どうやって再エネを増やしていくのかというところを伺いたいと思います。","respondent":"中西環境課長","answer":"１つは太陽光を増やしていくといったところで、今取り組んでいるものです。そういったものも含めながら検討してまいりたいと考えています。","id":"exchange-062"},{"speaker":"のだて委員","kind":"提案","question":"そのためにも、住宅を建築する際の地球温暖化対策の相談窓口を設置することを提案しますが、いかがでしょうか。ほかのところでもいろいろやっていると思うのですけれども、区としても推進すべきだと思いますが、いかがか尋ねました。","respondent":"中西環境課長","answer":"実際、我々としてもどのように拡大していくかといったところの検討を今進めているところです。様々、どういった形がいいのか検討してまいりたいと思います。","id":"exchange-063"},{"speaker":"のだて委員","kind":"提案","question":"具体的に相談窓口の設置や、初期投資ゼロで設置できる屋根貸し事業ということで提案させていただきました。ぜひ考えて、進めていっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"中西環境課長","answer":"先ほどもご答弁申し上げましたが、東京都の補助金等とも併用できる形で、かなり負担率としては減っているような状況もあります。私どもで課題と考えているのは、設置に向けて進められるかといったところについて、検討してまいりたいと考えています。","id":"exchange-064"},{"speaker":"のだて委員","kind":"質問・要望","question":"超高層ビルはそもそもやめるべきだとは思いますけれども、区内の住居は共同住宅が８割という状況ですので、対策が必要だと思います。区として賃貸住宅への太陽光発電設置に向けた取組を進めているのか伺いたいのと、今、助成事業で賃貸住宅は何件あるのか、割合も伺えたらと思います。","respondent":"中西環境課長","answer":"太陽光発電に関しましては集合住宅も対象とさせていただいているものです。細かい内訳に関しては、今、持ち合わせてございません。","id":"exchange-065"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ賃貸住宅も含めて設置できるようにしてほしいと求めましたし、再エネだけでなく省エネ分野でも大きく進めていかないと、カーボンハーフ、カーボンゼロを実現できないと思いますので、抜本的に取組を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"ひがし委員","kind":"確認","question":"本区ではがん情報をホームページで、令和４年１月から運用を開始していると確認しています。関心の高まりを感じておりますが、この閲覧数が伸びた件について区はどのように分析しているのか、答えるよう求めました。","respondent":"若生健康課長","answer":"令和５年度はアピアランスケアの事業も開始しておりますので、そういったことで非常に関心が高まってきたというところもあるかと考えております。著名人の方ががんを告白したりというニュースなども、一時的に閲覧数が上がる要因にもなっているのかというところで認識しています。","id":"exchange-067"},{"speaker":"ひがし委員","kind":"意見","question":"令和５年７月からのアピアランスケア事業によって、確かにホームページの閲覧数の向上に関係しているのではないかと私も推測いたしました。予算では１６０件程度の助成を想定し、４８０万円の予算を計上しておりましたが、令和５年度の実績についてお答えくださいとの意見を述べました。","respondent":"若生健康課長","answer":"アピアランスケア事業の実績です。１６０件というところに対しまして、助成については１４９件の助成をしておりまして、助成総額が４２３万６,１２８円となっています。","id":"exchange-068"},{"speaker":"ひがし委員","kind":"質問・要望","question":"令和５年７月から開始ということでありますが、４月から遡って支給するということも、議事録を通して確認しています。１点、１５歳から３９歳、その点についても焦点を当てて質問をさせてほしいと求めました。","respondent":"若生健康課長","answer":"区といたしましても、若い世代や働き盛り世代というところでのがんについて、非常に対策を進めていかなければいけないと認識しています。二、三十代の若い方も利用されている実績等もありますので、そういったことで支援に努めているところです。","id":"exchange-069"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今後充実させる必要があると考える取組は何ですか」という質問に対して、患者の費用負担の軽減というものが６３％というような結果になっております。患者の調査では、がん治療が難しくなった場合に過ごしたい場所はどこですかという質問では、自宅が５４.７％と最も多くなっております。","respondent":"若生健康課長","answer":"若年がん患者への在宅支援事業についてですが、幾つかの区や、４０代未満で介護が必要な方への経済的支援を行っているというところは認識しています。","id":"exchange-070"},{"speaker":"ひがし委員","kind":"質問・要望","question":"どうしたいですかと意向を聞いたところ、家族は自宅で見たいということで、ご自宅に帰るという決断をしました。国の動向だけではなくて品川区としても考えていかなければいけないかと思いますので、こちらについては重ねて要望します。","respondent":"石橋品川保健センター所長","answer":"令和５年度は保健センターにて実施させていただきまして、実施場所の変更や、ケアメニューの内容に変更があったことが減少した要因と考えております。令和４年は出産した方のみの受入れをしておりましたが、令和５年度からは、それが増加の要因と考えております。","id":"exchange-071"},{"speaker":"ひがし委員","kind":"質問・要望","question":"前回の決算特別委員会でも指摘させていただいたのですけれども、ぜひ予約をデジタル化してほしいというような要望をさせていただいておりました。現在の状況、また今後の方向性についても示すよう求めました。","respondent":"石橋品川保健センター所長","answer":"今までは紙申請だったのですが、電子申請になりまして、およそ９割の方が電子で申請していただいている状況になっております。日帰り型、訪問型についても、電子化について検討を進めていきたいと考えております。","id":"exchange-072"},{"speaker":"ひがし委員","kind":"質問","question":"どうですかということを聞いたときに、品川区がこうやって宿泊型についてまずは電子化ができたということは、大変うれしく評価しております。実際に、この回数の増加、そして対象者の拡大に対する区民の声などがありましたら、お聞かせほしいと求めました。","respondent":"石橋品川保健センター所長","answer":"既に８月までの実績で、複数回利用されている方が多数おります。５回利用できる、回数の増加や、使用できる月齢を延長したことの成果が着実に出ているものだと認識しております。","id":"exchange-073"},{"speaker":"ひがし委員","kind":"質問","question":"１回ではなかなか分かりにくいというところが、お困り事、月齢に応じた対応というところができると思います。もう一点聞きたかった休日・夜間診療の件については、また別の機会を設けまして質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"中塚委員","kind":"質問・要望","question":"３１１ページの衛生許可および監視指導より、災害時におけるキッチンカーの営業許可について伺いたいと思います。都全体ではまだ整理されていないということですが、品川区としても、しっかり整理してほしいと求めましたが、それぞれいかがか尋ねました。","respondent":"赤木生活衛生課長","answer":"災害時におけるキッチンカーの営業許可の要否についてのご質問を頂きました。無償で災害支援を行う場合というのは、新たな食品営業許可は不要であるという考えです。","id":"exchange-075"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう対応だということで確認させてほしいと求めましたが、ぜひ掲載してほしいと求めましたが、いかがでしょうか。まずは営業許可についての説明、必要な要件などを品川区のホームページに掲載してほしいと求めましたが、いかがか尋ねました。","respondent":"赤木生活衛生課長","answer":"ホームページへの掲載につきましては、こちらは基本的には防災計画の中で、ホームページ等も含めて整備されていくものであると認識しております。","id":"exchange-076"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、いつ起きてもおかしくないと言われている災害のことでありますので、早急に整えてほしいと求めましたが、いかがでしょうか。踏み出している自治体も伺っておりますので、スケジュール感を持って進めてほしいと求めましたが、いかがか尋ねました。","respondent":"赤木生活衛生課長","answer":"ホームページでの衛生状況や、キッチンカーの営業許可に関する案内というところですけれども、繰り返しとなりますが、防災課と連携しまして計画を持って進めてまいりたいと考えています。","id":"exchange-077"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ防災課と連携して進めてほしいと求めました。食事の管理・提供、メニューや献立も含めて、保健所の力の発揮を重ねて要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"西村委員","kind":"確認","question":"２９９ページ、公害健康被害予防事業費、３０１ページ、乳児健康診査、３０５ページ、予防接種費を、順不同で伺ってまいります。事務事業評価シートを確認し、執行率も高く、有効な事業だと考えています。","respondent":"石橋品川保健センター所長","answer":"小児健康相談事業のご質問になります。３歳児健康診査の結果、経過観察や発達健診などを実施し、早期に対応できるようにということでこの事業を実施しております。","id":"exchange-079"},{"speaker":"西村委員","kind":"意見","question":"例えば、１歳６か月児健康診査で言葉の出が遅いなどは、親も気づきやすく、親からご相談がある場合も多いと思います。国が５歳児健康診査を進めようとしている目的を改めて説明を求めました。","respondent":"石橋品川保健センター所長","answer":"国が目的として掲げているのは、育児の困難さや子育ての相談のニーズを踏まえ、子どもとその家族を必要な支援につなげることを目的としております。特に５歳児健康診査の目的としては、社会的な発達状況の確認ということを、５歳児健康診査の目的として国は掲げております。","id":"exchange-080"},{"speaker":"西村委員","kind":"質問","question":"単体で捉えず大きな事業の中の一つとして捉えてほしいと質問したところ、ご答弁では、健康診査後の相談支援体制の強化が課題と。そこで、区としては５歳児健康診査をどのように位置づけているのか伺います。","respondent":"石橋品川保健センター所長","answer":"円滑な就学に向け、適した支援につなげる機会が重要ということで、５歳児健康診査が必要と考えております。５歳児健康診査を実施するに向け、しっかりとその後のフォロー体制も構築していくように進めるよう、検討してまいりたいと考えております。","id":"exchange-081"},{"speaker":"西村委員","kind":"質問・要望","question":"次に、健康寿命延伸に向けたＣＯＰＤ重症化予防の推進について伺います。そこで、まずは区の現状について、ＣＯＰＤに関してどのような課題を認識されているかを伺います。","respondent":"若生健康課長","answer":"ＣＯＰＤについての課題です。そういったところを課題として考えておりまして、病気を知ってもらって認知度を上げる取組というのが必要であるということを認識しております。","id":"exchange-082"},{"speaker":"西村委員","kind":"質問","question":"ＣＯＰＤを罹患してしない６５歳以上の高齢者に比べて、健康寿命を延ばす上で対策は必須であると考えております。そこで、疾患啓発の取組について、ＣＯＰＤの疾患啓発の区の取組を教えてほしいと求めました。","respondent":"若生健康課長","answer":"国というか、ＣＯＰＤに関する電話相談を今年度から実施しておりまして、ティッシュにそういった案内を入れたりしてＰＲもしているところです。毎年１１月第３水曜日に世界ＣＯＰＤデーというのがありますので、そういったところでの普及・啓発も検討しています。","id":"exchange-083"},{"speaker":"西村委員","kind":"質問・要望","question":"その他啓発もぜひ力を入れていただきたいと思うのですが、令和７年度より次期健康増進計画がスタートしていく中で、伺ってまいりたいと思います。死亡率の減少など、ＣＯＰＤ対策についてどのような目標を設定していくのか伺います。","respondent":"若生健康課長","answer":"「しながわ健康プラン２１」へのＣＯＰＤの取組の反映というところになりますが、死亡率について指標を出すということは区単位では非常に難しいと考えておりまして、今のところは考えているところです。","id":"exchange-084"},{"speaker":"西村委員","kind":"質問・要望","question":"最後に、ＨＰＶワクチンについて伺いたいと思います。短縮スケジュールで年度内に接種が完了できるのだということを周知してほしいと求めましたが、区のお考えを伺います。","respondent":"五十嵐保健予防課長","answer":"国としては標準的な接種方法について早い段階からお知らせすることとしており、短縮のスケジュールについて周知する予定はないと言われております。","id":"exchange-085"},{"speaker":"西村委員","kind":"質問・要望","question":"男子の任意接種補助について伺いますけれども、来年度に対象から外れる高校１年生は、途中から補助を受けられない可能性が高くなってまいります。現状、どのような救済措置を検討されているのか伺います。","respondent":"五十嵐保健予防課長","answer":"現在のところ、４月から周知をさせていただいていた関係もありまして、高校１年生が今年度で終わってしまうということは承知しているところですが、現状では特に延長する考えは持っておりません。","id":"exchange-086"},{"speaker":"西村委員","kind":"意見","question":"対象学年の高校１年生相当の方は、３回目接種が間に合わない場合がある、またそれがどれぐらいの方々に影響を与えるのかということも改めてお調べいただいた上で、ご検討をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-087"},{"speaker":"やなぎさわ委員","kind":"質問","question":"品川区自殺対策計画の直近３年の目標値を教えていただいてもよろしいですか。自殺死亡率の目標値を説明するよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"確認","question":"令和３年度が人口１０万人当たり１４.２人、令和４年度が１３.６人、令和５年度が１３.１人になっております。今年の予算特別委員会での私の質問への答弁の件の確認ですけれども、その確認を一応したいのですが、いかがか尋ねました。","respondent":"五十嵐保健予防課長","answer":"大変失礼いたしました。ただ、共通の認識をするために目標値は定めることとなっておりまして、示しながらやっていくというようなことが示されているものになってあります。","id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"提案","question":"私からの要望というか提案なのですけれども、そういった中で結果的に自殺者が出てしまうのは致し方ないとしても、やはりゼロを目指してほしい。ぜひ目標をゼロでいってほしいと思うのですが、０.５人ずつ減らしているのですけれども、この具体的な根拠は何かあるのか尋ねました。","respondent":"五十嵐保健予防課長","answer":"具体的な根拠と言われますと難しいところではありますが、国で令和８年までに自殺死亡率を平成２７年と比べて３０％減少させると目標を定めているところから、０.５％ずつ、少しずつ下げられるようにということで示させていただいているものです。","id":"exchange-090"},{"speaker":"やなぎさわ委員","kind":"意見","question":"特に自殺率に関して言うと、分母が４０万人ぐらいいて、分子が数十人とか数人なわけです。何か受け止めがあればお願いしますとの意見を述べました。","respondent":"五十嵐保健予防課長","answer":"国でも最終的な目標としては、誰も自殺に追い込まれることのない地域の実現を目指すべきと定めております。先ほど申し上げました３０％以上減少というようなものも挙げておりますので、今年、設定のことについては考えていきたいと考えています。","id":"exchange-091"},{"speaker":"やなぎさわ委員","kind":"質問","question":"次です。飲食店は苦労していると思うのですが、品川区も例外ではないと思うのですが、区としてはどのように今のこの状況を受け止めておりますか尋ねました。","respondent":"小林地域産業振興課長","answer":"やはりご指摘のとおり、コロナの段階というのですか、コロナの期間中は政府の支援措置がかなり手厚かったということもあります。この１０年間の中でも、これはやはり悪いペースといいますか、かなり中小企業にとっては厳しい経済状況になっていると認識しています。","id":"exchange-092"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"それはどういうお店かというと、普通に食べて９００円、トッピングをつけると１,０００円を超えてしまうと。何か最後にあればお願いします。","respondent":"小林地域産業振興課長","answer":"ラーメン店、飲食店につきましては、今回の９月補正の予算も十分活用いただけるのではないかと考えています。","id":"exchange-093"},{"speaker":"こんの委員","kind":"質問・要望","question":"いやいや、このご家族はどうすればいいのですか。こうした事案についてどうお考えか尋ねました。","respondent":"三ツ橋荏原保健センター所長","answer":"周りの方に様々な影響を及ぼしているということで、近隣の方からのご相談についてどのように対応していくかですけれども、非常に難しい問題です。","id":"exchange-094"},{"speaker":"こんの委員","kind":"質問・要望","question":"それで、連携を取っていただいて、一緒にその方のお宅に行ってくださいとお願いいたしました。こうした対応についての連携というところを取っていただきたい、体制をつくっていただきたいと思うわけですが、いかがか尋ねました。","respondent":"三ツ橋荏原保健センター所長","answer":"近隣の方からの様々なご用件、ご要望がある中で、またご当人の人権侵害などを考えながら対応していかなければならないと考えています。ただし、警察との連携に関しましては、しっかりと連携を取っていきたいと思いますので、よろしくお願いいたします。","id":"exchange-095"},{"speaker":"こんの委員","kind":"質問・要望","question":"状況を把握して、適切な医療につなぐ、家族との接触などを図っていただける対策をつくってほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"３１３ページ、時間があれば３２１ページ、それぞれお伺いします。改めてその辺をお伺いします。","respondent":"五十嵐保健予防課長","answer":"もちろん３回接種できなくても、２回分は公費でできる部分もあったりしますので、ぜひ打てる方については打っていただきたいと考えているところです。","id":"exchange-097"},{"speaker":"石田（し）委員","kind":"意見","question":"やるべきだと思います。こういったことも含めて、もう一度、３回目の接種が年度をまたいでも助成をするべきだと思いますが、区のご見解を説明するよう求めました。","respondent":"五十嵐保健予防課長","answer":"子宮頸がんワクチンのキャッチアップにつきましては、３年前ぐらいからやらせていただいていたかと思います。その件もありますので、今のところは特に、キャッチアップのフォローをさせていただいて延ばすということは考えていないところです。","id":"exchange-098"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"コロナ禍で、なかなかこのワクチンを打つこともできなかったのが現状ではないでしょうか。これは要望で止めておきますが、ぜひお願いしたいと思います。","respondent":"高梨都市計画課長","answer":"羽田新飛行ルートに係る様々な声、区へのお問合せは都市計画課で受けておりますので、私から答弁をします。今、お子さんに蕁麻疹のような症状が現れるというような内容での区への区民からのお問合せということは、今まではございませんでした。","id":"exchange-099"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"本当にそうなのかどうかも確認していないですけれども、ぜひ、こういったいろいろな影響があるのです。この要望書が、どうやって国土交通省に行って、国土交通省の中で議論があって、その答えはいつ返ってくるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"石田（し）委員","kind":"意見","question":"では、それも含めてどういった調査をしているのかをお知らせくださいとの意見を述べました。","respondent":"高梨都市計画課長","answer":"しっかりと区民負担軽減につながる取組を早期に検討し、実施していただくといったところも、併せてお答えします。この間の近隣区との連携ですが、また個別に隣の区等々につきましては連絡を取り合って、情報共有を図っているところです。","id":"exchange-101"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"最初に、３０１ページ、小児健康相談についてお尋ねします。この小児健康相談というのは幅広い相談があるかと思いますけれども、主にどういった相談が多いのかというのをお知らせほしいと求めました。","respondent":"石橋品川保健センター所長","answer":"小児健康相談の主な内容についてのご質問になります。こちらは、お子様の発育や発達に対して、通常と比べて少し遅れているのではないかというような相談を、主に頂いているところになります。","id":"exchange-102"},{"speaker":"高橋（伸）委員","kind":"提案","question":"安心して、子どもの子育てをするための取組の提案だと、会派としても以前、強く要望してきたものであります。品川保健センター所長にお伺いしたいのは、健康診査や窓口でリーフレットを配れば解決できるものと思われているのか尋ねました。","respondent":"石橋品川保健センター所長","answer":"保健センターでは、病気や薬についても様々なものがありますので、なかなかポピュレーションアプローチ的なものは難しいものだと考えております。病気のケアについて、何か保健センター、区としてもできないかということは検討してまいりたいと考えております。","id":"exchange-103"},{"speaker":"高橋（伸）委員","kind":"質問","question":"私はそういうふうに理解しましたけれども、やはり私は行政の対応は、まだ十分ではないのかなと考えています。知識の提供とケアの仕方を習得していただく練習の場が必要ではないでしょうかと私は思っているのですけれども、ご見解をお願いしたいと思います。","respondent":"石橋品川保健センター所長","answer":"様々な病気を抱えているお子さんがいることは認識しておりまして、薬なども様々になりますので、今の時点では難しいものではないかと考えております。","id":"exchange-104"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは要望ですけれども、建設３団体に対しても、ぜひ啓発・広報活動をしていただきたい。もしかしたら広報しているのかもしれませんけれども、その辺のところを２点、お尋ねします。","respondent":"中西環境課長","answer":"皆様にご活用いただける助成になっていくかといった部分に関しましては、引き続き検討させていただければと考えています。今どのように周知をしていけば、より活用いただけるかといったところは検討していますので、改めて強化して進めてまいりたいと考えています。","id":"exchange-105"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それは、区の職員の方が行っておられるかと思うのです。逆に業者などに依頼する、委託するという手法もあるかと思うのですけれども、その辺についてお伺いします。","respondent":"中西環境課長","answer":"事前調査結果報告が令和４年度から求められる形になりまして、立入り調査が昨年度ですと９６９件、調査をしているような状況です。今後もどういったやり方がいいかを含めまして、様々、確認しながら検討してまいりたいと思います。","id":"exchange-106"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私からは、３０４ページ、３０５ページの各種健診の拡充とがん検診の無料化を求めて質問したいと思います。高齢者は無料になって本当によかったと思うのですけれども、小児もぜひ無料にしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"五十嵐保健予防課長","answer":"全体の調査をしているわけではないので、大変申し訳ありませんが、どのぐらいの区が無料にしているかというところまでは把握していない状況です。まだ現在、任意予防接種ということになってありますので、現在のところは無料化にすることは考えていない状況です。","id":"exchange-107"},{"speaker":"鈴木委員","kind":"質問・要望","question":"任意ということですけれども、ぜひ無料化に向けてご検討いただきたいということで要望します。がん検診の無料化を求めたいと思いますが、がん検診の無料化について他区の状況などを把握されていたら、その点についても説明を求めました。","respondent":"若生健康課長","answer":"区で実施している様々な健診がありますけれども、当然、最終的には死亡率を減らすという目標でやっている。いわゆる国が推奨している５つのがん検診全てを無料にしている区というのが、２３区中、９区ございました。","id":"exchange-108"},{"speaker":"鈴木委員","kind":"提案","question":"今年、共産党が予算の修正も提案したのですけれども、本当に驚くような額ではなく無料化というのはできるのです。これは共産党の試算ですけれども、区として無料化するとどれぐらいかかるというのを試算したものがあれば、教えてほしいと求めました。","respondent":"若生健康課長","answer":"若干、受診率の増加を見込んだところ、４,０００万円程度の増加というような試算をしております。根本的に、無償化したから全て受診率として解決するかというと、そうではないと考えています。","id":"exchange-109"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう点からも、これぐらいでできるわけですから、ぜひ無料化していただいて、アピールもできるようにお願いしたいと思います。ぜひ続けていただきたいと思うのですが、いかがか尋ねました。","respondent":"若生健康課長","answer":"実施しておりますけれども、現在実施しているがん対策推進計画の策定委員会でも議論させていただいておりまして、それらを踏まえて考えていきたいと考えています。","id":"exchange-110"},{"speaker":"田中委員","kind":"質問・要望","question":"私は、３１６ページの清掃事業関連、それから３２９ページの商店街支援、３２１ページ、時間があれば動物死体処理費についてお伺いします。清掃体制が新たになったということを踏まえ、この１年間の成果、どのような成果があったのかをお聞かせほしいと求めました。","respondent":"篠田品川区清掃事務所長","answer":"清掃事務所の体制についてのお尋ねです。この１２月に分室の解体工事が始まりますので、清掃事務所に移ってきたということで、全体の体制が変わってくるということになります。","id":"exchange-111"},{"speaker":"田中委員","kind":"質問・要望","question":"１点伺いたいのは、平成１２年に都から区に移管されて、時間が大分経過しているのかと。もっと早く体制整備を、区なりの体制に移行できなかったのかという思いがあるのですが、その理由についてお聞かせほしいと求めました。","respondent":"篠田品川区清掃事務所長","answer":"品川区に移管された後も、その２つの清掃事務所がある体制の下、例えば収集など、全て細かく分かれていたということがあります。全体を１つに統一した形の体制の中で清掃を組んでいくということで、今、考えているところです。","id":"exchange-112"},{"speaker":"田中委員","kind":"質問・要望","question":"２０年間は清掃事業以外には使ってはならないという縛りがあって、北品川分室も含めて、体制を変えることができなかったのか。そこの確認をさせていただきたい。","respondent":"篠田品川区清掃事務所長","answer":"それがあったからできなかったというよりも、どちらかというと、やはり２つの清掃事務所体制が長くずっと続いていた部分があるのかなと思います。","id":"exchange-113"},{"speaker":"田中委員","kind":"質問・要望","question":"品川区各所に商店街があって、それぞれの規模に応じて、またそれぞれの要望に応じた商店街支援をしっかりして頂いていることは理解しております。区でできること、今のそういう状況においての、各３商店街に対しての区の対応をお聞かせほしいと求めました。","respondent":"小林地域産業振興課長","answer":"これまでの区の支援といいますか、そういった活用も進められるようなご支援というのですか、地域のご支援もしています。こういったところも含めて、東京都への申出も含めまして、応援していきたいと考えております。","id":"exchange-114"},{"speaker":"田中委員","kind":"質問・要望","question":"産業支援というような観点からも、積極的に東京都との連携の下、丁寧に対応してほしいと求めました。動物に関してはまた改めてお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"吉田委員","kind":"質問","question":"私からは、３１７ページ、資源物再商品化経費と、それから３２５ページ、品川区シルバー人材センター支援事業、２つ伺います。監査結果が出て、その後の対応というのでしょうか、その点についてどのようにされたかご報告を頂きたいと思います。","respondent":"小林地域産業振興課長","answer":"区としても、その対応状況をしっかり今後も守られるようにというところで、その対応を引き続き求めていきたいと考えています。しっかり認識が同じになるようにということで、引き続き適正な対応ができるようにということで、区も求めていきたいと考えております。","id":"exchange-116"},{"speaker":"吉田委員","kind":"確認","question":"今後適正に行われるようにということで努められていると理解いたしました。会員同士の話合いというのでしょうか、きちんと皆さんがそれに納得されているということなのか、その辺について確認したいと求めました。","respondent":"小林地域産業振興課長","answer":"ただいまご指摘の点については、シルバー人材センターの職員と会員というところでの認識、同じ認識であるかというところが大事であると考えています。","id":"exchange-117"},{"speaker":"吉田委員","kind":"質問・要望","question":"次に、３１７ページの資源物再商品化経費で、製品プラスチックのリサイクルについて伺いたいと思います。その周知の成果は適正かつ効果的であったと思われるのか、現時点での評価を伺います。","respondent":"篠田品川区清掃事務所長","answer":"昨年度からモデル実施をしてまいりまして、プラスチック製品の回収をしてきたところで、本年の４月１日から全区展開をしたところです。説明会等も行いまして、それぞれの地域ごとにご説明をさせていただきましたので、かなり丁寧にやってきたという思いを持っているところです。","id":"exchange-118"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほど示しました２つの方法のどちらを選択するのか、もう決まりましたでしょうか。伺いたいと思います。","respondent":"篠田品川区清掃事務所長","answer":"先ほど申し上げた昨年度の説明会のほか、４月の本格実施に当たりましては、そういった一定の成果があったものと認識しています。実際に実施するということで、３年たった後どうなるかというと、それをまた引き続き継続して計画として進めるということではなくて。","id":"exchange-119"},{"speaker":"吉田委員","kind":"質問・要望","question":"ちらほらではありますけれども、２３区内にもありますし、ぜひその活動も参考にしながら決定してほしいと求めました。やはり人工芝を推奨している品川区として、そのプラスチックの有害性というのをどの程度認識されているのか、お考えを伺いたいと思います。","respondent":"中西環境課長","answer":"人工芝自体というよりは、充填剤と言われるゴムチップに化学物等が含まれているといったことは、報道等でも聞いているところです。紙製人工芝といったものが今後、汎用性が高くならないかといったところで、実証実験を進めているような状況です。","id":"exchange-120"},{"speaker":"吉田委員","kind":"質問・要望","question":"内分泌攪乱作用や発がん性、それから発生毒性、低出生体重や不妊増加などにつながると考えています。ぜひ深刻に受け止めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"若林委員","kind":"質問・要望","question":"５歳児健康診査は保険でやられるわけですが、なぜ必要なのか、まず確認させてください。福祉、教育といったところのフォローアップの体制を協議しておられるのか、お聞きしたいと思います。","respondent":"石橋品川保健センター所長","answer":"その後、どういった支援をしていくかというところが重要と考えているところが、区が５歳児健康診査を考えている理由というところになります。今後、今後どういった形で他課と連携を取って協働してやっていくかということは検討してまいりたいと考えております。","id":"exchange-122"},{"speaker":"若林委員","kind":"質問・要望","question":"今回の５歳児健康診査を通して、このネットワークをぜひ力強く構築していただきたいという思いをすごく、この話を聞いたときに感じました。保健所管としての強い気持ちを、役割を、どのように考えておられるかというのを確認させてほしいと求めました。","respondent":"石橋品川保健センター所長","answer":"５歳児健康診査をして終わりという形ではいけませんので、どうフォローしていくかというところがとても重要な部分になってきます。５歳児健康診査自体はきっかけとして考えておりまして、障害の分野を含めまして、区としての体制を構築してやっていければと考えております。","id":"exchange-123"},{"speaker":"若林委員","kind":"質問・要望","question":"信頼関係を築きながらということができれば、すごくいいなと期待しておりますので、頑張ってほしいと求めました。話合いが既にスタートしていると思いますけれども、その内容やご様子について、まず確認をさせてほしいと求めました。","respondent":"遠藤健康推進部次長","answer":"医師会等との話ということで、７月から８月にかけてそれぞれ１回ずつ、開催させていただいたところです。連携して取り組む事業や、まず地域医療連携が今回できたということで、お話などをさせていただいたところです。","id":"exchange-124"},{"speaker":"若林委員","kind":"質問・要望","question":"今の５歳児健康診査などもそうですけれども、関係者のお話を十分お聞きいただいて、四者の施策を進めていただきたい。区民のためにいい施策を進めていただきたいと要望させていただいて、質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-125"},{"speaker":"西本委員","kind":"質問","question":"この２つの事業の目的はそれぞれ何でしょうか。根本的な違いは何でしょうかということです。","respondent":"石橋品川保健センター所長","answer":"月１回程度、見守り支援員が訪問し、定期的なアウトリーチ型の支援の施策になっております。根拠法令や手法、内容等が異なりますので、それぞれ別の事業として必要性を感じて実施しているところになります。","id":"exchange-126"},{"speaker":"西本委員","kind":"質問","question":"それで、児童センターの指導員が継続的に行って、どういう状況ですかと伺っているのです。そういう考えはいかがか尋ねました。","respondent":"石橋品川保健センター所長","answer":"１回きりにはなりますが、４か月健康診査の前、専門的な分野での支援をしていくというところになります。こちらでは一括して今後の支援につなげていくというところを考えておりまして、今のところ、両方とも必要な事業だと認識しているところです。","id":"exchange-127"},{"speaker":"西本委員","kind":"質問","question":"おむつを配ればいいじゃないですか。それから地域の中で子育てをするという意味では、地域コミュニティという意味では最高の仕組みだと思っていますが、その点はいかがか尋ねました。","respondent":"石橋品川保健センター所長","answer":"見守りおむつ定期便は、あくまでも見守りが趣旨というところでやっておりまして、おむつ宅配だけの形とは全く考えていないところになります。正直、育児用品の経済的支援ということで、それをきっかけに行政が毎月しっかり関わりを取れることが重要だと認識しております。","id":"exchange-128"},{"speaker":"西本委員","kind":"質問・要望","question":"何も委託金に１億円をかける必要はないではないですか。費用対効果を含め、今までやってきたことにしっかり自信を持って、それで拡大するべきところは拡大していただきたいとお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-129"},{"speaker":"石田（秀）委員","kind":"質問","question":"海洋投棄は絶対駄目だけれども、プラスチック自体は悪者ですか。私はもう遅いと思っていますけれども、それぐらいのことをやるべきだと私は思っておりまして、それについての考え方も説明を求めました。","respondent":"篠田品川区清掃事務所長","answer":"今後、様々、そういったことも検討の俎上にのせていく必要があるのかもしれないというところは受け止めさせていただいているところです。","id":"exchange-130"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それから、集団回収はメニューをぜひ増やしていただきたい。それからプラスチックは、あまり悪者、悪者と言わないように、ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ご要望としては、４５分に短縮したものを、コース制ではなく６０分にしていただきたいと。利用者の要望を積極的に取り入れたという評価をモニタリングではしているのですが、このようなご要望と、いかがお考えか尋ねました。","respondent":"若生健康課長","answer":"それに継続して出ていただくようなコース型のプログラムというのをそれぞれやっておりまして、コロナ禍で一旦、減らしたりした時期もございました。","id":"exchange-132"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほどの区民の方のご意見なども、いわゆるアンケートボックスに入れたりしたのですけれども、全然改善していただけないと。その方向はいいのですけれども、区民の方々のご意見も改善に努めていってほしいと思いますが、いかがか尋ねました。","respondent":"若生健康課長","answer":"あるいは年１回アンケート調査を行って、利用者の声を伺って、それをなるべく早急に施設の運営に反映しています。なかなか１００％、全て答えるのは難しいですが、なるべくご要望に応えられるように努力しています。","id":"exchange-133"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぜひ要望に応えてほしいと求めました。次に、令和５年度の予算の事項別説明資料では３３１万円が還元されるということですが、どれぐらい収益が還元されたのか尋ねました。","respondent":"若生健康課長","answer":"令和５年度の収益還元金につきましては、６１０万７,６６４円の還元となっています。","id":"exchange-134"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ただ、２０％ということに関しては、以前からお話ししていますが、区の努力についてはまた別の機会にお話しさせてほしいと求めました。これについて金額を入れるべきだと思いますが、いかがか尋ねました。","respondent":"若生健康課長","answer":"還元金につきましては、今後、載せ方については検討してまいりたいと考えております。","id":"exchange-135"},{"speaker":"高橋（し）委員","kind":"質問","question":"というようなことを予算特別委員会で私が質問したら、当時の財政課長は「今後検討していきたいと思います」とおっしゃったのです。ということで半年たったのですけれども、どのような形で財政課は検討して、予算書・決算書等も含めてどのように入れていくのか尋ねました。","respondent":"加島財政課長","answer":"今、決算書につきましては、歳入、諸収入の中の雑入、雑入の中の「等」に含まれているところです。今回、２度目のご意見を頂きまして大変恐縮ですけれども、予算書に向けて検討してまいりたいと考えております。","id":"exchange-136"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今のように区に６００万円という収益が上がるものですから、大変貴重な仕組みですので、その数字が分かるようにしてほしいと求めました。今回、５月に区長がモンゴルを訪問されたのですが、訪問の成果と今後の展開をお伺いします。","respondent":"小林地域産業振興課長","answer":"モンゴル３高専との間で連携協定、また教育・科学省および、ウランバートルにあるＪＩＣＡモンゴル事務所との間で覚書を締結いたしました。今後、モンゴルとのいろいろな交流というのを深めていければと考えています。","id":"exchange-137"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"モンゴルとの交流は前々からお話を伺っていますけれども、今言ったスタートアップ支援というところが、また１つさらに発展したことだと思いますので、ぜひ今後、拡大、そしてモンゴルと緊密な関係を取っていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"},{"speaker":"松本委員","kind":"質問","question":"当事者は結構多いと思うのですけれども、申請が少なかったところの理由をもう少し分析したほうがいいのかなと思うのですが、見解を伺います。今年の７月から始まったほうの支援というか、７・８・９月と３か月なので、直感として伺えればと思います。","respondent":"若生健康課長","answer":"令和５年度についても残りの経過措置が続いているというところで、当初の見込みよりも減ってしまったというところが実情です。１０月になってから、徐々に浸透してきたかと思うので、啓発についても努めてまいりたいと考えております。","id":"exchange-139"},{"speaker":"松本委員","kind":"提案","question":"ご提案、ご要望というところですけれども、実績が高いところに行くという構造があると思います。ある程度、検討を始めたほうがいいのではないかと思うのですけれども、この点はいかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"やはり商店街の街路灯の持つ公的役割を踏まえると、７割程度、安定的に補助として維持されていることが望ましいということで設定しております。","id":"exchange-140"},{"speaker":"松本委員","kind":"質問・要望","question":"政府が延長するかどうかをまだ明確にしていないというのは、この１週間ぐらいでも出ていたので、そこも大きいのだろうと思います。そうはいっても、補助を使っても撤去するお金がないみたいな状況が生まれないのかというところが心配なのですが、その点はいかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"ただいまご指摘いただいたような、もし撤去する場合ですけれども、東京都の補助金で５分の４使えるというのがあります。では残りの５分の１の部分はというところと、我々としては、サポーター制度も入れながら支援しているという状況です。","id":"exchange-141"},{"speaker":"松本委員","kind":"質問・要望","question":"最後、質問する時間が、私のほうが長かったので、できないのですけれども、ただ公共財という部分もあるので、撤去ではなくて、場合によっては区で財産として頂くということも検討していただきたいというところで、最後、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"資金繰りはどうなのでしょうか。区内産業のことですから、品川区としてはしっかりと把握するべきだと私は思うのですが、その辺についてご見解を説明するよう求めました。","respondent":"小林地域産業振興課長","answer":"１つ、我々として気にしているのが、倒産件数というところに関連しまして資金繰り支援です。しっかり地域産業の支援予算を確保しつつ、助成措置なり、いろいろ支援措置というのをしっかり継続してまいりたいと考えております。","id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"今、私がお聞きしたのは、実体経済はどうなのですか。そういうふうに継承してきたかもしれないですが、私はもう変えるべきだと思いますけれども、いかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"では、東京都の実態調査はどれぐらいの母数でやっているかといいますと、調査回答数でいきますと約１,３００社です。大田区の場合は品川区よりも事業所数が４割多い程度ですけれども、あるいは助成金の対象件数などを見ながら対応しているものと承知しております。","id":"exchange-144"},{"speaker":"須貝委員","kind":"質問","question":"ここで、合理化設備への融資あっ旋ではなく、少しでも支援をしてやるべきではないですか。やはりそういうことを考えるべきではないかと思うのですが、ご見解を説明するよう求めました。","respondent":"小林地域産業振興課長","answer":"今回は新紙幣の券売機対応なども進めてまいりますけれども、そういった現場の声というものにも対応した助成金も使っております。そういった中で総合的な支援を行ってまいりたいと考えております。","id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"今、３,０００円でも５,０００円でも、光熱費を少しでも補填していただければありがたいと、みんな思うのではないですか。品川区で３億円を助成しているからには、きちんと私は議会に報告するべきではないかと思うのですが、ご見解を説明するよう求めました。","respondent":"小林地域産業振興課長","answer":"そのほか、医薬品・化粧品、６.１％、理髪店・美容等が５.５％となっています。その中で地域経済が回る仕組みを行っている事業ということで、目的というのを、業種も含めて我々として把握しているものです。","id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"区でやっているプレミアム付区内共通商品券は、意味がないではないですか。一部のところに助成しているようなものではないのか尋ねました。","respondent":"小林地域産業振興課長","answer":"あるいは区外の方も若干、１０％程度はいらっしゃいますけれども、９割近くは区民の方に使っていただいているものです。その中で地域の商店街のにぎわい創出につながるような取組をしていただいていると報告を受けているところです。","id":"exchange-147"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"「健康プラン２１」を確認しましたけれども、女性特有の乳がんや子宮がん、骨粗鬆症などにとどまっています。改めて「健康プラン」に、性と生殖の健康と権利を保障する姿勢を明確にすべきと思いますけれども、いかがか尋ねました。","respondent":"若生健康課長","answer":"リプロダクティブ・ヘルス／ライツについて知見を持たれている専門家の方のご意見やお話も聞かせていただきまして、非常に勉強になったところです。","id":"exchange-148"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"健康課としても性と生殖の健康と権利を計画に明記していただいて、説明もしていただいて広げていただきたいと、強く求めておきたいと思います。リプロダクティブ・ヘルス／ライツは、それは当然、健康課でもそういう認識であるかどうかを確認させてほしいと求めました。","respondent":"若生健康課長","answer":"人工妊娠中絶等の、望まない妊娠というようなところの認識です。女性も含めた全ての方、区民の健康増進というところで、そういうところでどういった取組ができるかというところは今後考えていきたいと考えています。","id":"exchange-149"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"厚生労働省は、第５次男女共同参画基本計画において、昨年の１１月から一部の薬局で緊急避妊薬の試験販売を全国で行いました。こうした情報を区としても、リプロダクティブ・ヘルス／ライツの視点から区民に知らせてほしいと求めましたけれども、いかがか尋ねました。","respondent":"若生健康課長","answer":"開始されているところで、これについては本格実施がまだというところでもありますので、区としては状況を注視しているところではあります。ただ一方で、やはりこういった避妊については、そういったところの正しい知識の周知というところは区として大事だと考えているところです。","id":"exchange-150"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひそれを広げていただきたいのですけれども、とにかく知らな過ぎる、少な過ぎるという状況なのです。なので、女性の身体を守る、そういう権利だということを積極的に健康課としても発信していただきたいということを強く求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-151"},{"speaker":"あくつ委員","kind":"質問・要望","question":"時間があれば３１３ページ、環境保全事業、宅配ポスト設置支援事業について伺っていきます。産後ケア事業についてですけれども、午前中、ひがし委員からも質問があったのですが、私からも具体的な確認をさせてほしいと求めました。","respondent":"石橋品川保健センター所長","answer":"日帰り型につきましては、指定医療機関が３施設、増えました。訪問型・宿泊型につきましては合わせて５回までの利用、１歳未満までの月齢に延長をさせていただいたところになります。","id":"exchange-152"},{"speaker":"あくつ委員","kind":"質問・要望","question":"できれば港区のように６泊７日というように、お母様がゆっくりと過ごせる時間を確保できるようにしていただきたいというのが率直な願いです。１回休んで、そしてまた利用できるという分割利用も可能にしてほしいと求めましたが、いかがか尋ねました。","respondent":"石橋品川保健センター所長","answer":"その中で、泊数の違いがあることも認識しております。泊数は、利用者の声も基に、いろいろ検討はしていきたいと考えております。","id":"exchange-153"},{"speaker":"あくつ委員","kind":"質問","question":"何というのですか、１日２,５００円というのは、自己負担額が安いというところ。これ以上安くしろというのは、なかなか難しいと思うのですけれども、自己負担額の設定を、同等のものをお願いしたいと思いますが、いかがか尋ねました。","respondent":"石橋品川保健センター所長","answer":"令和５年度よりも令和６年度は自己負担額の軽減ということで金額を下げさせていただきまして、努力はさせていただいたところになります。７医療機関で、自己負担額を一律にするかどうかも含めまして、検討していきたいと考えております。","id":"exchange-154"},{"speaker":"あくつ委員","kind":"質問","question":"これは、病院に行ったときに、やはり手間を見たときに、何というのですか、産後ケアの手続の手間が随分違うのだなというお話があったということです。紙の承認通知書の発行などに伴う事前申請の有無は、妊婦が一番利用しやすい形にしていただければと思うのですけれども、いかがか尋ねました。","respondent":"石橋品川保健センター所長","answer":"今、保健センターとしても課題として捉えておりますので、そこの部分は時間を短く対応できるようにと考えております。利用申請書を今、その辺りは、各医療機関とどのような形で手続を進めていけるかということも今後しっかり検討してまいりたいと考えております。","id":"exchange-155"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そういったところもそうだということで、既に２つあるのですけれども、そうしたご相談は今複数あるのでしょうか。区の関係部署の協力体制、組織横断的な問題解決ということを求めているのですけれども、具体的にはどのようにお考えになりますか尋ねました。","respondent":"小林地域産業振興課長","answer":"商店街支援の部署だけでなく、我々は心配というか、懸念しています。道路課と関係情報を共有させていただいて、必要な今後の対処も含めて、連携してやっていこうというような話をしています。","id":"exchange-156"},{"speaker":"あくつ委員","kind":"質問","question":"１点だけ、先ほど松本委員の最後の質問、これは場合としては受けていただけるのかどうか。ここについてどのようにお考えか、最後に説明を求めました。","respondent":"小林地域産業振興課長","answer":"監査の意見書にもあるとおり、基本的には商店街の私有物という扱いです。今後、そういう対処が、基本原則論だけで対処できない場合がないのかというところは考えてまいりたいと考えています。","id":"exchange-157"},{"speaker":"まつざわ委員","kind":"質問","question":"私からは、３２７ページの中小企業活性化事業費のうち、経営相談事業についてお聞きします。どんな相談が寄せられていて、それがどの程度の件数なのか、まず説明を求めました。","respondent":"小林地域産業振興課長","answer":"あるいは経営改善を行うための事業計画の見直し、生産性の向上に向けた助言指導といったものに、経営相談の中で対応しているものです。３番目としまして、経営の事業計画の見直しといったものにつきまして、これが８８件程度と認識しています。","id":"exchange-158"},{"speaker":"まつざわ委員","kind":"確認","question":"１番が要は金融、２番目が開業で、３番目が見直しということは確認が取れました。さらにお伺いしたいのですけれども、午前中にも質疑があって、インボイスの話が今回、多く出ました。","respondent":"小林地域産業振興課長","answer":"直接の相談件数は０件であると認識しておりまして、やはり近隣区においても０件、あるいはあってもまたごく僅かな件数であるということを確認しております。","id":"exchange-159"},{"speaker":"まつざわ委員","kind":"質問","question":"相談が０件、近隣も少ないのですか。そういう人は一体どこに相談されているのか説明を求めました。","respondent":"小林地域産業振興課長","answer":"我々が認識しておるところでは、国がインボイスのコールセンターという専門相談窓口を設置しております。令和５年度の上半期には１か月当たり４万件から６万件の相談対応というのが国で行われていたという新聞報道を確認しております。","id":"exchange-160"},{"speaker":"まつざわ委員","kind":"質問","question":"事業者の皆さんの、こういうインボイスの相談というのが、品川区、近隣で言うと大田区という自治体ではなくて、国の今、先ほど相談窓口というのはインボイスコールセンターに集中して寄せられている理由はどういったものなのか、分析があったら説明を求めました。","respondent":"小林地域産業振興課長","answer":"ですので、責任ある解釈や判断を下すことができるのは国ということで、そういう相談が寄せられているのではないかと推測しております。","id":"exchange-161"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"これは、事務事業評価シートを見ましても、しっかりと目標の数字というのはクリアしていることが確認できました。その中で１点、気になったのが、昨年度、高齢者施設等で１１回のＡＥＤの使用があったと記載がありますが、どんなケースだったのか説明を求めました。","respondent":"若生健康課長","answer":"しながわ中央公園で１回、家庭あんしんセンターで１回、それから学校で２回となっております。それから高齢者施設ですと、昼食中の誤嚥によってＡＥＤが必要になったというようなケースが多かったところです。","id":"exchange-162"},{"speaker":"まつざわ委員","kind":"質問","question":"こういうケースというのは、やはりあります。ＡＥＤの場所が分からないと大変困ると思っているのですけれども、ＡＥＤの場所が分かる対応というのが今、品川区はあるのか説明を求めました。","respondent":"若生健康課長","answer":"区では、ホームページ「しながわＭＡＰ」に区設置のＡＥＤを掲載しているほか、日本救急医療財団の全国ＡＥＤマップへのリンクも掲載しております。区設置以外の民間施設も含めた、国内で３０万件以上のＡＥＤ登録があるということで、活用を促しています。","id":"exchange-163"},{"speaker":"まつざわ委員","kind":"意見","question":"しかしこれは、探すときにマップを見るのが大変で、例えばアプリで場所がありますよというのも、実際に最近、新しくなっております。これは、ＡＥＤが解禁されて今年で２０年目になりますので、ＡＥＤの設置場所が誰でも分かるようにしていただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-164"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/285407?Template=document&Id=6855#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":116348,"voices":350}},{"id":"r06-20241009-10","meetingId":"r06-cm10","date":"2024年10月9日","dateIso":"2024-10-09","committee":"議会運営委員会","time":"午後 １時００分～午後 １時０５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"まつざわ委員長","kind":"確認","question":"９月１８日の議会運営委員会で確認しましたウェルビーイング・ＳＤＧｓ推進事業実行委員会監事の推薦についてです。○午後 １時０５分閉会。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759442?Template=document&Id=6839#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":2631,"voices":18}},{"id":"r06-20241010-4","meetingId":"r06-c-settlement","date":"2024年10月10日","dateIso":"2024-10-10","committee":"決算特別委員会","time":"午前 ９時３０分～午後 ６時３４分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を180件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"西村委員","kind":"質問","question":"３３９ページ、踏切への視覚障害者誘導用ブロックの整備、３５３ページ、公園・児童遊園維持管理費から伺ってまいります。公園・児童遊園の維持管理費について伺います。","respondent":"大友公園課長","answer":"公園における熱中症対策といたしましては、日陰をできるだけつくりたいということで、パーゴラに葦簾を設置しまして暑さ対策をしています。葦簾に加えまして、ミストの設置、稼働も併せて行わせていただいているところです。","id":"exchange-001"},{"speaker":"西村委員","kind":"質問","question":"今年の夏も大変暑くなっておりました。そこで、都内の各地で公園での花火が解禁となっておりますが区内の公園で花火が禁止されている理由を伺います。","respondent":"大友公園課長","answer":"品川区立公園条例におきまして、公園の管理に支障がある行為をすることを禁止事項としているというところにおきまして、火災の危険性であったり、近隣に対する煙や音の影響などから禁止しているものです。","id":"exchange-002"},{"speaker":"西村委員","kind":"質問・要望","question":"これまで花火については、子育て世帯からも様々要望をいただいていますが、公園課は特に苦情も多く大変難しい判断になるだろうと思ってきました。その辺りを説明するよう求めました。","respondent":"大友公園課長","answer":"全面的に禁止している区から、認めている区まで様々あると認識しています。区といたしましても、他区の状況も踏まえまして、来年の夏に向けて検討を進めてまいりたいと考えています。","id":"exchange-003"},{"speaker":"西村委員","kind":"質問・要望","question":"これからの公園管理を考える上で、ぜひ取り組んでいただきたいテーマだと考えていますので、これは要望とさせてほしいと求めました。２点伺いたいのですが、そしてまた、入れる公園内で入れない区域のルールなどがあれば説明を求めました。","respondent":"大友公園課長","answer":"犬を連れて入ることができる公園、また、児童遊園の数は、計２０か所となっています。植物が生えている植栽帯や芝生、花壇などへの立入りはできないという形のルールで運用させていただいてあります。","id":"exchange-004"},{"speaker":"西村委員","kind":"質問・要望","question":"区民の方が知らないことで、先ほどからの質問につながるのですが、なぜペットが公園に入っているのだというふうな苦情も入ってくると伺っております。実際に使う方が現地で困っていることについて把握をする必要があると思いますが、どのような整備をされたのか伺います。","respondent":"森道路課長","answer":"踏切手前部の点字ブロックの設置につきましては、苗木原踏切ですけれども、令和４年度から当事者の方とお話をさせていただきまして、昨年度、実際に現地で、立ち会っていただいて、どういった部分で困っているかを確認したところです。","id":"exchange-005"},{"speaker":"西村委員","kind":"質問","question":"１点伺いたいのが、立ち止まってしまって、引き返そうとしてしまわれたと記録されております。ぜひ歩道の延長沿いで踏切の中にも点字ブロックをつけていただくご検討をお願いしたいのですが、いかがか尋ねました。","respondent":"森道路課長","answer":"鉄道事業者のほうで中に設置していただくように、今、協議を進めているところです。引き続き、早期の整備について進めていきたいというふうに思っております。","id":"exchange-006"},{"speaker":"西村委員","kind":"意見","question":"中に入ってしまったかどうかということも大変分かりづらいというのは、本当に今、おっしゃっていただいたとおりであると思います。ぜひとも引き続きご準備、そして整備をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問","question":"３３９ページの、３５９ページの住宅・建築物耐震化支援事業について、耐風診断についてお伺いしてまいります。昨年度は東急電鉄の各線と交差する１４か所について整備を進め、残る１２か所についても、今後の方向性の展開についてお聞きできればと思います。","respondent":"森道路課長","answer":"区内の踏切は、東急電鉄が一番多いところですけれども、ＪＲと京急電鉄にもあります。ＪＲと京急電鉄につきましては、今年度、これから協議を進めていきまして、しっかりと踏切手前部の整備を進めていきたいというふうに考えております。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"特に障害者に配慮すべきと指定された３か所の踏切を優先して、線状ブロックは４本線ですが、２本線で対策措置がとられています。現場でアンケートをとったということでお聞きしておりますが、どういったお声があったのか、お聞きできればと思います。","respondent":"森道路課長","answer":"当時は、国や都と、それから市町村と同じような統一的なデザインでやってほしいというようなお声があったというふうに認識しております。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"できないことだと思いますが、そこに寄り添うことはできると思いますし、それも行政でもできることだと感じています。その現場の声を大事にして力強く進めてほしいと求めましたが、その上で区のお考えをお聞きしたいと思います。","respondent":"森道路課長","answer":"音声誘導につきましても、それについても障害者支援課と一緒に、当事者の方の意見を聞きながら進めているところです。これもしっかり引き続き行っていきまして、視覚障害者の方が安心して道路、踏切を通行できるように進めていければというふうに思っております。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"地面を確認しながらよりも素早く安心して渡ることができると視覚障害者の団体、また、地域の視覚障害者の方からのお声があります。踏切内も含めて一体的に進むように求めたいと思いますが、その反応の状況も含めて、区のお考えをお聞きできればと思います。","respondent":"森道路課長","answer":"旗の台駅の少し北側にあります荏原中延２号踏切、そちらについては、令和７年度中の踏切内の整備が求められているところです。鉄道事業者も、これを目標に設置していくというふうに聞いておりますので、引き続き協議を進めていきたいと考えています。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"質問","question":"続いて、住宅・建築物耐震化支援事業について質問いたします。ここについて、耐風診断の区の認識をお聞きできればと思います。","respondent":"森建築課長","answer":"令和元年に起きました台風の影響で、千葉県で大きな被害が出ているということは認識しております。区内でも被害が出ておりまして、屋根の耐風診断というもの、国の補助もあるということは認識しています。","id":"exchange-012"},{"speaker":"ひがし委員","kind":"確認","question":"最初に、おもてなしトイレ整備費についてお伺いします。品川区でも、令和９年度までに洋式化が完了すると議事録でも確認させていただきました。","respondent":"大友公園課長","answer":"令和６年度、１０か所の実施を予定しておりまして、１０５か所、８１％の洋式化が完了する予定になってあります。毎年１０か所程度の洋式化を進めまして、令和９年度に全１２９か所の洋式化を完了させるという考えです。","id":"exchange-013"},{"speaker":"ひがし委員","kind":"確認","question":"進捗について確認することができました。このような区民の声を受けて、区の認識、また、今後のトイレ整備についての見解を説明するよう求めました。","respondent":"大友公園課長","answer":"現在整備を進めているところにつきましては、洋便器化を優先して取り組んでいるところです。今、委員からお話がありましたように、そのときに広く地域の方からのご意見等々をいただきながら進めていきたいと考えているところです。","id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問・要望","question":"こちらは重ねての要望とさせていただき、次の質問とします。次に、交通安全啓発費に関連して、電動キックボードを中心に、交通安全啓発とヘルメット着用の指導強化についてお伺いいたします。","respondent":"山下交通安全担当課長","answer":"１件も発生していないところでしたけれども、本年に入りまして、８月末現在、８件、電動キックボードが関与する事故が発生しているです。なお、幸いなことに、大きな事故、大きなけがにつながる事故ではなく、軽症ということで聞いているところです。","id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問","question":"着用している県は最大で７０％近く、低いところでは５％程度にとどまる地域など格差が出ているというような評価になっておりました。その点について、ヘルメット着用率、上昇率等わかりましたら、説明を求めました。","respondent":"山下交通安全担当課長","answer":"数字がないのでお答えすることはできませんが、令和５年度末、１年後には１１％ほどまで上がっている状況になります。２か月ほど調査したところの結果になっておりますが、いずれにしましても、徐々に着用率は上昇してきているところであると認識しております。","id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問","question":"その点についても改めて質問しますので、この後お答えください。その点についてもご見解をお聞かせほしいと求めました。","respondent":"山下交通安全担当課長","answer":"若者に対する指導等ですけれども、現在は警察署と連携をとりまして、高校生など、そういった方に実技教室を行っているところです。そういった機会を捉えて、今後のヘルメットの着用率向上に向けた対策をとるようなことも申入れしてまいりたいと考えているところです。","id":"exchange-017"},{"speaker":"ひがし委員","kind":"質問・要望","question":"こちらは要望なのですけれども、課長に確認したところ、このヘルメット助成が活用できるということでした。防災訓練に障害がある方も参加できるようにとの要望を以前から求めておりました。","respondent":"伊藤災害対策担当課長","answer":"何かあれば対応するということでお伝えはしていますけれども、なかなかそこに至らなかったというような点は反省点であるかなと認識をしています。","id":"exchange-018"},{"speaker":"ひがし委員","kind":"質問・要望","question":"他区の事例等を確認させていただきました。このような活動を品川区でもぜひ進めていただきたいと思っているので、その点について見解を説明するよう求めました。","respondent":"伊藤災害対策担当課長","answer":"どういったニーズがあるのかということを把握した上で、今後の訓練に反映させていただければと考えております。支援する側の訓練としましては、障害者を車椅子で移動させるような訓練もやったりできますので、そういったことも広報していければと考えています。","id":"exchange-019"},{"speaker":"ひがし委員","kind":"質問・要望","question":"最後に、個別避難計画は福祉部を中心に進めていると思いますが、具体的な避難支援にどのように活用しているのでしょうか。時間が短いので、答えられる範囲で、答えるよう求めました。","respondent":"平原防災課長","answer":"避難行動要支援者につきましては、避難行動要支援者名簿を作成し、できれば訓練などに役立てていただくといったことで取組を進めさせていただいているところです。","id":"exchange-020"},{"speaker":"ひがし委員","kind":"質問・要望","question":"この点について、本当に災害医療というところとか、障害がある方の防災の観点はすごく大切だと思っているので、この点については、ぜひ総括のところでも改めて質問させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"質問なのですけれども、令和５年度の区営住宅入居者のうち、保証会社を使っている方は何％ぐらいいるのか、もし分かればお伺いしたいと思います。併せて、改めて区営住宅でも入居の際の保証人を不要とするよう求めますけれども、いかがか尋ねました。","respondent":"川原住宅課長","answer":"そういった一律の対応が場合によっては必要であるというふうに、先ほど申し上げた二十数名の滞納者の方には、しっかりと寄り添った対応をしています。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"公営住宅の入居に際して連帯保証人等を求めることは、かえって公営住宅法の趣旨に反する結果を招いてしまっていると書いています。１３か月分の家賃を払っている先ほど紹介した方の負担軽減にもなりますし、区営住宅の保証人不要へ改正を求めますけれども、いかがか尋ねました。","respondent":"川原住宅課長","answer":"現在は、区営住宅の入居の要件は、保証人を立てることを要件としております。しっかりと引き続き寄り添った対応しつつ、今後も入居要件としては、保証人を置くという形で現在は考えているところです。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いたいのは、再開発に同意してほしいと言われたあげくに、最後には必ず同意書にサインを迫られたということでございました。伺いたいのが、私はこの再開発に不同意ですという通告書が届いているかと思うのですけれども、それは間違いないか尋ねました。","respondent":"中道都市開発課長","answer":"不同意の件につきましては、区のほうにも提出されていることは確認しております。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"伺いますけれども、再開発というのは、借地権者、土地所有者、どちらもそれぞれ権利者の数、３分の２以上いないと本組合は認可されません。かなり大きいと私は思うのですけれども、今の要件に沿って、それぞれどれぐらいを占めているのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"今、準備組合のほうで、同意について地権者の方に対して個別面談等を行っているということは聞いております。法的要件は、土地、借地権等の３分の２以上というところで、現在、まだその３分の２に到達していないということは報告を受けています。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"それで、私が伺ったのは、この不同意を出された方が、かなり大きな面積の地権者なのです。割合を占めている方なのでしょうかということを伺いたいのと、その方がなぜこの再開発に不同意なのかという理由です、区としての認識を伺います。","respondent":"中道都市開発課長","answer":"一個人の全体に対する割合というところは、今、手持ちに資料がないのでお答えできない状況です。今、自宅の庭に大きな家がある、そういった風情のある庭は維持していきたいというようなことは聞いております。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"これ、やるべきだったのではないでしょうか。伺いたいと思います。","respondent":"中道都市開発課長","answer":"進むとなれば、品川区としましては、公益的なまちづくりというところに補助金に対して支援をしていくです。やはり一時期、声が大きい場面はございましたが、双方適正に意見交換を交わしているというふうな認識です。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"３６７ページ、そして３３９ページ、無電柱化推進事業についてお伺いいたします。第１弾となる東品川海上公園では、公募が行われていて、１１月ぐらいには事業者が決定されるというようなスケジュールになっております。","respondent":"大友公園課長","answer":"事業の実施に関して理解を得たです。事業者の公募開始に向けた準備を進めている段階となってございまして、今後、早い時期に公募指針を公表いたしまして。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"少し遅れてしまうのでしょうか、その辺りの確認と、その辺りはどうお考えか尋ねました。","respondent":"大友公園課長","answer":"公募を実施するに当たっての地域調整が最近ついたというところ、慎重に公募指針の内容を詰めていくというところで実施をしているところで、令和７年度の事業工事の全体スケジュールにつきましての変更は。","id":"exchange-029"},{"speaker":"筒井委員","kind":"提案","question":"ですから、どうやって逃げたらよいのかとかということを楽しみながらやっていただき、そして総合防災訓練でリアルなものを体験していただく。そうしたことも今後必要になっていくのかなと思っているのですけれども、その辺り、区のお考えはいかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"これは今年度初めての試みですので、今後どうなっていくかということは、今回検証した後に、来年度にはまた改めて検討していきたいと考えております。ＶＲを使った地震時の仮想空間における対応ですとか、そういった導入を踏まえて、今後も検討させていただければと存じます。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"マンション防災についてお伺いいたします。品川区のロゴマークを印刷できるのかどうか分かりませんが、その辺り、いかがお考えか尋ねました。","respondent":"平原防災課長","answer":"ぜひ管理組合で考えていただきたいというような観点でお配りしていますので、そういったことを書いて配布するというようなものではございません。","id":"exchange-031"},{"speaker":"筒井委員","kind":"意見","question":"１棟につき１基なのですけれども、６基中１基あっても、残りの５基に乗っているときに地震があったらどうするのかという問題もあります。対応してくださいということをお伝えしていってほしいなと考えていますので、その辺り、今後どのように展開していくのかお伝えくださいとの意見を述べました。","respondent":"平原防災課長","answer":"マンションのチェアですが、１基だけあってもどうすることもできないものですので、管理組合としては何をしなければならないのか。そういったところも含めて、今後、進めていただきたいということはお伝えさせていただいているところです。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"区道の無電柱化率は約７.２％ということでしたけれども、２０２９年度までで、２０２４年度が中間年度です。２０２９年度までに、これ、１００％達成可能なのかどうかを説明するよう求めました。","respondent":"森道路課長","answer":"優先的に行うものについてしっかりと進めていこうということで、１００というふうな数字を書かせていただいているところです。今、３路線動いておりますけれども、東京都とも新たな会議体も立ち上がりまして、それぞれ進めていきたいというふうに考えております。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"現実的には、新しい技術の活用などを行っていただき、ぜひ区道も加速していっていただきたいと存じます。ぜひよろしくお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"せらく委員","kind":"質問","question":"３６７ページの防災関係組織経費、３３９ページ、道路バリアフリー整備費から質問をいたします。停電時に避難所などで使えるポータブル電源は、区で何台所有していて、どういった施設に配置をしているか説明を求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"避難者への支援といたしまして、各避難所に１台ずつ。各協議会に１台ずつ、計５台のポータブル蓄電池を備蓄しています。","id":"exchange-035"},{"speaker":"せらく委員","kind":"質問・要望","question":"２０２２年１０月に、ソーラーパネルを５つ、ポータブル電源も５台ずつ寄贈いただいていることを確認しました。現在、区として、どこで保管をしているか、これまでどのような場で活用してきたかを説明するよう求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"こちらは、各協議会で、毎年１回、訓練を実施しています。そちらで実際にその蓄電池を使ってみたり、訓練の際に点検や充電などを行っている、そういう状況です。","id":"exchange-036"},{"speaker":"せらく委員","kind":"確認","question":"この寄贈いただいた分も、きちんと年に１回、訓練で使用できている、活用できているということは確認がとれました。その訓練のときに、ソーラーパネルからも、充電はされたかという点を説明するよう求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"ソーラーパネルでの充電を実施したかどうかですけれど、屋外で、大体１０時間近く置いておく必要があります。普通の電源からコードを差して点検・充電を行っているという対応をしています。","id":"exchange-037"},{"speaker":"せらく委員","kind":"質問・要望","question":"例えば、どこにパネルを設置するかとか、そういった確認だけでもしていただきたいというふうに思いました。品川区では、各家庭でもポータブル電源や自然エネルギーで蓄電できるものを用意したほうがいいか、どういうふうにお考えか尋ねました。","respondent":"平原防災課長","answer":"現在、災害情報をとっていただくためには、電子機器は非常に重要ですので、各ご家庭でポータブル電源を用意いただくということは非常に重要なことかと思ってあります。","id":"exchange-038"},{"speaker":"せらく委員","kind":"質問","question":"訓練や防災イベントなどで、来場者、区民が触れる機会などは用意していらっしゃいますか尋ねました。","respondent":"平原防災課長","answer":"今、全戸配布を開始させていただきました新たな「しながわ防災ハンドブック」などでも、そういったものが重要だということを触れしています。防災用品のあっ旋という形でもご紹介していますので、さらなる周知も含めまして、今後とも広めてまいりたいというふうに考えてあります。","id":"exchange-039"},{"speaker":"せらく委員","kind":"質問","question":"次に、道路バリアフリー整備費から１点だけお伺いします。これは以前からいただいておりますので、皆様も把握していることかもしれないのですけれども、こちらは傾斜をならすことはできるのか尋ねました。","respondent":"森道路課長","answer":"ご指摘の戸越銀座１号踏切ですけれども、確かに坂がきつくて上りづらいというところは、こちらも認識しています。今後、全体的な修繕を行う中で、できる限り勾配が緩やかになるような工夫はしっかりしていければなというふうに思っているところです。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問","question":"私からは、３６７ページ、防災関係組織経費、３６９ページ、応急活動対策費についてお伺いいたします。９月に石川県輪島市へ、携帯トイレなどの支援物資を緊急輸送しましたが、どのような教訓を得て今後の品川区の防災対策へと生かしていくのか尋ねました。","respondent":"平原防災課長","answer":"災害対応に当たりまして、民間支援団体との協働ですけれども、品川区でも支援いただくＮＰＯ法人と協定を締結させていただいてございまして。続きまして、能登の大雨の支援を踏まえた形での区の対応です。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問","question":"眉墨などを支援物資として提供することができれば、女性が微笑んだり、うきうきした気持ちになれる可能性があるのではないでしょうか。今後、心のケアの観点からの検討もお願いしたいと思いますが、区のお考えを説明するよう求めました。","respondent":"平原防災課長、羽鳥防災体制整備担当課長","answer":"私からは、災害時の心の問題についてお答えします。そのような中で、どういう対処をしていくのか、災害後の心の変化にどう対応するのか、そういったところを皆様に提案させていただいているところです。 第３回定例会の補正予算においては、防犯ブザー、そういったものをご提案させていただいているところです。民間企業と協力をしていくのか、そういったところも含めて、様々検討してまいりたいというふうに考えてあります。","id":"exchange-042"},{"speaker":"えのした委員","kind":"質問","question":"私からは、３６５ページ、住宅運営費、３４７ページ、地域交通検討経費についてお伺いいたします。住宅運営費について、令和５年度の区営住宅・区民住宅の団地数、戸数、入居者数などを示すよう求めました。","respondent":"川原住宅課長","answer":"区民住宅につきましては４０名です。","id":"exchange-043"},{"speaker":"えのした委員","kind":"提案","question":"ここに少し引っかかったのですかね、３階建て以上、住戸数１５戸以上であることとなっております。区のご見解をお伺いしますとの意見を述べました。","respondent":"川原住宅課長","answer":"今年度より始まったエレベーター内の防災チェアの設置も踏まえまして、防災への意識、普及の啓発というところは努めていきたいと考えています。","id":"exchange-044"},{"speaker":"えのした委員","kind":"質問・要望","question":"エレベーター２１台、前向きにご検討ということで、確認がとれました。私も視察に伺ったところ、西大井第三ですか、様々形も違うと思います。","respondent":"櫻木地域交通政策課長","answer":"１０月５日まで試験運行という形で、１０月６日から区民の皆様にご利用いただくような形で運行を開始しました。実施としましては、火曜日、木曜日、土曜日、日曜日という形で運行しています。","id":"exchange-045"},{"speaker":"えのした委員","kind":"質問","question":"そこでお伺いします。車のナンバーが横浜ナンバーだったことが気になりまして、なぜご当地の品川ナンバーではないのか、ご説明をお願いいたします。","respondent":"櫻木地域交通政策課長","answer":"今回、グリーンスローモビリティをやらせていただくということで、試行運行ですので、今回は京急電鉄にご協力いただきまして、車両をお借りするということで、京急電鉄が登録されている車両が横浜であったです。","id":"exchange-046"},{"speaker":"えのした委員","kind":"質問・要望","question":"Community Mobility株式会社から、ＡＩオンデマンド交通について、他自治体での取組等についてもお話を伺いました。品川区内でも、地域の実情に即した利用者の利便性を高める取組を要望しておりますが、こちらについてご見解をお伺いいたします。","respondent":"櫻木地域交通政策課長","answer":"今、委員ご指摘いただきましたとおり、品川区内、利便性が高い状況とはいえども、各地区を見ると、なかなか交通課題が残っている地区もある状況ですので、それぞれの地区に応じた取組を進めてまいりたいと考えています。","id":"exchange-047"},{"speaker":"塚本委員","kind":"確認","question":"３６５ページ、３６９ページ、しながわ防災体験館運営費の３点でお伺いしたいと思います。いわゆる道路擁壁点検調査の対象になっているのか、安全確認等は区として行っているのか、ここについてお伺いしたいと思います。","respondent":"森道路課長","answer":"ご指摘の擁壁につきましては、ＪＲの管理でございまして、今回の擁壁点検の中では対象にはしてございません。","id":"exchange-048"},{"speaker":"塚本委員","kind":"質問","question":"区として、どういった形での安全の確保というか、区民のこういった不安に対してのお答えをしていくのかをお伺いしたいと思います。ＪＲの管理責任ということではあるのですけれども、そういったところにおいて、ＪＲとの連携とか、協議とかも含めて教えてほしいと求めました。","respondent":"森道路課長","answer":"区のほうでは、ＪＲ東日本でも独自の要領を持って定期的な点検を行っているというふうに聞いてあります。１６３号線整備について、折を見てご教示いただきながら、区としても安全性について確認をしていきたいと考えています。","id":"exchange-049"},{"speaker":"塚本委員","kind":"質問","question":"どういうものだというふうに認識しているのか、今言える範囲のことになってしまうかもしれませんけれども、最後にお伺いしたいと思います。","respondent":"森道路課長","answer":"安全性は確保されているのだろうと考えていますけれども、それとは別に確認をして、区としても認識をしていきたいというふうに思っております。","id":"exchange-050"},{"speaker":"塚本委員","kind":"質問・要望","question":"では、次に、空き家等対策事業ということで、まず、空き家の対策事業の中に、空き家適正管理の促進というものがあるかと思います。その事業において、区の職員は、この空き家適正管理促進の中でどのような関わり方をされているのか教えてほしいと求めました。","respondent":"川原住宅課長","answer":"区の職員が実施している事業といたしましては、調査員とはまた別に、次のステップで区の職員が現地に行って対応したりといったこともあります。そういったところに、少し遠方になりますが、出張して直接対応するといったことも区の職員の役割となっています。","id":"exchange-051"},{"speaker":"塚本委員","kind":"質問","question":"今後どうなのか、こういうことをお聞きするのは、課としての業務量も間違いなく増えるのだろうというふうに思っているからです。今は区の職員が関わっている部分の負担軽減みたいな話とかは、どのようにお考えなのかお伺いしたいと思います。","respondent":"川原住宅課長","answer":"新たに命令等を発することができる特定空家になる前の未然の状態を防ぐという形で、管理不全空家の認定を新たに年度内にスタートする見込みです。","id":"exchange-052"},{"speaker":"塚本委員","kind":"質問","question":"ということでいくと、区の職員でなければできない、でなければ駄目なところといいますか、職員でないとできない部分が最後は残るというところがあるのでしょうか、お伺いします。","respondent":"川原住宅課長","answer":"区の職員が行うべき空き家の認定の業務は、国のガイドラインに準じて区のガイドラインを策定した上で、そこの認定業務が発生するところです。","id":"exchange-053"},{"speaker":"塚本委員","kind":"質問・要望","question":"この管理不全空家については、今後、品川区内にあるたくさんの空き家の適正管理の中で非常に大事な条例改正になっていると思います。区の職員として関わるべきというか、課長にお伺いしても難しいかもしれませんけれども、最後に一言お願いします。","respondent":"川原住宅課長","answer":"今、区内には、空き家が、適正なもの、不適正なものを含めて、８月末現在で５４０戸近くある形です。しっかりとその部分も促してまいりたいというふうに考えてあります。","id":"exchange-054"},{"speaker":"塚本委員","kind":"質問","question":"今般、報告書が令和６年７月に策定されて公表されていて、一応このしながわ防災体験館がある第二庁舎も検討範囲ということになっております。現在、どのように担当の防災課としては捉えていらっしゃるのか、お伺いしたいと思います。","respondent":"平原防災課長","answer":"しながわ防災体験館ですけれども、今後といいましょうか、そういった検討につきましては、様々な新庁舎あるいは庁舎跡地の全庁的な検討の中で考えていくべきというふうに考えてございまして、防災課といたしましては、個別に何か検討している、そういったことはございません。","id":"exchange-055"},{"speaker":"塚本委員","kind":"質問","question":"もっとやっていってもいいのではないのではないかなというふうに思いますけれども、そういった風水害の対応について、どのようにお考えでしょうか。お伺いいたします。","respondent":"平原防災課長","answer":"しながわ防災体験館を活用して、しながわ防災学校の取組をやっている中でも、風水害をかなり重視した内容をお伝えさせていただいているところです。","id":"exchange-056"},{"speaker":"塚本委員","kind":"質問・要望","question":"今後どうなっていくかということについて、いずれ検討、そういった議論が出てくるかなというふうに想定いたします。風水害の体験とか、防災体験館のアップグレードというものをぜひ検討して進めてほしいと求めましたが、最後に。","respondent":"平原防災課長","answer":"災害に備える意味で防災普及啓発は非常に重要なものだと思ってありますので、体験館も含めまして、今後ともしっかりと対応してまいりたいというふうに考えてあります。","id":"exchange-057"},{"speaker":"おぎの委員","kind":"質問","question":"３５７ページ、同じく３５７ページ、公衆便所費についてお伺いいたします。第７３号議案の資料を見ますと、６００台購入ということでしたが、椅子としての強度はどれぐらいか尋ねました。","respondent":"平原防災課長","answer":"こちらは、委員ご指摘のとおり、８月１日から配布を開始させていただいてございまして、実際に配布が完了した件数でいきますと３７件です。そういったものもやらなければならないのだといったところを認識いただくことが重要かなというふうに考えてあります。","id":"exchange-058"},{"speaker":"おぎの委員","kind":"質問","question":"続きまして、３５７ページ、子どもたちのアイデアを活かした公園づくりについてお伺いします。子どもたちのアイデアを聞くワークショップなどは定期的に行っているのでしょうか、併せてお聞かせほしいと求めました。","respondent":"大友公園課長","answer":"西五反田公園改修工事につきましては、こちらは、令和５年から、令和６年にかけての債務負担行為の工事として実施しています。そのアイデアが少なくなってきた段階等々で実施をしていますが、最近でありますと、子供の森公園の改修に合わせて。","id":"exchange-059"},{"speaker":"おぎの委員","kind":"質問","question":"続きまして、３５７ページ、公衆便所費から、大井町駅前公衆トイレについてお伺いします。誰でもトイレを含む特色あるタワー型個室トイレが６棟建っていますが、こちらの現在の使用率は把握されていますか尋ねました。","respondent":"大友公園課長","answer":"清掃委託等々を実施しているところでございまして、２回のトイレ等々あるのですけれども、回数が通常のトイレより多い形で実施をしているところになってあります。","id":"exchange-060"},{"speaker":"おぎの委員","kind":"提案","question":"過去の議事録を見ますと、犯罪抑止の提案をしている議員はおりましたが、その後、犯罪抑止の取組はどのようになっていますでしょうか。ここにあってよかった、使いやすかったと大井町を利用する方に思っていただきたいのですが、何か計画などがあればお願いしますとの意見を述べました。","respondent":"大友公園課長","answer":"できるだけきれいな状態を保って犯罪の抑止につなげていくという視点で、今、取り組んでいるところです。","id":"exchange-061"},{"speaker":"おぎの委員","kind":"意見","question":"その後もしっかり調査して、改良や次の計画に役立てるということが大切だと思いますので、私も他区の工夫などを探していきます。引き続き、前向きに取り組んでいただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"山本委員","kind":"質問","question":"３６７ページの防災訓練経費、３６９ページの防災普及教育費、３７１ページの防災情報配信経費について伺います。９月２９日、西大井広場公園で開催された大井第三地区の総合防災訓練に伺いました。","respondent":"伊藤災害対策担当課長","answer":"一方で、訓練参加者が限られてしまうというような課題があるのではというような意見も受けているような状況です。まだ１か所でしか実施してございませんので、また、この経過を踏まえて改善できるものは改善していきたいと考えております。","id":"exchange-063"},{"speaker":"山本委員","kind":"質問・要望","question":"どうぞよろしくお願いいたします。入場者数はいかがだったか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"今回の訓練につきましては５０６人で、昨年が４７７名でございましたので、若干の増加が見られた状況です。","id":"exchange-064"},{"speaker":"山本委員","kind":"質問・要望","question":"地区総合防災訓練は、それぞれ開催のための工夫を検討いただき、ぜひ残りの３か所でも開催に向けて地域の皆様との粘り強い働きかけを要望します。ご見解を伺います。","respondent":"伊藤災害対策担当課長","answer":"祭りなど、ほかのイベントなどと併せて実施をしていこうなどという動きがあったりということは把握しているような状況です。その地区、地域に合ったような支援を行いまして、より多くの地域の方々がつながりを広められるよう対応してまいりたいと考えています。","id":"exchange-065"},{"speaker":"山本委員","kind":"質問・要望","question":"続いて、防災の普及啓発費に関連して、携帯トイレ全戸配布について伺います。予算特別委員会で質問し、要望させていただきました追加購入を促すためのチラシ等は同封できましたか尋ねました。","respondent":"平原防災課長","answer":"今回の全戸配布につきましては、防災用品のあっ旋チラシにつきましては同封してございません。","id":"exchange-066"},{"speaker":"山本委員","kind":"質問","question":"災害対策には７日分の備蓄が好ましいことから、残りの４日分は自助での購入を促すということだと理解しております。残りの追加購入はどのように促すお考えか尋ねました。","respondent":"平原防災課長","answer":"このハンドブックをよくお読みいただき、災害への備えとして何がどのくらい必要かというものをまずご理解いただくことが必要と考えています。","id":"exchange-067"},{"speaker":"山本委員","kind":"質問・要望","question":"今回、対象となるマンションは何棟でしょうか。申請方式となっておりますが、現状、何棟の申込みがありますか尋ねました。","respondent":"平原防災課長","answer":"本事業の対象となるマンションにつきましては、約３,２００棟です。申込みの実績ですが、本年１０月１日時点で、配布済みの３７件を含めまして９５件となっています。","id":"exchange-068"},{"speaker":"山本委員","kind":"質問・要望","question":"周知方法はどうしていますでしょうか。周知方法に関する現状の認識、今後のやり方を説明するよう求めました。","respondent":"平原防災課長","answer":"周知につきましては、広報しながわ、区ホームページなど、区が持っております全ての広報媒体を活用して周知しています。今後も継続的に周知をしてまいりたいというふうに考えてあります。","id":"exchange-069"},{"speaker":"山本委員","kind":"質問","question":"今回申込みのあったマンション管理組合に、申込時に住所やメールアドレス等の情報を記載いただくのでしょうか。その後、各種情報を郵送やメールで送れるような情報利用の事前承諾をいただいておりますか尋ねました。","respondent":"平原防災課長","answer":"管理組合の名称、メールアドレスにつきましては、電子による申請の方のみについて記載いただいているところです。なお、これらの情報をほかの用途に活用する承諾は得てございません。","id":"exchange-070"},{"speaker":"山本委員","kind":"質問・要望","question":"マンションの住所やメールアドレスを得ることができているので、今後、情報を送付できるように手当てしてはいかがでしょうか。これはご見解を伺います。","respondent":"平原防災課長","answer":"エレベーター用防災チェアの申請を行っていただいたマンションは非常に関心が高いというふうに考えられるところです。このため、区からの情報発信でありますとか、そのための収集につきまして検討が必要かなというふうに考えてあります。","id":"exchange-071"},{"speaker":"山本委員","kind":"質問","question":"次に、防災の情報発信の仕組みについて伺います。現在の区が考える手法について説明するよう求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"災害時の対応は、平時からの取組の延長にあるべきというふうに考えてあります。同じ考えの下、ケーブルテレビ品川など、様々な区が保有する情報発信媒体を活用してまいりたいと考えています。","id":"exchange-072"},{"speaker":"山本委員","kind":"質問","question":"戦略広報課にお聞きしたところ、Ｘが約３万５,０００人、ＬＩＮＥが約５万７,０００人、しなメールが約６,７００人、重複する人もいるでしょう。新たな方策を検討していますでしょうか、他区事例を研究していますでしょうか、説明を求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"委員からご指摘ありましたとおり、各情報発信媒体の登録者数に関しましては、引き続きの課題であるというふうに認識しています。そのほか、例えば防災情報を中心とした情報発信の方法などないか、他区の事例も参考にしながら研究しています。","id":"exchange-073"},{"speaker":"山本委員","kind":"質問・要望","question":"これまでも他の委員の方々がご要望しておりますが、やはり大田区や渋谷区などで導入されている防災アプリは有効ではないでしょうか。ご見解を伺います。","respondent":"羽鳥防災体制整備担当課長","answer":"委員おっしゃられましたとおり、他区では、防災アプリや防災ポータルサイトの導入を防災課としても確認しています。このような事例を参考にしながら、新たな情報発信の方法について引き続き検討してまいります。","id":"exchange-074"},{"speaker":"山本委員","kind":"質問・要望","question":"防災アプリと、そのような効果的な導入方法の検討を要望し、次の質問に進みます。目黒川氾濫注意に関する情報発信と、全般的な都と区の情報発信について、ご見解を伺います。","respondent":"平原防災課長","answer":"災害対策に当たりましては、他の機関との連携は極めて重要と考えています。区のシステムに連携できるものは連携いたしまして、区民にとって分かりやすくお示しできるように努めてまいりたいというふうに考えてあります。","id":"exchange-075"},{"speaker":"山本委員","kind":"質問","question":"次に、大井町駅周辺地区再開発事業について伺います。ＪＲとの協議状況と、３,０００人の帰宅困難者受入れの場所について説明するよう求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"区といたしましては、現在、ＪＲ東日本と３,０００人の帰宅困難者の受入れについて協議を進めているところです。具体的に、避難スペース、備蓄スペースをどこにするのか、そういったところを今、協議を行っているという状況です。","id":"exchange-076"},{"speaker":"山本委員","kind":"質問","question":"帰宅困難者の受入れは、今回のスペース確保で十分となるとの認識でしょうか。新庁舎がその機能を果たす場合は、それも併せて説明するよう求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"開発により今後増加が見込まれるため、エリア防災計画の見直しを行う中で、今後の対策について引き続き検討していきたいと考えています。新庁舎における帰宅困難者の受入れについては、現在、新庁舎整備課と調整しています。","id":"exchange-077"},{"speaker":"山本委員","kind":"質問","question":"ここに大規模な帰宅困難者受入れスペースを確保することが有効であると考えます。ご見解を伺います。","respondent":"羽鳥防災体制整備担当課長","answer":"庁舎の跡地など区有施設や民間事業者の協力も得ながら、引き続き、一時滞在施設の確保に努めてまいりたいと考えています。","id":"exchange-078"},{"speaker":"山本委員","kind":"質問・要望","question":"これまでもほかの委員からご質問がございまして、いろいろと確認が済みました。私からは１点、区の方針の公募への反映についてお伺いいたします。","respondent":"大友公園課長","answer":"公募指針に記載する要件は、できるだけ少ないほうが民間の活力を活用した自由な提案を受けられると考えておりますけれども、区が公園に求めている考えがありますので、一定、区としての考えを公募指針に反映させるべきものと考えています。","id":"exchange-079"},{"speaker":"中塚委員","kind":"質問","question":"３６７ページ、防災関係組織経費に関して、避難所運営マニュアルの改訂、キッチンカーとの災害協定について伺います。そこで、内容について、どのように地域に示されるのか伺います。","respondent":"平原防災課長","answer":"先月９月から順次、地域に示させていただいているところでございまして、年度末までに仕上げたいというふうに考えてあります。お示しするものは示していくというようなところが今回の変更点でございまして、これまで課題となっていたところを大きく前進させようという意図です。","id":"exchange-080"},{"speaker":"中塚委員","kind":"質問・要望","question":"協力もいただきたいということを募っていただいて、そういう場が必要ではないかと思いますけれども、いかがでしょうか。今、こういったところに人手が必要なのだと、いかがか尋ねました。","respondent":"平原防災課長","answer":"並行して進めております地区防災計画の地域における作成でありますとか、そういうような考え方を入れていけばいいのかということは、私どもの中で研究させていただければと思ってあります。","id":"exchange-081"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう少し突っ込んで伺いますと、いろいろな要望が出るのですけれども、その人手も被災者同士ですから。ここが今、大事なところなのではないかと思うのですけれども、改めていかがか尋ねました。","respondent":"平原防災課長","answer":"避難所運営における人手不足だけではなくて、災害時の共助という点では、様々な人の力が要るといったところは、私ども、承知しています。","id":"exchange-082"},{"speaker":"中塚委員","kind":"提案","question":"そこでまず、キッチンカーとの災害協定について、２３区の状況を伺いたいと思います。災害時の食事の提供について、避難所の環境改善を進めてほしいと求めましたが、いかがか尋ねました。","respondent":"平原防災課長","answer":"２３区における状況は、その地域にあるキッチンカーを取りまとめている団体との間で協定が締結されている区があると聞いているところです。今後、しっかりと研究させていただいて、災害時の温かい食の提供といったものを考えてまいりたいというふうに考えているところです。","id":"exchange-083"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういう仕組みを作ることが教訓なのかと、区の見解も伺いたいと思います。ぜひ積極的にキッチンカーとの災害協定について検討していただくことを改めて求めますけれども、いかがか尋ねました。","respondent":"平原防災課長","answer":"まだまだこちらで考えなければならないことがあるものですから、先ほど、研究というふうに言わせていただいたところです。協定自体はまた考えるところもありますので、何かお話がございましたら、こちらのほうでしっかりと考えていきたいというふうに思ってあります。","id":"exchange-084"},{"speaker":"中塚委員","kind":"質問・要望","question":"実際に区役所の前でキッチンカーが始まっているわけですから、ぶっつけ本番ではなく、事前に協定を結んで計画を持って食事の支援を強めていただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"こしば委員","kind":"質問・要望","question":"品川区の放置自転車についてお伺いいたします。放置自転車が多発する傾向のある地域、地理的な特徴についてまず教えてほしいと求めました。","respondent":"山下交通安全担当課長","answer":"放置自転車が多発する場所についてのご質問ですけれども、やはり乗降が多い駅、五反田駅ですとか、大井町駅、また武蔵小山駅、こういったところが多く発生しているところでございまして、撤去活動等を強化しています。","id":"exchange-086"},{"speaker":"こしば委員","kind":"質問","question":"３階はまだ空いているのに、放置自転車はまだまだ絶えないという状況です。この放置自転車に対する対策を講じておりますが、西大井駅周辺の放置自転車の対策として取り組まれていることを教えていただけますか尋ねました。","respondent":"山下交通安全担当課長","answer":"撤去活動、それに加えまして、指導・警告活動を実施しています。撤去活動は、おおむね週に約２日程度、本年度におきましては、９月末までに４５日間撤去活動を行っておりまして、約１５０台の撤去をしています。","id":"exchange-087"},{"speaker":"こしば委員","kind":"質問","question":"近隣のマンションの敷地内に自転車がたくさん放置されてしまっているような場合、品川区として何か対策はあるのでしょうか。マンションと連携した取組、対策についてありましたら、お伺いいたします。","respondent":"山下交通安全担当課長","answer":"以前に比べますと若干減ってきているのかなという認識ではいたのですけれども、まだまだ、今後も引き続き徹底してまいりたいと考えております。","id":"exchange-088"},{"speaker":"こしば委員","kind":"質問・要望","question":"３階建ての駐輪場のそばに、今度新しくレンタルシェアサイクルポートが新設されました。気づきがありましたら、ぜひ教えてほしいと求めました。","respondent":"櫻木地域交通政策課長","answer":"西大井駅の公園のほうに、シェアサイクルポートを最近設置させていただきまして、利用は比較的順調ということで、いつも借り出されているような状況だと認識しております。","id":"exchange-089"},{"speaker":"こしば委員","kind":"確認","question":"このレンタルシェアサイクルによって、放置自転車が減ったという認識ですでしょうか。その辺り、確認させてほしいと求めました。","respondent":"山下交通安全担当課長","answer":"やはり放置自転車対策の３本柱であります駐輪場の整備、啓発活動、これによって徐々に年々放置自転車自体は減ってきているという現状はあります。","id":"exchange-090"},{"speaker":"こしば委員","kind":"提案","question":"少し提案を含めて質問させていただきたいのですけれども、光学通り沿いに広場に入る入口があるのですけれども、そのすぐそばに駐輪場があります。こちらは、およそ何台ぐらい駐輪ができるのか教えてほしいと求めました。","respondent":"大友公園課長","answer":"西大井広場の南側、光学通りに面したところの駐輪場の台数ですけれども、公園利用者を対象としたものですが、２０台、収納を想定した駐輪場となっています。","id":"exchange-091"},{"speaker":"こしば委員","kind":"質問","question":"私の中では、多分５０台ぐらいとめられるのではないかなと思ったのですが、そこはまた改めてお聞きしたいと思います。平日を含めて、こういった駐輪場の整理は、区のほうでどのように取り組んでおられるのか説明を求めました。","respondent":"大友公園課長","answer":"台数の補足から説明をさせていただきたいと思います。そちらのほうで整列等々をしたりする形で、今、整頓をかけているという形になってあります。","id":"exchange-092"},{"speaker":"こしば委員","kind":"質問・要望","question":"先ほど少し答弁、最後のほうがお聞きできなかったのですけれども、自転車のスタンドもぜひ設置してほしいと求めました。やはりそういったことで放置自転車の対策にもなってくると思いますので、その辺りを改めてお考えを教えてほしいと求めました。","respondent":"大友公園課長","answer":"整列してとめるより台数を増やす２段ラックとかもあるかと思うのですけれども、白線などいろいろな対策も含めまして検討を進めてまいりたいと考えています。","id":"exchange-093"},{"speaker":"こしば委員","kind":"質問・要望","question":"なかなか、中に入れば駐輪場がはっきり分かるのですけれども、そもそも駐輪場がここにあったのかという話も実際に聞いたことがありました。ぜひ周知してほしいと求めましたし、その辺りもぜひ幅広く考えていただきまして、放置自転車の対策に取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"やなぎさわ委員","kind":"確認","question":"春先、私も見に行きまして、展示の内容を確認してまいりました。現在の展示の状況、おもちゃみたいなものがなかったので、今どうなっているか説明を求めました。","respondent":"大友公園課長","answer":"えさを利用した遊具の一種、えさを取り出すために遊ぶ道具を入れさせていただいてあります。それをランダムに日替わりとか、週替わりで入れ替えて実施しているところになります。","id":"exchange-095"},{"speaker":"やなぎさわ委員","kind":"質問","question":"様々工夫されているようで非常に安心しました。１個しか入っていなかったりする日があるみたいで、その点は、現状どうなっていますか尋ねました。","respondent":"大友公園課長","answer":"私の記憶にあるの話でお答えすると、複数入っているときは、布と何かという形で入れていたと記憶しております。今後、複数の導入等ができないか検討してまいりたいと考えております。","id":"exchange-096"},{"speaker":"やなぎさわ委員","kind":"質問","question":"予算特別委員会のときにお伺いしたときに、あと、ほかの水族館もイルカのショーをやるということで希少性が薄れている。様々な団体とか、哺乳類の飼育事情もあるというようなことをお伺いしたのですけれども、そういった認識で間違いないか尋ねました。","respondent":"大友公園課長","answer":"イルカの展示とイルカショーの廃止につきましては、今、委員のほうからご説明いただいたところが主な方向性です。そのとおりです。","id":"exchange-097"},{"speaker":"やなぎさわ委員","kind":"質問","question":"イルカにやはり人気があって、新しい目玉ということで、差別化を図る意味でもカワウソが非常に有効ではないかというふうに思っております。ぜひ、最後に何かあれば、答弁をお願いします。","respondent":"大友公園課長","answer":"展示の目玉というところにつきましてなのですけれども、令和４年３月に策定いたしましたしながわ水族館のリニューアルの方向性というものがあります。現在、この方向性に基づいた検討をしています。","id":"exchange-098"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"荏原ですとか大崎ルートの要望もあるということで、さらにそれもどうなるか、運行されても時間がかかるかなという状況だと思います。そういったことも検討していただければなと思うのですが、その点、いかがか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"は走りながらやるということ、試行運行ということ、様々な経験値を獲得しています。ハイエース、いずれにしろ総合的に考えて検討してまいりたいと考えています。","id":"exchange-099"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"昨今、やはり民間のバスの本数が減少しているということで、区民の方から苦情といいますか、要望を聞いております。交通難民を増やさないためにも、ぜひ区が主体となって交通整備をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、３４９ページ、避難道路機能強化事業、３６５ページ、区営住宅管理費、この２点をお伺いしたいと思います。その後どうなっているのか、その辺をお聞きしたいと思います。","respondent":"高梨都市計画課長、川原住宅課長","answer":"一番南側の桐畑隧道の部分につきましては、補助３１号線という都市計画道路に位置づけがされてあります。この部分の拡幅も視野に、安全な広域避難場所への避難というところの計画と合わせて検討を進めていく必要があるというふうに認識… そして、劣化状況調査を実施いたしまして、今後については、計画的な維持管理としては、屋上の防水工事の実施予定しています。","id":"exchange-101"},{"speaker":"こんの委員","kind":"質問・要望","question":"３１号線という考え方も必要ですけれども、そもそも隧道の在り方というところを、私はこれまでも何回も質問を上げさせていただいてまいりました。３１号線という考え方はありますけれども、そこだけの避難経路としての改善はできるのではないかと考えるところですが、いかがか尋ねました。","respondent":"森道路課長","answer":"道路課のほうで昨年度も少し検討させていただきまして、一直線にとれるかという検討をした結果、とれないというようなところでございました。そういった部分も含めて、引き続き、どういったところが安全かということは検討していきたいと思います。","id":"exchange-102"},{"speaker":"のだて委員","kind":"質問・要望","question":"２.５ｍ以下の私道も、住民の負担なしで私道整備ができるようにしてほしいと求めましたが、いかがでしょうか。その割合を伺います。","respondent":"森建築課長","answer":"傷みが大きいということで１００％助成、２.５ｍを切るところにつきましては１割負担していただくというところで、実施しております。実績についてですけれども、９件中２件が１割負担をしていただいた工事ということになってあります。","id":"exchange-103"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひこうしたところで２.５ｍ以下の私道でも負担がないように整備できるようにしていただきたいと改めて求めたいと思いますが、いかがでしょうか。そして、この幅の要件をつけた理由を伺いたいと思います。","respondent":"森建築課長","answer":"あるいは２割負担を求めている、１００％であっても、様々あります。２３区の中でも、そこまで問題がない状況ですので、受益者負担として１割負担していただきたいというふうに考えてあります。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそうしたところも、ほかの市道も負担なしで整備できるようにしていただきたいと、これは要望しておきたいと思います。これはどういうときに利用できる制度なのか伺います。","respondent":"伊藤災害対策担当課長","answer":"１点目が、もう１件は、福祉について支払ってあります。入院をして７日以上でないと支払われないといったようなものになりますので、随時、報告を受ける消防署と連携をして進めていきたいと考えております。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問・要望","question":"この補償について、近年の利用実績を伺います。安心して活動ができるように、消防団の活動でけがをした際には補償が利用できるようにしてほしいと求めましたが、いかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"けがをされたとしても、入院であれば７日以上の入院日数が必要だというような状況ですので、なかなか利用については難しいような状況です。引き続き、消防庁ならびに消防署と連携をしまして、こういったご意見があるということを共有してまいりたいと感じております。","id":"exchange-106"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそうした面でも、区としても利用できるようにしてほしいと求めました。なので、先ほど紹介した肉離れですとか腰痛の場合にも、これは対象になるというふうに思うのですが、いかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"まず１点目、先ほど１２件と申しましたが、疾病をされた方も含まれていることをご承知おきください。７日以上の入院が必要だというようなことになっておりますので、また、この情報については共有をさせていただきたいと存じます。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問・要望","question":"次に、リニア新幹線について伺います。事実上の河川管理者である区も認識していると聞いていますが、この気泡の発生を確認したのはいつなのか、現在も気泡は発生しているのか伺います。","respondent":"北原河川下水道課長","answer":"８月５日にＪＲ東海より、８月２日から御嶽橋下流付近にて、区としても把握に努めております。今月７日にも確認をしています。","id":"exchange-108"},{"speaker":"のだて委員","kind":"質問・要望","question":"酸素が少ない空気だということが分かって、世田谷区に成分調査を要望し、区が事業者に実施を求めて成分調査が行われました。目黒川で発生している気泡の成分調査をすべきだと思いますが、いかがか尋ねました。","respondent":"北原河川下水道課長","answer":"ＪＲ東海より、リニアの原因ということではなく、実質的な判断で気泡の成分調査を実施中というふうに聞いておりまして、区としても状況を注視してまいりたいと思います。","id":"exchange-109"},{"speaker":"のだて委員","kind":"質問・要望","question":"水面だから発生が分かったわけですけれども、地下室などに酸欠空気がたまっていれば、そこでも被害が出る可能性があります。そうしたことも含めて、しっかり調査をして明らかにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"石田（し）委員","kind":"質問","question":"以前お話をしましたが、区民公園内のバーベキュー場の喫煙所についてお伺いします。改めて、この件について、どのような認識なのか説明を求めました。","respondent":"大友公園課長","answer":"管理等々、鬱蒼としてというところにつきましては、現状、管理を適正に、というところのご指摘として受け止めていきたいと考えているところです。一定の時間、周辺や利用者の方々の意見も聞きながら、検討をさらに進めてまいりたいと考えているところです。","id":"exchange-111"},{"speaker":"石田（し）委員","kind":"質問","question":"五反田駅周辺地区コーディネートでありますが、これは平成２０年ぐらいからずっとやられていると思います。今回の令和５年度のコーディネートについて、どのようなことをやられたのか説明を求めました。","respondent":"中道都市開発課長","answer":"現在、五反田駅の東口に、準備組合があります。そういったところで、商店街または町会、または、その地域の関係者の方々と、五反田駅の周辺のまちづくりの方向性について意見交換を交わしています。","id":"exchange-112"},{"speaker":"石田（し）委員","kind":"質問","question":"どうしたんだという心配の声もありながら、この間、どのように把握をしていたのか。どのような対策を打ってきたのか説明を求めました。","respondent":"中道都市開発課長","answer":"ですので、今、コーディネートという形で、地域の方々と意見を交わして、こういった周辺のまちづくりをどうしていくかということを、検討しています。","id":"exchange-113"},{"speaker":"石田（し）委員","kind":"質問","question":"ということは、ＴＯＣのことについては、区は一切把握をしていなかったということでよろしいのですか。その点を説明するよう求めました。","respondent":"中道都市開発課長","answer":"ＴＯＣのほうで、資材高騰によって新しい建物を建てるというところを中止するということは聞いてはおりました。より進めてほしいとかという、またさらに五反田ににぎわいをもたらしてほしいというところで、お願いという形でお話をしています。","id":"exchange-114"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひ情報も含めてしっかり連携をとっていただきたいなというふうに思います。五反田のまちをどのように考えているのか、どのような位置づけなのか、改めて説明を求めました。","respondent":"中道都市開発課長","answer":"区は認識していますので、予算の見せ方も、また検討していきたいというふうに考えてあります。やはりそういった高まりを見せておりますので、区としても、そういったお話を聞きながら支援をしていきたいと考えています。","id":"exchange-115"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"いろいろなものが出てきた、これはやはり１つにまとめて、区がどういうふうに地域の交通を考えていくのかということを考えるべきだと思うのです。これはぜひ、どのように地域で区民の皆さんが求めているのかということをぜひ考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"こういうことも考えていただいて、森林環境譲与税を使っていただきたいなと思って、その住宅改修のところで入れ込んでほしいなと考えています。あそこのＢＭＸでも何でも、ぜひそういうことも全体を見ながら考えていただきたいなと思っているので、そこの考え方を説明するよう求めました。","respondent":"伊藤災害対策担当課長、川原住宅課長、山下交通安全担当課長","answer":"今回、新たなコンテンツを導入しました訓練としまして、５か所での実施を考えてあります。例えば、そういったところからいろいろ切り崩しと申しますか… 令和５年の申請の内容を見ますと、内装材については、実際、件数としては４件ということで、まだ非常に少ないところです。エコの高断熱浴槽であるとか… 実情、確かに広く十分敷地もありますし、車も撤去車も十分停めておける状況です。","id":"exchange-117"},{"speaker":"石田（秀）委員","kind":"提案","question":"森林環境譲与税は、具体的に提案をしますので、よろしくお願いします。ありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-118"},{"speaker":"田中委員","kind":"質問・要望","question":"今定例会でも９月２４日に総務委員会に付託され、全会一致だったでしょうか、採択されていますので、本会議において議決される予定となっております。いわゆる空き家、先ほど、空き家が全体で５４０件というふうに伺っておりますが。","respondent":"川原住宅課長","answer":"６月の空き家の審議会でもお諮りしていた案件なのですけれども、現在、区の職員が何年もかけて対応させていただいているところです。８月末現在１３３戸あります。","id":"exchange-119"},{"speaker":"田中委員","kind":"確認","question":"それぞれ空き家対策の成果として、令和５年度に確認された特定空き家等は、もう除却の方向で、しっかり対処していただいているという状況であります。もう一気に対象にしてもよいのだろうというふうな思いがありますが、その点について、どのようにお考えか尋ねました。","respondent":"川原住宅課長","answer":"適正ではない管理不全空き家等という形で認定をしてまいりたいところですが、全ての戸数というところは、現在は考えてございません。そのような措置をしないと、まずは少しずつ対応を行うことによって、そういったところも見ながら検討してまいりたいというふうに考えてあります。","id":"exchange-120"},{"speaker":"田中委員","kind":"質問・要望","question":"料金を下げてほしいという、あと、新しい停留所をつくってほしいという声があります。私は大いなる疑問を感じておりますが、僅かですが、ご感想をお聞かせほしいと求めました。","respondent":"櫻木地域交通政策課長","answer":"大井第三地区の代表としてご意見を聴取させていただきまして、今後もう少し幅広く意見を聞けるような形で考えていきたいと考えています。","id":"exchange-121"},{"speaker":"吉田委員","kind":"質問","question":"それからもう１つが、３４３ページ、治水対策推進助成事業について伺います。区として、音響信号機の設置を進める手順をまず伺います。","respondent":"山下交通安全担当課長","answer":"音響式信号機の設置の関係ですが、所管が警察署になりますので、最終的には警察署のほうに要望するという形でいつも進めているところです。","id":"exchange-122"},{"speaker":"吉田委員","kind":"提案","question":"どういう形か、そこをつないでくださるというか、そう考えてよろしいのでしょうか。もう一度確認させてくださいとの意見を述べました。","respondent":"山下交通安全担当課長","answer":"ぜひ私のところに言っていただければ、警察署のほうには、私も警察官ですので、積極的にご意見、ご要望は伝えていきたいと考えています。","id":"exchange-123"},{"speaker":"吉田委員","kind":"質問・要望","question":"視覚障害者の方からそういうご要望をいただいたときには、課長がきちんとお答えくださったので、安心して意見を言うようにというふうにお伝えします。手話通訳者の手配についても、同様に考えてよろしいのでしょうか、確認したいと求めました。","respondent":"山下交通安全担当課長","answer":"手話通訳につきましては、それぞれの警察署に常時配置しているわけではございませんので、やはり手配が必要になってくると思います。当日は、ある程度、後日また手話の方と一緒にお話を深くまで聞いていくというような段取りでやっているというふうに認識しています。","id":"exchange-124"},{"speaker":"吉田委員","kind":"質問・要望","question":"交通事故に遭った聴覚障害者の方が、自分たちは被害者なのに、加害者のほうの意見ばかり警察官が聞いて、自分たちには筆談を求められた。どういう形で連絡しても、ぜひ警察の中に広めていっていただきたいと思うのですが、いかがか尋ねました。","respondent":"山下交通安全担当課長","answer":"貴重なご意見ですので、私も警察署に立ち寄ったときですとか、また、警察署に戻ったときにでも、そういった話はぜひ広めていきたいと考えていますし、私もそういう警察官が育つような環境で、しっかり部下を指導できるような人間になっていきたいと考えています。","id":"exchange-125"},{"speaker":"吉田委員","kind":"質問・要望","question":"主体的にその辺のことをきちんと障害者への配慮ということを進めてほしいということをしっかりお伝えほしいと求めました。タンク助成の２０２３年度の実績を伺います。","respondent":"北原河川下水道課長","answer":"令和５年度の実績については、２件になります。","id":"exchange-126"},{"speaker":"吉田委員","kind":"質問・要望","question":"チラシの書き方がまずいのではないのかということと、それから、チラシをどこに置いてあるのですかということを伺ってきたと思います。ぜひそれは検討していただきたいのですけれども、いかがか尋ねました。","respondent":"北原河川下水道課長","answer":"チラシの記載についてですけれども、現在は、できるだけ受け取った方にとってプラスに見えるような形で記載をしてきているところです。ただ、いただいたご意見も踏まえて、よりよいチラシについても研究をして改善をしていきたいと考えております。","id":"exchange-127"},{"speaker":"吉田委員","kind":"質問・要望","question":"なぜ浸水被害の抑制になるのかというところは、川の水が汚いのも、あなたの生活排水が川に流れ込んでしまう。少し詳細に説明するような形を、もう少し別の形で考えていただきたいと思うのですが、いかがか尋ねました。","respondent":"北原河川下水道課長","answer":"どういうふうに役立つか知ってもらうということが大事だと思っていますので、様々な啓発を考えてきているところです。昨年度から展示を２週間程度やったり、こういった助成金を使っていただけるように、きちんと広報をやってまいりたいと思っています。","id":"exchange-128"},{"speaker":"吉田委員","kind":"質問・要望","question":"私の要望がだんだん浸透してきているようなので、そういうことにつながるのだということを、もう少し分かりやすく表現をしてほしいと求めました。私たちも協力したいと思いますので、ぜひこれからも合流改善という視点を入れたチラシの作成とか情報提供を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-129"},{"speaker":"若林委員","kind":"確認","question":"３６５ページの居住支援事業の中で、居住支援相談会についてお尋ねします。実績は３件というふうに事務事業評価シートで確認済みですので、それから相談を受ける側はどういう、こういった点をまずお聞きいたします。","respondent":"川原住宅課長","answer":"令和５年度の居住支援相談会の内容についてご説明いたします。成果としては、やはり今後も、その方に寄り添った支援が必要であるというふうに認識をしています。","id":"exchange-130"},{"speaker":"若林委員","kind":"質問","question":"令和６年度、今年度も同様２回の予算が組まれております。２回、いつ行われるのかということが１つと、これから工夫をしようとしていることがあるのかどうかについてお聞きします。","respondent":"川原住宅課長","answer":"年内に１回を予定してございまして、あとは翌年、令和７年に１回、２月までにはもう１回実施をしたいというふうに考えているところです。今後は、高齢者の方に寄り添った支援の専門の有識のある介護事業者の方のサポートもいただきながら、居住支援相談会の開催を検討しています。","id":"exchange-131"},{"speaker":"若林委員","kind":"質問","question":"２年度にして様々な工夫の手が入っているということで評価いたします。年２回やられるということなのですが、そのための予算措置について、どういうふうに担保されているのかお聞きします。","respondent":"川原住宅課長","answer":"この辺りは財政の担当のほうにも、協議をするところです。そして、来年度さらに居住支援の強化というところで、区の福祉サービスだけでは行えない個別の支援も拡充できるというふうに考えているところです。","id":"exchange-132"},{"speaker":"若林委員","kind":"質問・要望","question":"速やかな予算措置を行っていただきたいというふうに要望します。もうお話を伺っていますので、どのような予算を組み浚渫を行うのか、ここは確認します。","respondent":"北原河川下水道課長","answer":"東京都で浚渫を実施するというふうに聞いておりますので、我々のほうも支障物処理と浚渫をやっていくというふうに考えてあります。引き続きどういったやそり方がいいか考えてまいりたいと考えています。","id":"exchange-133"},{"speaker":"西本委員","kind":"質問","question":"ですから、途中、変わっているのですよね。ここの中には庁舎の建て替えも入っていますので、その辺をお聞きしたいと思います。","respondent":"中道都市開発課長","answer":"多様なニーズに対応すべく、住宅といった多機能な拠点整備を形成して、そこに対して新たなにぎわいを創出していきたいです。ＪＲと区では、役割は分担しつつ、そういった新たなにぎわいを創出していきたいというふうに考えてあります。","id":"exchange-134"},{"speaker":"西本委員","kind":"質問","question":"どういう分担になるのでしょうか。そうすると、今までの考えてきたことをもう少し広げていかないと、非常に難しいような状況だと思いますが、その辺はいかがか尋ねました。","respondent":"中道都市開発課長","answer":"現在、区としましては、地域の町会、商店街、また、阪急、イトーヨーカドー、ＮＰＯまちづくり大井など、そういった方々と検討会を行ってあります。","id":"exchange-135"},{"speaker":"西本委員","kind":"意見","question":"それらと関連すると、なかなか全体的にどうやって今後進めようとされているのか。今、いろいろ検討されておりますけれども、どういう方向に持っていこうとするのかをぜひ説明を求めました。","respondent":"泉広町事業調整担当課長","answer":"昨年度から庁舎跡地等活用検討委員会、公募区民の方々と考えてまいりまして、そのようなところを導き出されてきたというところになってあります。策定に当たりましては、地域全体のにぎわいが創出されるような形でのまちづくりを目指していくというところで考えてあります。","id":"exchange-136"},{"speaker":"西本委員","kind":"質問","question":"ですから、先ほど言っているように、このＪＲの再開発とどうリンクしていくのですかという話です。少し違うものになりはしないかということを言っているので、そこのコラボレーションの仕方とか、考え方を説明するよう求めました。","respondent":"泉広町事業調整担当課長","answer":"ＪＲ東日本と連携しながら話を進めてきておりまして、例えば、そういうところはかねてからやってきたところです。ＪＲの開発をしっかりと踏まえまして、どういったところが適切かというところを、引き続き段階的に検討してまいりたいと考えています。","id":"exchange-137"},{"speaker":"西本委員","kind":"意見","question":"その中で、皆さんに忘れてほしくないのは、今まで中央公園をどういう人たちが利用されているのか、ここ、家族の人たちが非常にいっぱい来るのです。当然考えていると思いますけれども、現状を含めて、どういうふうな方向性でにぎわいゾーンを創出していこうとしているのか説明を求めました。","respondent":"泉広町事業調整担当課長","answer":"今ございましたしながわ中央公園、非常に地域の方から親しまれているというところは、区としてもしっかり認識しています。減らすといったところは前提にせず事業を進めているところでございまして、一定、にぎわいを創出したいと思ってあります。","id":"exchange-138"},{"speaker":"高橋（伸）委員","kind":"質問","question":"３６５ページ、空き家等対策事業、３３７ページ、人孔蓋枠等整備工事、時間があれば、３４３ページ、治水対策推進助成事業についてお伺いいたします。最初に、３６５ページ、空き家等対策事業についてお伺いいたします。","respondent":"川原住宅課長","answer":"不適正管理状態というものは、そのうち１割に満ちておりません。約５９戸、改善も含めて、指導の上、適正管理に至ったものが５９０戸という形です。","id":"exchange-139"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そこで、例えば、同じ敷地内に４棟あって、１棟がまだご家族が暮らしていて、それも管理不全に値するところ。空き家が３棟あったときに、同じ敷地内に４棟あったときは、カウントとして、どういうカウントをとるのか説明を求めました。","respondent":"川原住宅課長","answer":"例えば、枝の越境であるとか、そういった緑のものが隣家に越えてしまったというものも含めさせていただいているものです。空き家が３棟、非居住家屋であれば１棟という形で、別でカウントをしています。","id":"exchange-140"},{"speaker":"高橋（伸）委員","kind":"確認","question":"やはり私が思っているのが、空き家、所有者が当然いるわけではないですか。それは区の職員の方がやらなければいけないものなのかなと私はそういうふうに思っているのですけれども、それで間違いないか確認したいと求めました。","respondent":"川原住宅課長","answer":"委員のご質疑にありました個人情報に係る部分は区の職員の管理になるかというご質問です。委員のご指摘のとおりです。","id":"exchange-141"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、３３７ページ、人孔蓋枠等整備工事についてお伺いいたします。区内に８か所あると私は認識しているのですが、その確認と、しながわ観光協会でマンホールカードを配布をしているかと思います。","respondent":"森道路課長","answer":"デザインマンホールにつきましては、委員ご指摘のとおり、８種類を設置しておりまして、そのうち２種類をマンホールカードとして配布しています。","id":"exchange-142"},{"speaker":"高橋（伸）委員","kind":"確認","question":"その８か所が、大井町が２か所、マンホールを設置するところがあるのかどうか確認したいと求めました。","respondent":"森道路課長","answer":"今、例を挙げていただきました箇所について設置をしております。ここに設置をしようというところはございませんけれども、歩道上にどうしても設置をする必要がありますが、そういったところの適地があれば。","id":"exchange-143"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"大井町のこれからに向けて、それも１つのにぎわいの創出にもなると思いますので、ぜひこれは要望とします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-144"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"３３３ページ、交通安全啓発費になるでしょうか。花海道が併設される、そして学校通学路との関係、その辺りの安全対策を学校との連携をしっかりしていただきたいのですが、いかがか尋ねました。","respondent":"山下交通安全担当課長、大友公園課長、森道路課長","answer":"歩行者用信号機の秒数の関係ですが、歩行者用信号機につきましては、基本的には横断歩道の距離に応じて一定の秒数が設定されているところです。ただ… 引き続き、防砂効果を保ちながら、観戦がしやすい手法を検討してまいりたいと考えているところです。続きまして… 勝島人道橋の説明会は、９月２６日に行いましたけれども、５３名の方からご参加いただきましてご意見をいただきました。","id":"exchange-145"},{"speaker":"高橋（し）委員","kind":"質問","question":"今年の６月の補正予算でトイレトラックを導入することになったということで、これは大変すばらしい施策で、早急に納車されるといいと思います。このトイレは、何室あって、バリアフリートイレはどれぐらいあるのか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"こちらは、来年の２月末に納車予定ということで、今、準備を進めているところです。おむつ交換台であったり、オストメイト対応の設備等、そういったものが設置されているトイレトラックです。","id":"exchange-146"},{"speaker":"高橋（し）委員","kind":"質問","question":"このようなものが能登で活躍して、小さいお子さん、足の不自由な方、そして車椅子の方がお使いになって大変役に立ったというふうなことを伺いました。そして来年も４台、１０台と購入がありますが、このようなものを導入するということはいかがか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"現在は、２２自治体で助けあいジャパンからトイレトラックを導入しているという状況です。そういった災害派遣トイレネットワークを活用して、被災地に派遣、品川が被災したときは受援を受ける、そういった体制を組んでいるところです。","id":"exchange-147"},{"speaker":"松本委員","kind":"質問","question":"私からは、３３５ページ、道路維持費、３３７ページ、道路改良費、３７１ページ、貯水槽等維持管理費について順不同で伺います。区が所有していないとしたら誰が所有しているのか、また、管理は誰がどのように行っているのか伺います。","respondent":"羽鳥防災体制整備担当課長","answer":"委員おっしゃられたとおり、区内に１,８００基以上の防火水槽が設置しています。それ以外のものは、消防であったり、民間が所有管理しているという状況です。","id":"exchange-148"},{"speaker":"松本委員","kind":"質問・要望","question":"２枚目のほうの防火水槽の標識というものを見ていただきたいのですけれども、水槽がここにあるということが分かるでしょうかというところなのです。この点について、区としてどのようにお考えか伺います。","respondent":"羽鳥防災体制整備担当課長","answer":"こちらの防火水槽に関しましては、東京消防庁が所有し、東京消防庁が管理しているもので、幼稚園の私有地の中に設置させていただいているものです。","id":"exchange-149"},{"speaker":"松本委員","kind":"質問","question":"２回も見に行っていただいたということで、感謝申し上げます。今のところ、ゲートが閉まっている点については、どう考えればよいか伺えればと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"ゲートが閉まっているですけれど、今回、私有地の中に防火水槽を設置しているという状況ですので、そういったところは、東京消防庁と施設管理者のほうで、今後、どのような対応がいいかということを、また話を詰めていくのかなというふうに思っております。","id":"exchange-150"},{"speaker":"松本委員","kind":"質問・要望","question":"次に、道路管理なのですけれども、昨日の産業経済費で商店街の街路灯について伺いました。１ｍぐらいの距離に、区のほうの街路灯を切ることによって電気代を抑えられるのではないかなというふうに思うのですが、この点はいかがか尋ねました。","respondent":"森道路課長","answer":"道路課でも、商店街灯と街路灯が近接してあるというところは幾つかあるというふうに認識しております。区の街路灯は、確かに見た感じはダブっているようには見えるかなと思いますけれども、それぞれの目的で進めていければと考えています。","id":"exchange-151"},{"speaker":"松本委員","kind":"質問・要望","question":"最後は要望だけになってしまうかもしれませんが、１枚目の写真、これは区民の方からご提供いただいた写真です。道路の側溝を含めて、これから区としても今後の対応についてもぜひお願いしたいと思い、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-152"},{"speaker":"須貝委員","kind":"質問","question":"災害時に、このようなトイレトラックのような設備は必要だと思うのですが、いかがでしょうか。暗い、そこは電気を通せばなるのでしょうが、もうそういう時代ではないのではないか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"最悪の場合は、災害関連死につながることもありますので、トイレも含めて避難所の生活衛生環境の改善は重要な課題だというふうに認識しています。実際に見て、触れていただける、そういった機会を設けてまいりたいというふうに考えてあります。","id":"exchange-153"},{"speaker":"須貝委員","kind":"意見","question":"これ、１基や２基あってもどうしようもない。そういうことも考えるべきだと思うのですが、その辺について、ご見解を説明するよう求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"そういったところで、現状、各自治体、導入しているところも、それぞれ１台ずつということになっています。助け合いの輪が今後広がっていく、そういったことが重要なのかなというふうに考えてあります。","id":"exchange-154"},{"speaker":"須貝委員","kind":"質問・要望","question":"そして、品川区だけ集中して２０基でも３０基、いや、５０基でも持ってきてくれるのですか。被災民のまた強い要望でもあるこういうトイレトラックのような設備を備えて、１,２００回分しか使えなかったら、トイレトラック。","respondent":"羽鳥防災体制整備担当課長","answer":"緊急車両等、あと支援物資の輸送の車両等が通れるように対策はとられるものということで認識しています。参加自治体が増えれば、さらに経験値が積み上がって、品川区の支援にもつながるものと期待しています。","id":"exchange-155"},{"speaker":"須貝委員","kind":"質問","question":"私は、閉じ込められて、では、この方たち、体は大丈夫なのですか。それが確実にどこかで止まって、そして人を救出できるということを最優先にやるべきだと思うのですが、ご見解を説明するよう求めました。","respondent":"平原防災課長","answer":"委員ご指摘の、まさにその前にやることは、管理組合がやるべきことだと思ってあります。まずは、災害時にどういうことになるのか、そういったところをしっかりお考えいただいた上で対策をとっていただくことが第一義だと考えています。","id":"exchange-156"},{"speaker":"須貝委員","kind":"質問","question":"そうしたら、こういうことを積極的に教えるのは区ではないのですか。指導するということが、区としての立場だと思うのですが、いかがか尋ねました。","respondent":"平原防災課長","answer":"まず、東京都が事業を推進するに当たっては、東京都が積極的にまず周知広報すべきものというふうに考えてあります。その上で、区といたしましては、マンション防災の在り方という点の中で、そういったものも含めて周知啓発するというような立場です。","id":"exchange-157"},{"speaker":"須貝委員","kind":"質問","question":"そこに救援に行くのですか。もう一度ご見解を説明するよう求めました。","respondent":"平原防災課長","answer":"そういう中で、マンション防災全体というもので、エレベーターだけではありません。そういったところをしっかりと考えていただくといったところが重要かなというふうに区の立場では考えてあります。","id":"exchange-158"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、しっかりやはり普及啓発を図って、こういう安全装置を一刻も早く皆さんにつけていただくように、普及啓発のために、推進、そして指導してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-159"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、３５３ページ、品川駅南地域周辺まちづくり事業について伺いたいと思います。地権者数、土地所有権利者、借地権者、そして計画に関わる世帯数を伺います。","respondent":"大石まちづくり立体化担当課長","answer":"最後、南地区ですが、権利者数といたしましては９１名、うち土地所有者数といたしましては３９名、借地権者といたしましては５２名となっています。なお、宅地数については、現在、把握していないところです。","id":"exchange-160"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"北街区、西街区となっていますが、それぞれの事業面積を街区別で教えていただきたい。準備組合も立ち上がっていますので、準備組合加入者数も説明を求めました。","respondent":"大石まちづくり立体化担当課長","answer":"いわゆる今検討している面積になりますが、品川駅寄りの北地区につきましては、約６haとなっています。次に、準備組合の加入者数ですが、こちらは各準備組合に確認したところ、いずれも非公表とのことです。","id":"exchange-161"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それぞれ、これも街区別に企業名を伺いたいと思います。それと、総事業費、あと補助金がどれぐらい入るのか、見込みでも想定でもいいので教えてほしいと求めました。","respondent":"大石まちづくり立体化担当課長","answer":"各準備組合により、まちづくり検討が行われている状況でございまして、まだ事業化されている段階ではございません。このため、総事業費、補助金等も、見込みといえども現時点では未定です。","id":"exchange-162"},{"speaker":"石田（ち）委員","kind":"質問","question":"この辺の道路の架け替えなどもあるのかなというように見てとれるのですけれども、この新たな人道橋の建設や道路の架け替えがあるのでしょうか。伺います。","respondent":"大石まちづくり立体化担当課長","answer":"検討が進められている地区内には、補助１４９号線と、補助１６２号線という２本の都市計画道路があります。その中で都市計画道路の在り方についても検討がなされているものと認識しています。","id":"exchange-163"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ住民に、準備組合の情報を区から住民に情報を出していただきたいと思うのです。準備組合に入っていない権利者に、区から情報を出すべきだと思いますけれども、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"検討されている情報につきましては、最終的に準備組合が情報を発出するしないかというところは、判断はそちら側になると考えています。ただ一方で、再開発準備組合との調整はありますけれども、そういった形で不安の解消に努めていきたいと考えているところです。","id":"exchange-164"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"なので、平等に情報は入れるべきだと思います。反対する区民にも寄り添ってほしい、進めないでほしいという声が本当に強く届いておりますので、区から地権者に出すように強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-165"},{"speaker":"大倉委員","kind":"質問・要望","question":"３６７ページの区内一斉防災訓練、３３３ページ、放置自転車対策事業で伺います。様々活用していっていただきたいと思っていますというところで、管理して、どのような流れになっているのか説明を求めました。","respondent":"平原防災課長、山下交通安全担当課長","answer":"検討をしていくということで考えているところですが、ＳＮＳアプリなどを活用して、まずは導入することを検討しています。同時に、国のほうでもマイナンバーカードを活用した避難所のシステム開発も進んでございまして… 撤去しました自転車については、国道１号より西側が不動前、東側につきましては八潮北の保管所に保管する形となっております。","id":"exchange-166"},{"speaker":"大倉委員","kind":"質問・要望","question":"改めて確認ですが、具体的にどうやって登録されていくのかということについて、分かれば教えてください。その確認の方法、登録しましたよという確認の方法をどうするのか説明を求めました。","respondent":"平原防災課長、山下交通安全担当課長","answer":"単に紙で書く、その手間がなくなったといったところで、行列の縮減効果があるといったところです。被災者台帳に入力する際、現状では、マイナンバーを使わない限りでは、最終的には手入力という形になるというふうに認識しています。自転車駐輪場の利用料金もキャッシュレス化していますので、こちらのほうも今後に向けて検討していく必要はあるのかなと考えているところです。","id":"exchange-167"},{"speaker":"あくつ委員","kind":"質問・要望","question":"３６９ページ、防災体制整備費、そして３３９ページ、橋梁管理費から伺ってまいります。その代表質問においては、必要な資機材の確保や円滑な避難所運営のための支援など、国が前面に立って進めることを求めています。","respondent":"羽鳥防災体制整備担当課長","answer":"災害時のトイレ問題は非常に重要な課題であるというふうに認識しています。避難者の命や尊厳を守るためにも、災害時のトイレ対策について、品川区といたしましても取り組んでまいりたいというふうに考えてあります。","id":"exchange-168"},{"speaker":"あくつ委員","kind":"質問・要望","question":"改めて伺いますけれども、災害関連死を防ぎ、品川区としての具体的な災害時のトイレ確保・管理計画を策定していただけないでしょうか。併せて、実務的な意味でのトイレ対応の責任者の設置をお願いしたいと思いますが、いかがか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"トイレトラックの運用方法も整理をさせていただきながら、策定に向けて具体的に検討してまいりたいというふうに考えてあります。その中で、しっかりトイレ対応ができるような体制はとってまいりたいというふうに考えてあります。","id":"exchange-169"},{"speaker":"あくつ委員","kind":"質問","question":"伺います。これまで都市計画課であったと思うのですけれども、少し変わったというふうに伺っておりますが、その理由について説明を求めました。","respondent":"櫻木地域交通政策課長","answer":"開催回数は、これまで３回で、１回目は令和３年１２月、２回目は令和５年２月、３回目は令和６年７月となります。それが当課に移管されて、開発が絡まない鉄道駅のバリアフリー化については、当課が対応しているものです。","id":"exchange-170"},{"speaker":"あくつ委員","kind":"質問","question":"特に直近の７月の第３回目の中身、そして、どのようなことが決まったのか教えてください。意気込み、つまり、バリアフリー化が具体的に前進している感触を得たのか説明を求めました。","respondent":"櫻木地域交通政策課長","answer":"私も幾度となく現地を確認して、現状のままでは地域の皆様が非常に使いづらい不便な状況にあるという認識は改めて感じております。早く対応が進むように、また、品川区としても必要な協力は積極的にするという態度で臨んでいるところです。","id":"exchange-171"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう少しですからということで。聞かないものですから、そういう方だけではなくて、地域の方の声をしっかり聞いていただくよう求めました。","respondent":"櫻木地域交通政策課長","answer":"委員ご指摘のとおり、個別の施設の意見だけではなくて、地元の意見をまずはしっかりと聞いてほしい、説明してほしいということを区からは申し入れていきたいと考えています。","id":"exchange-172"},{"speaker":"まつざわ委員","kind":"確認","question":"地域交通検討経費につきましては、事務事業概要で、全体の執行率９２％、効率的に予算が執行されたことは確認いたしました。この数字をまずはどう評価しているのか説明を求めました。","respondent":"櫻木地域交通政策課長","answer":"西大井循環ルートを外すなどのルート変更、新しいモビリティの登場等、様々計画策定時とは想定と異なった状況になっていると認識しております。","id":"exchange-173"},{"speaker":"まつざわ委員","kind":"質問","question":"これは昨年度の令和５年度から検討していくという部分でありますけれども、これが一体どういう検討がなされているのかお聞きします。ＡＩオンデマンドの交通導入によって、一体品川区にどのような効果が期待できるのか、それを説明するよう求めました。","respondent":"櫻木地域交通政策課長","answer":"課題としましては、構造上の交通を阻害しないような場所に設定することが、なかなか区内の狭隘な道路では難しいということが挙げられます。まだ検討がまとまった段階ではございませんが、まとまり次第、速やかにスケジュール等をお示しできればと考えています。","id":"exchange-174"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"石田しんご委員からもありました、コミュニティバスとオンデマンドなど、私も地域交通の全体を考えていていただきたいです。そういった先の運行計画を立てる際にも、やはり地域住民は必ず計画の中に入れてほしいと求めましたけれども、ご見解を説明するよう求めました。","respondent":"櫻木地域交通政策課長","answer":"運行について、地域住民を含めて検討です。あらかじめ地域の皆様にご説明をするとともに、その際にミーティングポイントの設置等のご要望等も伺えればと考えております。","id":"exchange-175"},{"speaker":"まつざわ委員","kind":"質問","question":"先ほどもありました、３日から７日間、１週間は備蓄をするようにしましょうと。これによって備蓄の積み増しが多分起こってくると思うのですが、区における備蓄の状況、今後の計画を、示すよう求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"不足する部分は、区によるプッシュ型の支援であったり、民間事業者の協力などを得ながら対応してまいりたいというふうに考えてあります。一方で、区といたしましては、今後、女性や子ども視点の物資など、質的な充実についても対応してまいりたいというふうに考えてあります。","id":"exchange-176"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"足りない部分は協力して、事業所などでやっていただきたい。品川区だけではないから、すぐに支援につながらない場合も考えられると思うのですが、その辺りの見解を説明するよう求めました。","respondent":"平原防災課長","answer":"協定事業者が被災している場合などが考えられまして、同業の複数の事業者と協定を結ぶなど、そういった時点で得られる勢力を結集して災害対策を行うことを計画しているものです。","id":"exchange-177"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"それが町会同士でできないのだったら、そこの部分を行政が助けていただくということは、本当に大切だと思っています。そこで、この新しい共助というものに対する区の考え方を教えていただきたい。","respondent":"平原防災課長","answer":"災害が発生した後は公助が届きづらいということで、共助の役割が非常に重要だというふうに私ども認識しております。そういうような取組が進んでいくと、後々区が入らなくても、どんどんと災害時の助け合いの取組が広がっていくものというふうに考えているところです。","id":"exchange-178"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ぜひ難しい、つながりとつながりのないところをつなげるきっかけ、これはぜひ行政でもまずやっていただきたいと考えています。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-179"},{"speaker":"石田（し）委員","kind":"確認","question":"こんな時間なので手短にしますが、１点確認させてください。私の認識どおりで間違いがないかを確認したいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-180"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/285407?Template=document&Id=6857#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":123078,"voices":412}},{"id":"r06-20241010-5","meetingId":"r06-cm10","date":"2024年10月10日","dateIso":"2024-10-10","committee":"総務委員会","time":"午後 １時１８分～午後 １時４４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件整理しています。","topics":[{"id":"topic-01","title":"議案審査および予定表２、報告事項を行います。 第８６号議案、令和６年度品川区一般会計補正予算、および令和６年１０月２７日執行 衆議院議員選挙（東京都第三区）…","agenda":"議案審査および予定表２、報告事項を行います。 第８６号議案、令和６年度品川区一般会計補正予算、および令和６年１０月２７日執行 衆議院議員選挙（東京都第三区）…","exchanges":[{"speaker":"西本委員","kind":"質問","question":"そういう流れになるべきではないのかと思うのですが、まず、その１点。それから、事前ポスター、たくさん貼ってありますけれども、それの何が駄目で、何がいいのかというのを説明するよう求めました。","respondent":"今井選挙管理委員会事務局長","answer":"公示日というのが選挙運動の開始になりますので、公示日の前には、いわゆる選挙に関わるポスターというのは掲示できません。公示日１５日の段階で、先ほどの１５日の候補者の事前説明会の中でも、選挙管理委員会としても徹底してまいりたいと考えております。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問・要望","question":"事前ポスターの件なのですけれども、よく分からないのですが、選挙期間に入ったら、２連も駄目ですよね。２連が貼ってあるし、１連というか、選挙に入るまでに撤去していただくという認識でよろしいか尋ねました。","respondent":"今井選挙管理委員会事務局長","answer":"大変失礼いたしました。２連ポスターにつきましては、いわゆる掲示板、公営のポスター掲示場に１枚貼っていただくという形になっております。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問・要望","question":"結構巧妙にＳＮＳを使う陣営が多いですから、それはやはり公平ではないと思いますので、選挙管理委員会は注意喚起だけですから。取り締まることはできないので、十分その権限は分かっておりますが、ぜひ注意喚起をやってほしいと求めましたが、いかがか尋ねました。","respondent":"今井選挙管理委員会事務局長","answer":"事前説明会については東京都選挙管理委員会事務局でやっておりますので、それから、選挙管理委員会がもちろん注意喚起をする。警察のほうも選挙取締本部が設置されると思いますので、連携して対応していきたいと考えています。","id":"exchange-003"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"初めてＡ４サイズでホームページからダウンロードできる形で活用がされたと思いますが、また、少し教えてほしいと求めました。記述欄を設けてほしいということを要望させていただいておりましたが、改善があるのか、教えてほしいと求めました。","respondent":"今井選挙管理委員会事務局長","answer":"選挙管理委員にもご検討、ご協議いただきまして、投票支援カードは入場整理券を入れる封筒に同封することにしました。投票支援カードとともに、投票用紙の枠内に書きやすくする補助具の導入を検討しておりますので、障害者の方に使いやすく。","id":"exchange-004"},{"speaker":"西本委員","kind":"意見","question":"賛成ですが、先ほどもお願いしましたが、平等で透明性のある選挙になりますようにお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/837879?Template=document&Id=6843#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":8930,"voices":28}},{"id":"r06-20241010-10","meetingId":"r06-cm10","date":"2024年10月10日","dateIso":"2024-10-10","committee":"議会運営委員会","time":"午後 ２時２５分～午後 ２時２６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759442?Template=document&Id=6841#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":881,"voices":8}}]);
